static void usnap_read_x(uint64_t a, void *out, size_t n, int wait) {
    const usnap_t *c = wait ? usnap_find(a, n) : usnap_find_slow(a, n, 0);
    memcpy(out, c ? (const void *)(c->cpu + (a - c->lo)) : (const void *)(uintptr_t)a, n);
