/* TOTK: the value guest memory [a, a+n) will hold once this submission's pending writes (inline uniform updates,
   GPU copies) have executed: the replay needs it on the CPU for pointers the shader loads from a user uniform block.
   Returns 1 when a pending write supplied the bytes, 0 when memory is current (out is filled either way), -1 when a
   pending write overlaps only partly or the table overflowed (out = memory, which may be stale). */
static int pend_read(uint64_t a, void *out, size_t n, int depth) {
    for (int i = g_npend - 1; i >= 0; i--) {
        if (a >= g_pend_hi[i] || a + n <= g_pend_lo[i]) continue;
        if (a < g_pend_lo[i] || a + n > g_pend_hi[i]) { memcpy(out, (const void *)(uintptr_t)a, n); return -1; }
        if (g_pend_kind[i] == 0) { memcpy(out, (const uint8_t *)g_pend_src[i] + (a - g_pend_lo[i]), n); return 1; }
        uint64_t src = (uint64_t)(uintptr_t)g_pend_src[i] + (a - g_pend_lo[i]);
        if (depth < 4) { int r = pend_read(src, out, n, depth + 1); return r < 0 ? -1 : 1; }
