/* Reusing the open copy encoder needs a barrier between copies too: Metal 4 does not run the commands of one encoder in
   recording order, so a write then a read (or two writes) of the same range can swap (D2R Mobile 44a6770: without it a
   test read a stale value 1 time in 3). The barrier when the encoder opens only orders it against earlier encoders. On
   Metal 4 the copy encoder is a compute encoder, so both blit and dispatch stages are ordered. TOTK_BLIT_BAR=0: off. */
static int blit_bar_on(void) { static int v = -1; if (v < 0) { const char *e = getenv("TOTK_BLIT_BAR"); v = !e || atoi(e); } return v; }
static id<MTL4ComputeCommandEncoder> blit_kind(int buffer_alias) { blit_note(); if (!g_blit) { g_blit_opens++; g_blit_splits += g_enc != nil; } rp_end();
    if (buffer_alias && !g_copy_probe_no_alias) g_blit_alias = 1; // rp_end may itself open and close a copy encoder
    if (!g_blit) { rs_sync(); ser_gate(); pt_mark(g_cb, 'B', nil); g_blit = enc_b_begin(g_cb); [g_blit barrierAfterQueueStages:MTLStageAll beforeStages:MTLStageAll visibilityOptions:blit_vis()]; }
    else if (blit_bar_on()) [g_blit barrierAfterEncoderStages:MTLStageBlit | MTLStageDispatch beforeEncoderStages:MTLStageBlit | MTLStageDispatch visibilityOptions:blit_vis()];
    return g_blit; }
static id<MTL4ComputeCommandEncoder> blit(void) { return blit_kind(0); }
/* Buffer copies (mtl_sub_copy, the copy fallback of inline uniform updates). The same memory can be reached through two Metal
   buffers, each with its own GPU virtual address: a virtual pool's remapped view of a physical pool, or two pools over the same
   CPU memory. Device visibility alone does not make a write through one visible to a read through the other: a chain of copies
   through two no-copy buffers over one allocation read stale bytes on every run (probe-gpu-copy-alias). So every buffer-copy
   segment carries alias visibility in the barriers it keeps and at the encoder end (original port d309e62, Codex). The ranges
   are unused here; the original port's copy-batch experiment (off by default) takes the same call. */
static id<MTL4ComputeCommandEncoder> blit_buffer(id<MTLBuffer> src, NSUInteger so, id<MTLBuffer> dst, NSUInteger d, NSUInteger n) {
    (void)src; (void)so; (void)dst; (void)d; (void)n; return blit_kind(1); }

/* TOTK: collect and copy the uniform ranges a submission binds (see usnap_t). */
static size_t arena_alloc(size_t n, id<MTLBuffer> *buf);
static void pend_materialize(uint64_t a, uint8_t *out, size_t n, int depth);
static void pend_overlay(uint64_t a, uint8_t *out, size_t n, int depth);
static void pend_materialize_x(uint64_t a, uint8_t *out, size_t n, int depth, int wait);
static void pend_overlay_x(uint64_t a, uint8_t *out, size_t n, int depth, int wait);
typedef struct { uint64_t lo, hi; } usnap_rng;
typedef struct { usnap_rng *r; int n, cap; } usnap_rngs;
static usnap_rngs g_usr;   // replay side (the capture on the game thread uses its own list)
static void usnap_collect(usnap_rngs *v, const uint8_t *p, int depth) {
    for (;;) {
        op_hdr h; memcpy(&h, p, sizeof h);
        if (h.size < 8 || (h.size & 7) || h.op >= OP_COUNT_) MDIE("corrupt recording at %p while copying uniforms (op %u size %u)", (const void *)p, h.op, h.size);
        if (h.op == OP_END) return;
        if (h.op == OP_JUMP) { memcpy(&p, p + 8, 8); continue; }
        if (h.op == OP_CALL) { uint64_t t; memcpy(&t, p + 8, 8); if (depth < 16) usnap_collect(v, (const uint8_t *)(uintptr_t)t, depth + 1); }
        else if (h.op == OP_BIND_UBO) {
            const p_bind_buf *b = (const p_bind_buf *)(p + 8);
            if (b->addr && b->size && b->size <= 65536) {
                if (v->n == v->cap) { v->cap = v->cap ? v->cap * 2 : 4096; v->r = realloc(v->r, v->cap * sizeof *v->r); if (!v->r) MDIE("uniform copy ranges"); }
                v->r[v->n++] = (usnap_rng){b->addr, b->addr + b->size};
            }
        }
        p += h.size;
    }
}
static int usnap_cmp(const void *x, const void *y) { const usnap_rng *a = x, *b = y; return a->lo < b->lo ? -1 : a->lo > b->lo; }
/* TOTK: sort ranges by start. A frame binds a few thousand uniform ranges; qsort with a compare callback took about 5% of
   the replay (0.4 ms a frame on the M4). LSD radix sort on the 64-bit start, 8 bits per pass, skipping bytes every key
   shares (guest addresses differ only in their low few bytes); stable, so equal starts keep their order. */
static void rng_sort(usnap_rng *a, int n) {
    if (n < 2) return;
    if (n <= 32) { qsort(a, (size_t)n, sizeof *a, usnap_cmp); return; }
    static usnap_rng *tmp; static int cap;
    if (n > cap) { cap = n + n / 2; tmp = realloc(tmp, (size_t)cap * sizeof *tmp); if (!tmp) MDIE("range sort"); }
    uint64_t lo_or = 0, lo_and = ~0ull;
    for (int i = 0; i < n; i++) { lo_or |= a[i].lo; lo_and &= a[i].lo; }
    uint64_t vary = lo_or ^ lo_and;
    usnap_rng *src = a, *dst = tmp;
    for (int sh = 0; sh < 64; sh += 8) {
        if (!((vary >> sh) & 0xff)) continue;
        int cnt[257] = {0};
        for (int i = 0; i < n; i++) cnt[((src[i].lo >> sh) & 0xff) + 1]++;
        for (int b = 0; b < 256; b++) cnt[b + 1] += cnt[b];
        for (int i = 0; i < n; i++) dst[cnt[(src[i].lo >> sh) & 0xff]++] = src[i];
        usnap_rng *t = src; src = dst; dst = t;
    }
    if (src != a) memcpy(a, src, (size_t)n * sizeof *a);
}
static int gw_cmp(const void *x, const void *y) { const gw_t *a = x, *b = y; return a->lo < b->lo ? -1 : a->lo > b->lo; }
/* With the translation thread (TOTK_ASYNC_REPLAY=1) nvnQueueSubmitCommands returns before the replay, as on the console,
   and the game rebuilds its constant pools right away: the uniform bytes are captured in the submit call (game thread)
   and the replay builds its copies from them. done: fence completion at the capture; a GPU write of an earlier submission
   whose fence is above it was not in memory then, so ranges it overlaps are read on the GPU timeline instead (with the
   replay inside the submit call the capture is the replay's own start, as before). */
typedef struct { uint64_t done; int n; usnap_rng *r; size_t *off; uint8_t *bytes; uint64_t ns; } usnap_cap;
static _Atomic uint64_t g_ucap_ns, g_ucap_bytes;
void *mtl_sub_capture_ubos(const uint64_t *h, int n) {
    static int on = -1;   // TOTK_UBO_CAPTURE=0 (A/B only): the translation thread copies at the start of the replay instead
    if (on < 0) { const char *e = getenv("TOTK_UBO_CAPTURE"); on = !(e && !strcmp(e, "0")); if (!on) MLOG("TOTK_UBO_CAPTURE=0：翻译线程模式下 uniform 在回放开始时才拷（对照用）"); }
    if (!on || !usnap_on()) return NULL;
    uint64_t t0 = clock_gettime_nsec_np(CLOCK_UPTIME_RAW);
    usnap_cap *c = calloc(1, sizeof *c); if (!c) MDIE("uniform capture");
    c->done = __atomic_load_n(&g_done, __ATOMIC_ACQUIRE);   // before the bytes: a write completing meanwhile only makes this conservative
    usnap_rngs v = {0};
    for (int i = 0; i < n; i++) usnap_collect(&v, (const uint8_t *)(uintptr_t)h[i], 0);
    if (v.n) {
        rng_sort(v.r, v.n);
        int k = -1;   // merge overlapping / touching bindings that lie in one memory pool; drop bindings outside every pool
        for (int i = 0; i < v.n; i++) {
            void *mb; uint64_t mo;
            if (k >= 0 && v.r[i].lo <= v.r[k].hi) {
                if (v.r[i].hi <= v.r[k].hi) continue;
                if (mtl_addr(v.r[k].lo, v.r[i].hi - v.r[k].lo, &mb, &mo)) { v.r[k].hi = v.r[i].hi; continue; }
            }
            if (!mtl_addr(v.r[i].lo, v.r[i].hi - v.r[i].lo, &mb, &mo)) continue;
            v.r[++k] = v.r[i];
        }
        c->n = k + 1;
        size_t total = 0;
        c->off = malloc(sizeof *c->off * (size_t)(c->n ? c->n : 1)); if (!c->off) MDIE("uniform capture");
        for (int i = 0; i < c->n; i++) { c->off[i] = total; total += (size_t)(v.r[i].hi - v.r[i].lo); }
        c->bytes = malloc(total ? total : 1); if (!c->bytes) MDIE("uniform capture bytes");
        for (int i = 0; i < c->n; i++) memcpy(c->bytes + c->off[i], (const void *)(uintptr_t)v.r[i].lo, (size_t)(v.r[i].hi - v.r[i].lo));
        c->r = v.r; v.r = NULL;
        atomic_fetch_add(&g_ucap_bytes, total);
    }
    free(v.r);
    c->ns = clock_gettime_nsec_np(CLOCK_UPTIME_RAW) - t0; atomic_fetch_add(&g_ucap_ns, c->ns);
    return c;
}
static void ucap_free(usnap_cap *c) { if (c) { free(c->r); free(c->off); free(c->bytes); free(c); } }
/* The bytes of [a, a+n) as captured: memory at the capture where a captured range covers them (they are memory now
   elsewhere: no binding of this submission reads there). */
static void ucap_read(const usnap_cap *c, uint64_t a, uint8_t *out, size_t n) {
    memcpy(out, (const void *)(uintptr_t)a, n);
    int lo = 0, hi = c->n;   // first captured range ending above a (ranges are disjoint and sorted)
    while (lo < hi) { int m = (lo + hi) / 2; if (c->r[m].hi <= a) lo = m + 1; else hi = m; }
    for (int i = lo; i < c->n && c->r[i].lo < a + n; i++) {
        uint64_t s0 = c->r[i].lo > a ? c->r[i].lo : a, e0 = c->r[i].hi < a + n ? c->r[i].hi : a + n;
        memcpy(out + (s0 - a), c->bytes + c->off[i] + (s0 - c->r[i].lo), (size_t)(e0 - s0));
    }
}
static int g_ucap_probe_now;   // probe-gpu-ubo-snapshot negative control only: judge GPU writes at the replay, not the capture
static void usnap_take(const uint64_t *h, int n, const usnap_cap *cap);
/* Helper threads for phase 2 of usnap_take: each claims entries through an atomic cursor and copies them; the replay
   thread signals them after phase 1 and goes on replaying. usnap_finish waits for them before the entries or the capture
   are reused / freed (end of the submission; long after they are done in practice). */
#define USH_MAX 2
static dispatch_semaphore_t g_ush_sem; static _Atomic int g_ush_next, g_ush_busy, g_ush_n; static int g_ush_count = -1;
static const usnap_cap *g_usnap_cap;   // the translation-thread mode's capture, the source of the copies until the helpers are done
static void *ush_main(void *arg) {
    (void)arg; pthread_set_qos_class_self_np(QOS_CLASS_USER_INTERACTIVE, 0);
    for (;;) {
        dispatch_semaphore_wait(g_ush_sem, DISPATCH_TIME_FOREVER);
        int n = atomic_load_explicit(&g_ush_n, memory_order_acquire); uint64_t did = 0;
        for (;;) {
            int i = atomic_fetch_add(&g_ush_next, 1); if (i >= n) break;
            int exp = US_PENDING; if (atomic_compare_exchange_strong(&g_usnap[i].st, &exp, US_COPYING)) { usnap_copy_one(&g_usnap[i]); did++; }
        }
        atomic_fetch_add(&g_usnap_helped, did);
        atomic_fetch_sub_explicit(&g_ush_busy, 1, memory_order_release);
    }
    return NULL;
}
static int ush_count(void) {
    if (g_ush_count < 0) {
        const char *e = getenv("TOTK_USNAP_HELPERS"); int k = e ? atoi(e) : USH_MAX; if (k < 0) k = 0; if (k > USH_MAX) k = USH_MAX;
        if (k) { g_ush_sem = dispatch_semaphore_create(0); for (int i = 0; i < k; i++) { pthread_t th; if (pthread_create(&th, NULL, ush_main, NULL)) MDIE("uniform copy helper thread"); pthread_detach(th); } }
        g_ush_count = k; MLOG("[nvn] uniform 提交时快照：%d 个辅助线程并行拷贝%s", k, k ? "，回放不等它们" : "（TOTK_USNAP_HELPERS=0：回放线程自己拷）");
    }
    return g_ush_count;
}
static void usnap_finish(void) {   // this submission's copies are about to be reused: the helpers must be done with them
    while (atomic_load_explicit(&g_ush_busy, memory_order_acquire)) sched_yield();
    if (g_usnap_cap) { ucap_free((usnap_cap *)g_usnap_cap); g_usnap_cap = NULL; }
}
void mtl_sub_snapshot_ubos_cap(const uint64_t *h, int n, void *capv) {
    usnap_cap *cap = capv;
    usnap_finish();
    g_nusnap = 0;
    if (!usnap_on()) { g_ngw = 0; ucap_free(cap); g_fc_snap_end = clock_gettime_nsec_np(CLOCK_UPTIME_RAW); return; }
    uint64_t t0 = clock_gettime_nsec_np(CLOCK_UPTIME_RAW);
    usnap_take(h, n, cap);   // keeps cap in g_usnap_cap until the copies are done (usnap_finish)
    g_fc_snap_end = clock_gettime_nsec_np(CLOCK_UPTIME_RAW);
    g_usnap_ns += g_fc_snap_end - t0;
    g_usnap_n += (uint64_t)g_nusnap;
    if (++g_usnap_subs % 1800 == 0) {
        uint64_t cns = atomic_exchange(&g_ucap_ns, 0), cby = atomic_exchange(&g_ucap_bytes, 0);
        MLOG("[nvn] uniform 提交时快照：每次提交平均 %.0f 段 / %.1f KB / 回放线程 %.3f ms（收集排序 %.3f / 合并 %.3f / 分配并派发 %.3f）；辅助线程拷 %llu 段、回放自取 %llu 段、等辅助线程 %llu 次；本次提交里 GPU 写入使快照失效共 %llu 段，因前次提交的 GPU 写入未完成而不拷贝共 %llu 段%s",
             (double)g_usnap_n / 1800, (double)g_usnap_bytes / 1800 / 1024, (double)g_usnap_ns / 1800 / 1e6,
             (double)g_usnap_t[0] / 1800 / 1e6, (double)g_usnap_t[1] / 1800 / 1e6, (double)g_usnap_t[2] / 1800 / 1e6,
             (unsigned long long)atomic_load(&g_usnap_helped), (unsigned long long)g_usnap_self, (unsigned long long)g_usnap_waits,
             (unsigned long long)g_usnap_drops, (unsigned long long)g_usnap_skip_gpu,
             cby ? [NSString stringWithFormat:@"；翻译线程模式：提交调用里先拷 %.1f KB / %.3f ms（游戏线程）", (double)cby / 1800 / 1024, (double)cns / 1800 / 1e6].UTF8String : "");
        g_usnap_n = g_usnap_bytes = g_usnap_ns = 0; g_usnap_t[0] = g_usnap_t[1] = g_usnap_t[2] = 0; atomic_store(&g_usnap_helped, 0); g_usnap_self = g_usnap_waits = 0;
        cg_stats_line();
        { uint64_t f = atomic_load(&g_usnap_faults); if (f) MLOG("【红】uniform 快照拷贝读到不可访问地址累计 %llu 次（那些段改读内存）", (unsigned long long)f); }
        if (g_fc_n) MLOG("[nvn] 首段提交（每次提交平均，ms）：开始 %.3f / 快照 %.3f / 首段回放 %.3f / 等编码线程 %.3f / 上传冲刷 %.3f / 驻留提交 %.3f / 提交 %.3f%s",
                         (double)g_fc_t[0] / 1800 / 1e6, (double)g_usnap_ns / 1800 / 1e6, (double)g_fc_t[1] / g_fc_n / 1e6, (double)g_fc_t[2] / g_fc_n / 1e6,
                         (double)g_fc_t[3] / g_fc_n / 1e6, (double)g_fc_t[4] / g_fc_n / 1e6, (double)g_fc_t[5] / g_fc_n / 1e6,
                         g_exp_skip_fs_n ? [NSString stringWithFormat:@"；【实验】按片元着色器跳过的绘制 %llu", (unsigned long long)g_exp_skip_fs_n].UTF8String : "");
        memset(g_fc_t, 0, sizeof g_fc_t); g_fc_n = 0; g_exp_skip_fs_n = 0;
    }
}
void mtl_sub_snapshot_ubos(const uint64_t *h, int n) { mtl_sub_snapshot_ubos_cap(h, n, NULL); }
static void usnap_take(const uint64_t *h, int n, const usnap_cap *cap) {
    uint64_t tq0 = clock_gettime_nsec_np(CLOCK_UPTIME_RAW);
    uint64_t done = cap && !g_ucap_probe_now ? cap->done : __atomic_load_n(&g_done, __ATOMIC_ACQUIRE);
    int ng = 0; uint64_t gw_maxlen = 0;   // GPU writes not finished at the capture, sorted by start
    for (int i = 0; i < g_ngw; i++) if (g_gw[i].fence > done) { g_gw[ng++] = g_gw[i]; if (g_gw[i].hi - g_gw[i].lo > gw_maxlen) gw_maxlen = g_gw[i].hi - g_gw[i].lo; }
    g_ngw = ng;
    if (ng > 1) qsort(g_gw, (size_t)ng, sizeof *g_gw, gw_cmp);
    g_usr.n = 0;
    if (cap) {   // the bindings as captured (merged, inside pools); the merge below works on them as on fresh ones
        if (cap->n > g_usr.cap) { g_usr.cap = cap->n + 256; g_usr.r = realloc(g_usr.r, g_usr.cap * sizeof *g_usr.r); if (!g_usr.r) MDIE("uniform copy ranges"); }
        memcpy(g_usr.r, cap->r, sizeof *cap->r * (size_t)cap->n); g_usr.n = cap->n;
    } else for (int i = 0; i < n; i++) usnap_collect(&g_usr, (const uint8_t *)(uintptr_t)h[i], 0);
    if (!g_usr.n) return;
    usnap_rng *u = g_usr.r;
    if (!cap) rng_sort(u, g_usr.n);
    uint64_t tq1 = clock_gettime_nsec_np(CLOCK_UPTIME_RAW); g_usnap_t[0] += tq1 - tq0;
    /* merge ranges up to 256 bytes apart that lie in one memory pool, at most 1 MiB each (arena blocks are 4 MiB); the copies
       stay disjoint and sorted (usnap_first): a range overlapping a full copy keeps only its part beyond it, so a binding
       that no single copy holds reads memory as before */
    int k = 0;
    for (int i = 1; i < g_usr.n; i++) {
        void *mb; uint64_t mo; uint64_t hi = u[i].hi > u[k].hi ? u[i].hi : u[k].hi;
        if (hi <= u[k].hi) continue;   // inside the current copy
        if (u[i].lo <= u[k].hi + 256 && hi - u[k].lo <= (1u << 20) && mtl_addr(u[k].lo, hi - u[k].lo, &mb, &mo)) u[k].hi = hi;
        else { usnap_rng r = u[i]; if (r.lo < u[k].hi) r.lo = u[k].hi; u[++k] = r; }
    }
    int nr = k + 1;
    if (nr > g_capusnap) { g_capusnap = nr + 256; g_usnap = realloc(g_usnap, g_capusnap * sizeof *g_usnap); if (!g_usnap) MDIE("uniform copies"); }
    uint64_t tq2 = clock_gettime_nsec_np(CLOCK_UPTIME_RAW); g_usnap_t[1] += tq2 - tq1;
    for (int i = 0; i < nr; i++) {
        void *mb; uint64_t mo; uint64_t sz = u[i].hi - u[i].lo;
        if (!mtl_addr(u[i].lo, sz, &mb, &mo)) continue;   // not in one pool: read live memory
        if (ng) {   // a GPU write not finished at the capture overlaps it: read on the GPU timeline
            uint64_t from = u[i].lo > gw_maxlen ? u[i].lo - gw_maxlen : 0; int a = 0, b = ng;
            while (a < b) { int m = (a + b) >> 1; if (g_gw[m].lo < from) a = m + 1; else b = m; }
            int hit = 0; for (int j = a; j < ng && g_gw[j].lo < u[i].hi; j++) if (g_gw[j].hi > u[i].lo) { hit = 1; break; }
            if (hit) { g_usnap_skip_gpu++; continue; }
        }
        id<MTLBuffer> ab; size_t off = arena_alloc((size_t)sz, &ab);
        usnap_t *c = &g_usnap[g_nusnap++];
        c->lo = u[i].lo; c->hi = u[i].hi; c->gpu = ab.gpuAddress + off; c->cpu = (uint8_t *)ab.contents + off;
        atomic_store_explicit(&c->st, US_PENDING, memory_order_relaxed);
        g_usnap_bytes += sz;
    }
    // phase 2: the bytes. Helpers claim entries through the cursor; the replay goes on and copies what it needs first itself.
    g_usnap_cap = cap;
    g_usnap_pend_n = g_npend;   // the copies (helpers or the replay itself) overlay only the pending writes known now
    int helpers = ush_count();
    if (helpers && g_nusnap) { atomic_store(&g_ush_next, 0); atomic_store_explicit(&g_ush_n, g_nusnap, memory_order_release); atomic_store_explicit(&g_ush_busy, helpers, memory_order_release); for (int k = 0; k < helpers; k++) dispatch_semaphore_signal(g_ush_sem); }
    else for (int i = 0; i < g_nusnap; i++) { int exp = US_PENDING; if (atomic_compare_exchange_strong(&g_usnap[i].st, &exp, US_COPYING)) usnap_copy_one(&g_usnap[i]); }
    g_usnap_t[2] += clock_gettime_nsec_np(CLOCK_UPTIME_RAW) - tq2;
}
static void usnap_copy_one(usnap_t *c) {   // the entry is COPYING and ours; lookups inside never wait (memory, as before)
    size_t sz = (size_t)(c->hi - c->lo);
    /* The reads below touch guest memory and the sources of pending GPU copies; a page the game unmapped meanwhile faults.
       Guarded: the fault drops this entry (its readers use memory, as for a GPU-written range) instead of ending the process
       (2026-10-16: a helper thread died with SIGBUS once in ~12 sessions). */
    sigjmp_buf jb;
    if (sigsetjmp(jb, 1) == 0) {
        runtime_fault_guard = &jb;
        if (g_usnap_cap) ucap_read(g_usnap_cap, c->lo, c->cpu, sz);   // captured bytes plus earlier submissions' writes not yet executed
        else memcpy(c->cpu, (const void *)(uintptr_t)c->lo, sz);     // memory plus writes of earlier submissions not yet executed
        pend_overlay_x(c->lo, c->cpu, sz, 0, 0);
        runtime_fault_guard = NULL;
        int exp = US_COPYING; atomic_compare_exchange_strong_explicit(&c->st, &exp, US_READY, memory_order_release, memory_order_relaxed);   // stays DROPPED if a GPU write hit it meanwhile
    } else {
        runtime_fault_guard = NULL;
        atomic_store_explicit(&c->st, US_DROPPED, memory_order_release);
        uint64_t k = atomic_fetch_add(&g_usnap_faults, 1);
        if (k < 4) MLOG("【红】uniform 快照拷贝读到不可访问的地址（段 %#llx+%zu，第 %llu 次）：这一段改读内存", (unsigned long long)c->lo, sz, (unsigned long long)k + 1);
    }
}
void mtl_sub_copy(uint64_t src, uint64_t dst, uint64_t n) {
    g_copy_n++; g_copy_split += g_enc != nil;
    upd_guard(src, src + n); upd_guard(dst, dst + n);
    pend_note(dst, n, (const void *)(uintptr_t)src, 1); pd_xfer("copy", src, dst, n);
    usnap_drop(dst, n);   // TOTK: later readers see the copied bytes (memory, on the GPU timeline)
    anom_note_xfer('Y', src, dst, n, NULL);   // TOTK_ANOMALY
    void *sb, *db; uint64_t so, dof;
    if (!mtl_addr(src, n, &sb, &so) || !mtl_addr(dst, n, &db, &dof))
        MDIE("缓冲拷贝地址不在任何内存池内 src=%#llx dst=%#llx n=%#llx", (unsigned long long)src, (unsigned long long)dst, (unsigned long long)n);
    enc_b_copy_buffer(blit_buffer((__bridge id<MTLBuffer>)sb, so, (__bridge id<MTLBuffer>)db, dof, n), (__bridge id<MTLBuffer>)sb, so, (__bridge id<MTLBuffer>)db, dof, n);
}

// TOTK: uniform updates carry their data inline in the (host-owned) recording; stage it in this submit's
// argument arena (shared Metal memory) and copy on the GPU timeline like any other buffer copy.
static size_t arena_alloc(size_t n, id<MTLBuffer> *buf);
/* TOTK: inline uniform updates without splitting the render pass (renaming).
   The game updates small uniform ranges between draws about 200 times per frame (nvnCommandBufferUpdateUniformBuffer).
   Each one used to be a GPU copy, which ended the render pass: a copy encoder in between and the pass reopened with every
   attachment loaded again (~80 copy encoders and ~23 split passes per frame in the East Reservoir scene). Now an update
   stages its bytes in the submission arena and is logged. A draw or dispatch that binds a uniform range overlapping
   logged updates gets a private copy of that range: memory plus every pending write in order (pend_materialize), so
   draws before an update read the old bytes and draws after it the new ones. The logged updates reach memory at the end
   of the submission, or earlier when anything other than a uniform binding (vertex / index / storage / texture buffer,
   buffer copy, built-in kernel) touches an updated range; that check runs before the draw opens its encoder.
   Overlapping updates are merged and written once per merged range, so copies in one encoder never race.
   TOTK_UB_RENAME=0 keeps the per-update GPU copies. */
static inline void args_dirty_all(void);
static void upd_dirty_stages(uint64_t lo, uint64_t hi);
typedef struct { uint64_t lo, hi, seq; } upd_ent;
static upd_ent *g_upd; static int g_nupd, g_updcap; static uint64_t g_upd_lo = UINT64_MAX, g_upd_hi, g_upd_seq;
/* g_upd is kept sorted by lo (insertion with memmove; a few hundred entries per submission) with g_upd_maxhi[i] = largest hi
   in g_upd[0..i], so an overlap query is a binary search plus a backwards walk over actual overlaps: every uniform binding
   of the frame (over ten thousand) is checked, and most overlap nothing. */
static uint64_t *g_upd_maxhi;
static void upd_insert(uint64_t lo, uint64_t hi) {
    if (g_nupd == g_updcap) {
        g_updcap = g_updcap ? g_updcap * 2 : 256;
        g_upd = realloc(g_upd, (size_t)g_updcap * sizeof *g_upd); g_upd_maxhi = realloc(g_upd_maxhi, (size_t)g_updcap * sizeof *g_upd_maxhi);
        if (!g_upd || !g_upd_maxhi) MDIE("uniform update log");
    }
    int a = 0, b = g_nupd; while (a < b) { int m = (a + b) >> 1; if (g_upd[m].lo <= lo) a = m + 1; else b = m; }
    memmove(g_upd + a + 1, g_upd + a, (size_t)(g_nupd - a) * sizeof *g_upd);
    g_upd[a] = (upd_ent){lo, hi, ++g_upd_seq}; g_nupd++;
    for (int i = a; i < g_nupd; i++) { uint64_t prev = i ? g_upd_maxhi[i - 1] : 0; g_upd_maxhi[i] = g_upd[i].hi > prev ? g_upd[i].hi : prev; }
    if (lo < g_upd_lo) g_upd_lo = lo; if (hi > g_upd_hi) g_upd_hi = hi;
}
// Newest seq among logged updates overlapping [lo, hi), 0 when none.
static uint64_t upd_overlap_seq(uint64_t lo, uint64_t hi) {
    if (!g_nupd || hi <= g_upd_lo || lo >= g_upd_hi) return 0;
    int a = 0, b = g_nupd; while (a < b) { int m = (a + b) >> 1; if (g_upd[m].lo < hi) a = m + 1; else b = m; }   // entries [0, a) start below hi
    uint64_t last = 0;
    for (int i = a - 1; i >= 0 && g_upd_maxhi[i] > lo; i--) if (g_upd[i].hi > lo && g_upd[i].seq > last) last = g_upd[i].seq;
    return last;
}
typedef struct { uint64_t lo, size, seq, gpu; } ubo_shadow;
#define UBO_SHADOW_MAX 512
static ubo_shadow g_shadow[UBO_SHADOW_MAX]; static int g_nshadow;
/* Small direct-mapped index into the authoritative shadow list. Always compare the
   complete range and update sequence, so collisions, flushes and list wraparound
   fall back to the original search. No old GPU address is stored in the index. */
#define SHADOW_INDEX_N 1024
static uint16_t g_shadow_index[SHADOW_INDEX_N];
static _Atomic int g_shadow_index_on = -1, g_shadow_index_check;
static uint64_t g_shadow_index_hits, g_shadow_index_misses, g_shadow_index_verified;
static int g_shadow_index_stale_probe;
static int shadow_index_on(void) {
    int v = atomic_load(&g_shadow_index_on);
    if (v < 0) { const char *e=getenv("TOTK_SHADOW_INDEX"); v=e && atoi(e); atomic_store(&g_shadow_index_on,v); }
    return v;
}
static unsigned shadow_index_slot(uint64_t lo, uint64_t size) {
    uint64_t h=(lo >> 4) ^ (lo >> 19) ^ (size * UINT64_C(0x9e3779b97f4a7c15));
    return (unsigned)(h ^ (h >> 32)) & (SHADOW_INDEX_N-1);
}
static uint64_t g_ren_updates, g_ren_shadows, g_ren_bytes, g_ren_flushes, g_ren_late, g_ren_fallback;
static int ub_rename_on(void) {
    static int v = -1;
    if (v < 0) { const char *e = getenv("TOTK_UB_RENAME"); v = !(e && !strcmp(e, "0")); MLOG("TOTK: inline uniform updates %s", v ? "renamed per binding (render passes stay open)" : "copied on the GPU timeline (TOTK_UB_RENAME=0)"); }
    return v;
}
void mtl_ren_stats(uint64_t v[6]) { v[0] = g_ren_updates; v[1] = g_ren_shadows; v[2] = g_ren_bytes; v[3] = g_ren_flushes; v[4] = g_ren_late; v[5] = g_ren_fallback; }
/* Bytes [a, a+n) as the GPU will see them at this point of the submission: memory, then every pending write that the GPU
   has not completed yet, oldest first (inline updates carry their bytes; GPU copies read their source the same way). */
static void pend_materialize_x(uint64_t a, uint8_t *out, size_t n, int depth, int wait) {
    usnap_read_x(a, out, n, wait);
    pend_overlay_x(a, out, n, depth, wait);
}
static void pend_materialize(uint64_t a, uint8_t *out, size_t n, int depth) { pend_materialize_x(a, out, n, depth, 1); }
static void pend_overlay_x(uint64_t a, uint8_t *out, size_t n, int depth, int wait) {   // the pending writes over out (= [a, a+n) before them)
    uint64_t done = __atomic_load_n(&g_done, __ATOMIC_ACQUIRE);
    int npend = wait ? g_npend : g_usnap_pend_n;   // wait = 0: the copy routine (possibly on a helper thread)
    for (int i = 0; i < npend; i++) {
        uint64_t lo = g_pend_lo[i], hi = g_pend_hi[i];
        if (hi <= a || lo >= a + n || g_pend_fence[i] <= done) continue;   // completed writes are already in memory (which may hold newer CPU writes)
        uint64_t s0 = lo > a ? lo : a, e0 = hi < a + n ? hi : a + n;
        if (g_pend_kind[i] == 0) memcpy(out + (s0 - a), (const uint8_t *)g_pend_src[i] + (s0 - lo), e0 - s0);
        else if (depth < 2) pend_materialize_x((uint64_t)(uintptr_t)g_pend_src[i] + (s0 - lo), out + (s0 - a), e0 - s0, depth + 1, wait);
        else memcpy(out + (s0 - a), (const uint8_t *)g_pend_src[i] + (s0 - lo), e0 - s0);
    }
}
static void pend_overlay(uint64_t a, uint8_t *out, size_t n, int depth) { pend_overlay_x(a, out, n, depth, 1); }
// Write the logged updates into memory on the GPU timeline (ends a render pass if one is open).
static void upd_flush(void) {
    if (!g_nupd) return;
    /* Own encoder: copies inside one encoder may run concurrently, so earlier copies to these bytes and later readers of
       them (a buffer copy right after this flush) must sit in other encoders, ordered by the encoder barriers. */
    if (g_blit) { enc_b_end(g_blit); g_blit = nil; }
    id<MTL4ComputeCommandEncoder> b = nil;
    for (int i = 0; i < g_nupd;) {
        uint64_t lo = g_upd[i].lo, hi = g_upd[i].hi; int j = i + 1;
        for (; j < g_nupd && g_upd[j].lo <= hi; j++) if (g_upd[j].hi > hi) hi = g_upd[j].hi;   // merge overlapping / touching ranges
        void *db; uint64_t dof;
        if (!mtl_addr(lo, hi - lo, &db, &dof)) MDIE("renamed uniform update %#llx+%#llx is no longer in one memory pool", (unsigned long long)lo, (unsigned long long)(hi - lo));
        usnap_drop(lo, hi - lo);   // TOTK: from here on the update is in memory (GPU timeline): later readers read it there
        id<MTLBuffer> sb; size_t so = arena_alloc((size_t)(hi - lo), &sb);
        pend_materialize(lo, (uint8_t *)sb.contents + so, (size_t)(hi - lo), 0);   // every byte here is covered by a logged update: the newest one wins
        if (!b) b = blit();
        enc_b_copy_buffer(b, sb, so, (__bridge id<MTLBuffer>)db, dof, hi - lo);
        i = j;
    }
    if (b) { enc_b_end(g_blit); g_blit = nil; }
    g_nupd = 0; g_upd_lo = UINT64_MAX; g_upd_hi = 0; g_nshadow = 0;
}
// Before a non-uniform access to [lo, hi): logged updates overlapping it must be in memory first.
static int g_upd_guard_off;   // probe-gpu-ub-rename negative control only
static inline int upd_guard(uint64_t lo, uint64_t hi) {
    if (!g_nupd || g_upd_guard_off || !upd_overlap_seq(lo, hi)) return 0;
    g_ren_flushes++; upd_flush(); return 1;
}
// GPU address of a private copy of the uniform range [lo, lo+size) holding the logged updates, or 0 when none overlaps it.
static uint64_t upd_shadow(uint64_t lo, uint64_t size) {
    uint64_t last = size ? upd_overlap_seq(lo, lo + size) : 0;
    if (!last) return 0;
    int indexed=shadow_index_on(); unsigned slot=0;
    if (indexed) {
        slot=shadow_index_slot(lo,size); int idx=(int)g_shadow_index[slot]-1;
        if (idx>=0 && idx<g_nshadow && g_shadow[idx].lo==lo && g_shadow[idx].size==size &&
            (g_shadow_index_stale_probe || g_shadow[idx].seq==last)) {
            if (atomic_load(&g_shadow_index_check)) {
                uint64_t reference=0;
                for(int i=0;i<g_nshadow;i++) if(g_shadow[i].lo==lo && g_shadow[i].size==size && g_shadow[i].seq==last){reference=g_shadow[i].gpu;break;}
                if(reference!=g_shadow[idx].gpu)MDIE("shadow index mismatch: %#llx + %llu seq %llu",(unsigned long long)lo,(unsigned long long)size,(unsigned long long)last);
                g_shadow_index_verified++;
            }
            g_shadow_index_hits++; return g_shadow[idx].gpu;
        }
        g_shadow_index_misses++;
    }
    for (int i = 0; i < g_nshadow; i++) if (g_shadow[i].lo == lo && g_shadow[i].size == size && g_shadow[i].seq == last) {
        if(indexed)g_shadow_index[slot]=(uint16_t)(i+1);
        return g_shadow[i].gpu;
    }
    id<MTLBuffer> sb; size_t so = arena_alloc((size_t)size, &sb);
    pend_materialize(lo, (uint8_t *)sb.contents + so, (size_t)size, 0);
    uint64_t gpu = sb.gpuAddress + so;
    if (g_nshadow == UBO_SHADOW_MAX) g_nshadow = 0;
    g_shadow[g_nshadow++] = (ubo_shadow){lo, size, last, gpu};
    if(indexed)g_shadow_index[slot]=(uint16_t)g_nshadow;
    g_ren_shadows++; g_ren_bytes += size;
    return gpu;
}
static void mtl_sub_update(const void *data, uint64_t dst, uint64_t n) {
    void *db; uint64_t dof;
    /* Measurement only, DM_EXP_VIS_FILL=<bytes>: an update of exactly that size (BY3 resets its per-object visibility words,
       81920 bytes, each frame) writes 0xffff in every word instead, as if each object had passed the depth pre-pass. */
    { static long vf = -2; static uint32_t *fill; if (vf == -2) { const char *e = getenv("DM_EXP_VIS_FILL"); vf = e ? strtol(e, NULL, 0) : -1; }
      if (vf > 0 && (long)n == vf) { if (!fill) { fill = malloc((size_t)n); for (uint64_t i = 0; i < n / 4; i++) fill[i] = 0xffff; } data = fill; } }
    g_upd_n++;
    pd_update_bytes(data, dst, n, g_upd_n);
    if (!mtl_addr(dst, n, &db, &dof)) MDIE("uniform update target not in any memory pool dst=%#llx n=%#llx", (unsigned long long)dst, (unsigned long long)n);
    id<MTLBuffer> sb; size_t so = arena_alloc((size_t)n, &sb);
    memcpy((uint8_t *)sb.contents + so, data, (size_t)n);
    pend_note(dst, n, (const uint8_t *)sb.contents + so, 0);   // the arena copy outlives this submission's replay
    pd_xfer("update", 0, dst, n);
    anom_note_xfer('U', 0, dst, n, data);   // TOTK_ANOMALY
    if (ub_rename_on() && g_npend < PEND_MAX && __atomic_load_n(&g_done, __ATOMIC_ACQUIRE) >= g_pend_over_fence) {
        upd_insert(dst, dst + n);
        g_ren_updates++;
        upd_dirty_stages(dst, dst + n);   // argument buffers reused inside the pass would still point at the previous version
        return;
    }
    if (ub_rename_on()) { g_ren_fallback++; upd_flush(); }   // pending table full: keep the order with a real copy
    usnap_drop(dst, n);   // TOTK: the update reaches memory on the GPU timeline; later readers read it there
    enc_b_copy_buffer(blit_buffer(sb, so, (__bridge id<MTLBuffer>)db, dof, n), sb, so, (__bridge id<MTLBuffer>)db, dof, n);
}
static void post(post_op o) {
    if (g_npost == g_postcap) { g_postcap = g_postcap ? g_postcap * 2 : 64; g_post = realloc(g_post, g_postcap * sizeof *g_post); }
    g_post[g_npost++] = o;
}
void mtl_sub_event(volatile uint32_t *val, uint32_t mode, uint32_t v) { post((post_op){1, val, mode, v, 0, 0, NULL}); }
void mtl_sub_counter(uint64_t addr, uint32_t type) { post((post_op){2, NULL, 0, 0, addr, type, NULL}); }
// ---------- TOTK: conditional rendering evaluated in GPU order ----------
// Counter reports replayed earlier in GPU order whose memory write has not happened yet (it happens in the completion
// handler of their submit) are kept in a ring with the value they will write: 0 for timestamp / unimplemented types,
// unknown for samples passed. cond_eval consults the ring first, then the pool memory, so a conditional sees the same
// counter values the GPU would. Results are cached per op pointer per frame so the lookahead scanners and the replay agree.
typedef struct { uint64_t addr, fence, val; int known; } cpend_ent;
#define CPEND_N 4096
static cpend_ent g_cpend[CPEND_N]; static unsigned g_cpend_head, g_cpend_tail; static pthread_mutex_t g_cpend_mu = PTHREAD_MUTEX_INITIALIZER;   // TOTK: [tail, head) may still be pending (fences rise with the index, so completions clear a prefix)
static void cpend_push(uint64_t addr, uint64_t fence, uint64_t val, int known) {
    pthread_mutex_lock(&g_cpend_mu); g_cpend[g_cpend_head % CPEND_N] = (cpend_ent){addr, fence, val, known}; g_cpend_head++; pthread_mutex_unlock(&g_cpend_mu);
}
static void cpend_done(uint64_t fence) {   // the records of this submit are now in memory
    pthread_mutex_lock(&g_cpend_mu);
    if (g_cpend_head - g_cpend_tail > CPEND_N) g_cpend_tail = g_cpend_head - CPEND_N;
    for (unsigned i = g_cpend_tail; i != g_cpend_head; i++) if (g_cpend[i % CPEND_N].addr && g_cpend[i % CPEND_N].fence <= fence) g_cpend[i % CPEND_N].addr = 0;
    while (g_cpend_tail != g_cpend_head && !g_cpend[g_cpend_tail % CPEND_N].addr) g_cpend_tail++;
    pthread_mutex_unlock(&g_cpend_mu);
}
// 1 = value known (written to *val), 0 = pending but unknown, -1 = no pending write (read memory)
static int cpend_lookup(uint64_t addr, uint64_t *val) {
    int r = -1; pthread_mutex_lock(&g_cpend_mu);
    unsigned n = g_cpend_head - g_cpend_tail; if (n > CPEND_N) n = CPEND_N;   // only the part that may still be pending (it was all 4,096 slots twice per conditional)
    for (unsigned k = 0; k < n; k++) { const cpend_ent *e = &g_cpend[(g_cpend_head - 1 - k) % CPEND_N]; if (e->addr == addr) { r = e->known; *val = e->val; break; } }
    pthread_mutex_unlock(&g_cpend_mu); return r;
}
extern uint64_t g_draw_skip[16];
static _Atomic uint64_t g_cur_frame;
typedef struct { const void *op; uint64_t frame; int result; } cond_cache_ent;
static cond_cache_ent g_cond_cache[1024];
static int cond_eval(const void *payload, const void *op) {
    const p_render_cond *c = payload; uint64_t frame = atomic_load(&g_cur_frame);
    cond_cache_ent *ce = &g_cond_cache[((uintptr_t)op >> 3) & 1023];
    if (ce->op == op && ce->frame == frame) return ce->result;
    uint64_t x = 0, y = 0; int kx = cpend_lookup(c->addr, &x), ky = cpend_lookup(c->addr + 16, &y), enabled = 1, unknown = 0;
    if (kx == 0 || ky == 0) unknown = 1;
    else {
        void *bf; uint64_t off;
        if (!mtl_addr(c->addr, 32, &bf, &off)) { static int once; if (!once++) MLOG("【红】conditional render counters at %#llx are not in any memory pool", (unsigned long long)c->addr); unknown = 1; }
        else {
            if (kx < 0) memcpy(&x, (const void *)(uintptr_t)c->addr, 8);
            if (ky < 0) memcpy(&y, (const void *)(uintptr_t)(c->addr + 16), 8);
            enabled = c->mode == 0 ? x == y : x != y;
        }
    }
    if (unknown) { enabled = 1; g_draw_skip[14]++; } else if (!enabled) g_draw_skip[13]++;
    *ce = (cond_cache_ent){op, frame, enabled};
    return enabled;
}
void mtl_counter_stats(uint64_t rep[32], uint64_t rst[32]) { memcpy(rep, g_cnt_report, sizeof g_cnt_report); memcpy(rst, g_cnt_reset, sizeof g_cnt_reset); }

/* TOTK: counter timestamps in the Tegra 19.2 MHz tick base of nn::os::GetSystemTick (runtime_dispatch: mach_absolute_time
   in ns * 12 / 625). The game turns the GPU timestamps of its frame (main+0x2a7b630, via nvnDeviceGetTimestampInNanoseconds
   and ConvertToTick) into "GPU done, ticks after the CPU frame start" and raises its present interval when that is long
   (main+0x8f6bec). CLOCK_MONOTONIC counts sleep while mach_absolute_time does not: the reported GPU end was later than the
   frame start by the machine's whole sleep time since boot (24 days on the Mac, 20 on the iPhone), so the game sat at
   interval 3 (20 frames) everywhere once the device had slept. */
static uint64_t gpu_ticks(void) { static mach_timebase_info_data_t tb; if (!tb.denom) mach_timebase_info(&tb); __uint128_t ns = (__uint128_t)mach_absolute_time() * tb.numer / tb.denom; return (uint64_t)(ns * 12 / 625); }

// ---------- 启动埋点（DM_BOOTPROF=1）：metallib 载入、管线创建（均在提交线程回放中同步发生）、贴图上传、首帧出图 ----------
// ---------- Boot instrumentation (DM_BOOTPROF=1): metallib loading, pipeline creation (both happen synchronously during replay on the submit thread), texture upload, first-frame present ----------
static uint64_t bp_now(void) { struct timespec t; clock_gettime(CLOCK_MONOTONIC, &t); return (uint64_t)t.tv_sec * 1000000000ull + t.tv_nsec; }
static int survey_shader_log(void) { static int on = -1; if (on < 0) on = getenv("TOTK_SURVEY_SHADER_LOG") != NULL; return on; }
static uint64_t g_bp_t0;   // 进程启动（本模块装入）时刻 | Time of process start (when this module is loaded)
__attribute__((constructor)) static void bp_t0(void) { g_bp_t0 = bp_now(); }
static int bootprof(void) { static int v = -1; if (v < 0) v = getenv("DM_BOOTPROF") != NULL; return v; }
static uint64_t g_bp_lib_n, g_bp_lib_ns, g_bp_pso_n, g_bp_pso_ns, g_bp_up_bytes, g_bp_first_present;
static uint64_t g_up_total_ns;   // 上传累计耗时（与逐帧 @upload_ms 同源） | Cumulative upload time (same source as the per-frame @upload_ms)
// ---------- 按帧归集 GPU 时间 ----------
// ---------- Per-frame GPU time aggregation ----------
#define GRING 1024
static struct { _Atomic uint64_t frame, ns, t0, t1; _Atomic int pending; } g_gpu[GRING];   // t0 / t1：该帧最早 GPUStart / 最晚 GPUEnd（mach 绝对时间 ns） | t0 / t1: the frame's earliest GPUStart / latest GPUEnd (mach absolute time, ns)
/* g_cur_frame is defined above (conditional rendering) */
// ---------- 同进程交替测量（DM_NVN_UB，缺省无：不设环境变量时下面只多一次「是否启用」的判断） ----------
// 真机热态下系统持续调功率 / 频率，分段对比（A 段、B 段各跑一分钟）分不清 <10% 的差；在同一局里按相轮流开关、相邻相配对取差，漂移对消。
// DM_NVN_UB="名字=项,项;名字=项"，每 DM_NVN_UB_N 帧（缺省 180，下限 60）一相：偶数相 = 基准（什么都不改），奇数相轮流取一类。一类里的每一项：
//   @set:<全局变量名>=<值>   进相时把这个 int 全局变量设成该值、出相时还原（按符号名找地址；真机上要用的开关须在下面的登记表里加一行）
//   <片元着色器键前缀> 或 *   该相丢掉这些片元着色器的全部绘制（画面会错，只量「这类绘制值多少」；近乎空载的类别要单独成轮）
// 读数：每相丢掉前 45 帧（过渡 + 上屏滞后），其余帧的实际上屏间隔（与 perf.txt 同源）均值与 16.7 / 25 / ≥33 ms 三档帧数，日志一行「UB 上屏」。
// 出表：$DM_ROOT/run/ruler/ub_table.py；真机脚本：$DM_ROOT/run/ruler/ub_alt.sh。
// ---------- Same-process alternating measurement (DM_NVN_UB, off by default: without the environment variable the code below only adds one 'is it enabled' check) ----------
// On a hot real device the system keeps adjusting power / frequency, and segment comparison (segments A and B each run for a minute) cannot resolve differences of <10%; within the same run, toggle by phase in turn and take differences of adjacent phase pairs, so the drift cancels.
// DM_NVN_UB="name=item,item;name=item", one phase every DM_NVN_UB_N frames (default 180, minimum 60): even phases = baseline (nothing changed), odd phases take one category in turn. Each item of a category:
//   @set:<global variable name>=<value>   on entering the phase set this int global variable to the value, on leaving restore it (address found by symbol name; switches to be used on a real device must have a line added to the registration table below)
//   <fragment shader key prefix> or *   the phase drops all draws of these fragment shaders (the picture will be wrong; it only measures 'how much this kind of draw is worth'; a nearly idle category needs a round of its own)
// Readings: each phase discards its first 45 frames (transition + present lag); for the remaining frames, the mean of the actual present interval (same source as perf.txt) and the frame counts in the three buckets 16.7 / 25 / ≥33 ms, one log line 「UB 上屏」(UB present).
