@implementation NvPkg
- (void)dealloc {
    free(edge);   // TOTK (#90): the shared first / last page bytes (pkg_edge_snap)
    // The wrapper is released after its GPU readers finish. Recycle its allocation
    // with the same descriptor key as a re-upload, retaining residency. The next
    // owner overwrites every mip/layer; cached views are retired by the normal path.
    if (!owned && pkg_final_cache_on() && reup_offer(tex, &key)) atomic_fetch_add(&g_pkg_final_kept, 1);
    else res_remove(tex);
}
@end
/* TOTK: GPU renderings into CPU-visible memory pools reach that memory when the CPU invalidates it.
   On hardware the GPU writes the texture's memory, and the game reads it back with the CPU after
   nvnMemoryPoolInvalidateMappedRange (CPU-cached pools). Here a mirrored texture the GPU renders into keeps the result
   only in its MTLTexture, so the game read the bytes it had uploaded before. The game bakes terrain tile normals on the
   GPU into such a pool and copies them with the CPU into new tiles: after moving, new tiles got stale normals and the
   ground turned black block by block (2026-10-15). Each rendering of a mirrored texture is noted here (with a reference,
   so the result outlives a temporary texture object finalized before the submission runs); an invalidate over its
   memory waits for the GPU and writes every level back in the NVN layout, unless the CPU has written the memory since
   the rendering (then the CPU's bytes are newer). Runtime switch: TOTK_INPUT_FILE "flag writeback 0|1" (default 1). */
typedef struct { tex_t t; uint64_t stamp; void *obj; } wb_ent;
static nvn_hmap g_wb = {.klen = 8};   // serial -> wb_ent * (g_smu): rendered since the last write-back
static _Atomic int g_wb_on = 1;
/* TOTK: fill the driver segment c0 for vertex and compute shaders (thread-group counts, uniform / storage address tables,
   point size limit; see drv_scan). TOTK_DRV_FILL=0 or "flag drvfill 0" gives them the old all-zero segment (A/B only). */
static _Atomic int g_drvfill_on = -1;
static int drvfill_on(void) { int v = atomic_load(&g_drvfill_on); if (v < 0) { const char *e = getenv("TOTK_DRV_FILL"); v = !(e && !strcmp(e, "0")); atomic_store(&g_drvfill_on, v); } return v; }
static uint64_t g_wb_done, g_wb_skip_cpu, g_wb_skip_fmt, g_wb_bytes;
/* TOTK diagnostics for the game's occlusion culling (a 256x144 occluder depth pass, then one SAMPLES_PASSED query per
   candidate object with a bounding-sphere proxy; an object whose query reports 0 is not drawn): "flag occl_visible 1"
   reports every query as visible (if a vanished object comes back, the culling decided it); "querylog <frames>" logs
   each query's result with the sphere the proxy draw had in its vertex uniform block 1 (x, y, z, radius). */
void dm_gfx_querylog_next(long n) { long f = (long)atomic_load(&g_cur_frame); atomic_store(&g_ql_until, f + (n > 0 ? n : 1)); MLOG("[query] logging occlusion queries until frame %ld", f + n); }
static void driver_cache_set(int v);
static void driver_cache_check_set(int v);
// One shader class can be hidden for geometry fault isolation without restarting.
// Diagnostic only: measurements with this enabled are never valid performance results.
static _Atomic uint64_t g_diag_skip_fs;
static _Atomic uint64_t g_diag_texpng_fs, g_diag_geometry_fs;
static int diag_shader_prefix_matches(const char *key, uint64_t value) {
    char prefix[17]; snprintf(prefix, sizeof prefix, "%016llx", (unsigned long long)value);
    return key && !strncmp(key, prefix, 16);
}
void dm_gfx_set_flag(const char *name, int v) {
    if (!strcmp(name, "arg_epoch")) { (void)arg_epoch_on(); atomic_store(&g_arg_epoch_on, v != 0); MLOG("[flag] arg_epoch = %d", v != 0); return; }
    if (!strcmp(name, "arg_epoch_check")) { (void)arg_epoch_on(); atomic_store(&g_arg_epoch_check, v != 0); MLOG("[flag] arg_epoch_check = %d verified=%llu extra=%llu", v != 0, (unsigned long long)atomic_load(&g_arg_epoch_verified), (unsigned long long)atomic_load(&g_arg_epoch_extra)); return; }
    if (!strcmp(name, "tex_slots")) { (void)tex_slots_on(); atomic_store(&g_tex_slots_on, v != 0); MLOG("[flag] tex_slots = %d", v != 0); return; }
    if (!strcmp(name, "tex_slots_check")) { (void)tex_slots_on(); atomic_store(&g_tex_slots_check, v != 0); MLOG("[flag] tex_slots_check = %d verified=%llu hits=%llu", v != 0, (unsigned long long)atomic_load(&g_tex_slots_verified), (unsigned long long)atomic_load(&g_tex_slots_hits)); return; }
    if (!strcmp(name, "render_stream")) { atomic_store(&g_rs_on, v != 0); MLOG("[flag] render_stream = %d (next render pass)", v != 0); return; }
    if (!strcmp(name, "cube_merge")) { atomic_store(&g_cg_on, v != 0); MLOG("[flag] cube_merge = %d", v != 0); return; }
    if (!strcmp(name, "skip_invisible")) { skv_set(v); return; }
    if (!strcmp(name, "mfx_upscale")) { mfxup_set(v < 0 ? !mfxup_enabled() : v); return; }   // TOTK_MFX_UPSCALE at run time (manual key 3 picture mode)
    if (!strcmp(name, "mfx_interp")) { mfx_set(v); return; }
    if (!strcmp(name, "draw_log")) { extern _Atomic long g_draw_log; atomic_store(&g_draw_log, v); MLOG("[flag] draw_log: every draw and dispatch of the next %d frames", v); return; }
    if (!strcmp(name, "uw_log")) { extern _Atomic long g_uw_log; atomic_store(&g_uw_log, v); MLOG("[flag] uw_log: canvas draws of the next %d frames", v); return; }   // key 4 UI squeeze diagnostic
    if (!strcmp(name, "mfx_output")) { mfxup_output_set(v < 0 ? !mfxup_output_enabled() : v); return; }   // TOTK_MFX_OUTPUT at run time (the window output stage)
    if (!strcmp(name, "pass_gpu")) {
        if (v < 0 || v > 120) { MLOG("[flag] pass_gpu requires 0..120 frames"); return; }
        atomic_store_explicit(&g_pt_request, v, memory_order_relaxed);
        MLOG("[flag] pass_gpu = %d (next submission; diagnostic frames must be excluded from FPS)", v); return;
    }
    if (!strcmp(name, "diag_env_once")) { extern void nvn_diag_env_once_set(int); nvn_diag_env_once_set(v); return; }
    if (!strcmp(name, "inline_bulk")) { extern void dm_nvn_inline_bulk_set(int); dm_nvn_inline_bulk_set(v); return; }
    if (!strcmp(name, "keepalive_us")) {
        if (v && (v < 100 || v > 1000)) { MLOG("[flag] keepalive_us requires 0 or 100..1000"); return; }
        atomic_store(&g_ka_target_us, v); MLOG("[flag] keepalive_us = %d", v); return;
    }
    if (!strcmp(name, "chunk_first") || !strcmp(name, "chunk_draws")) {
        if (v < 0 || v > 1000) { MLOG("[flag] chunk controls require 0..1000"); return; }
        atomic_store(!strcmp(name, "chunk_first") ? &g_chunk_first_request : &g_chunk_size_request, v);
        MLOG("[flag] %s = %d (next submission)", name, v); return;
    }
    if (!strcmp(name, "usnap_index")) { atomic_store(&g_usnap_index_on, v != 0); MLOG("[flag] usnap_index = %d", v != 0); return; }
    if (!strcmp(name, "usnap_index_check")) { atomic_store(&g_usnap_index_check, v != 0); MLOG("[flag] usnap_index_check = %d", v != 0); return; }
    if (!strcmp(name, "vertex_streams")) { atomic_store(&g_vertex_streams_on, v != 0); MLOG("[flag] vertex_streams = %d", v != 0); return; }
    if (!strcmp(name, "arg_bind_cache")) { atomic_store(&g_arg_bind_cache_on, v != 0); MLOG("[flag] arg_bind_cache = %d", v != 0); return; }
    if (!strcmp(name, "pool_query_cache")) { atomic_store(&g_pool_query_on, v != 0); MLOG("[flag] pool_query_cache = %d", v != 0); return; }
    if (!strcmp(name, "pool_query_check")) { atomic_store(&g_pool_query_check, v != 0); MLOG("[flag] pool_query_check = %d", v != 0); return; }
    if (!strcmp(name, "texture_plan")) { (void)texture_plan_on(); atomic_store(&g_texture_plan_on, v != 0); MLOG("[flag] texture_plan = %d", v != 0); return; }
    if (!strcmp(name, "texture_plan_check")) { (void)texture_plan_on(); atomic_store(&g_texture_plan_check, v != 0); MLOG("[flag] texture_plan_check = %d", v != 0); return; }
    if (!strcmp(name, "anomaly_capture")) {
        const char *dir = getenv("TOTK_ANOMALY");
        if (!dir || !*dir) { MLOG("[flag] anomaly_capture unavailable: start with TOTK_ANOMALY directory"); return; }
        atomic_store(&g_anom_requested, v != 0); MLOG("[flag] anomaly_capture = %d", v != 0); return;
    }
    if (!strcmp(name, "shadow_index")) { atomic_store(&g_shadow_index_on, v != 0); MLOG("[flag] shadow_index = %d", v != 0); return; }
    if (!strcmp(name, "shadow_index_check")) { atomic_store(&g_shadow_index_check, v != 0); MLOG("[flag] shadow_index_check = %d", v != 0); return; }
    if (!strcmp(name, "pkg_final_cache")) { atomic_store(&g_pkg_final_cache, v != 0); MLOG("[flag] pkg_final_cache = %d", v != 0); return; }
    if (!strcmp(name, "pend_arena_pin")) { atomic_store(&g_pend_arena_pin, v != 0); MLOG("[flag] pend_arena_pin = %d", v != 0); return; }
    if (!strncmp(name, "skipfs_", 7)) {
        const char *p = name + 7;
        if (strlen(p) != 16 || strspn(p, "0123456789abcdefABCDEF") != 16) { MLOG("[flag] skipfs needs exactly 16 hex digits"); return; }
        atomic_store(&g_diag_skip_fs, v ? strtoull(p, NULL, 16) : 0);
        MLOG("[flag] diagnostic skipfs %.16s = %d (incomplete geometry; invalid FPS)", p, v != 0); return;
    }
    if (!strncmp(name, "texpngfs_", 9) || !strncmp(name, "geodumpfs_", 10)) {
        int geometry = !strncmp(name, "geodumpfs_", 10);
        const char *p = name + (geometry ? 10 : 9);
        if (strlen(p) != 16 || strspn(p, "0123456789abcdefABCDEF") != 16) {
            MLOG("[flag] shader capture needs exactly 16 hex digits"); return;
        }
        atomic_store(geometry ? &g_diag_geometry_fs : &g_diag_texpng_fs,
                     v ? strtoull(p, NULL, 16) : 0);
        MLOG("[flag] diagnostic %s = %d (capture on requested dump; invalid FPS)", name, v != 0); return;
    }
    if (!strcmp(name, "drv_cache")) { driver_cache_set(v); return; }
    if (!strcmp(name, "drv_cache_check")) { driver_cache_check_set(v); return; }
    if (!strcmp(name, "writeback")) { atomic_store(&g_wb_on, v); MLOG("[flag] writeback = %d", v); return; }
    if (!strcmp(name, "deferred")) { extern void nvn_set_deferred_binds(int on); nvn_set_deferred_binds(v); return; }
    if (!strcmp(name, "framewait")) { extern void nvn_set_framewait(int on); nvn_set_framewait(v); return; }
    if (!strcmp(name, "uncapped_interval")) { extern void nvn_set_uncapped_interval(int on); nvn_set_uncapped_interval(v); return; }
    if (!strcmp(name, "occl_visible")) { atomic_store(&g_occl_vis, v); MLOG("[flag] occl_visible = %d", v); return; }
    if (!strcmp(name, "drvfill")) { atomic_store(&g_drvfill_on, v != 0); MLOG("[flag] drvfill = %d", v != 0); return; }
    if (!strcmp(name, "ubo_snapshot")) { (void)usnap_on(); atomic_store(&g_usnap_on, v != 0); MLOG("[flag] ubo_snapshot = %d", v != 0); return; }
    MLOG("【红】unknown runtime flag %s", name);
}
/* TOTK diagnostic DM_NVN_TILELOG=WxH: every event on textures of that size (render, CPU texel read / write, invalidate,
   upload), to see the order of operations on one piece of memory; with it nvn_dirty.c also records who unprotects pages. */
static int tilelog_match(const tex_t *t) {
    static int on = -1; static unsigned w, h; if (on < 0) { const char *e = getenv("DM_NVN_TILELOG"); on = e && sscanf(e, "%ux%u", &w, &h) == 2; }
    return on && t && t->d.width == w && t->d.height == h;
}
#define TILELOG(t, fmt, ...) do { BOTW_TILELOG_NOTE(t) if (tilelog_match(t)) MLOG("[tile] f%llu ser=%llu mem=%p nvnfmt=%#x lv%u " fmt, (unsigned long long)atomic_load(&g_cur_frame), (unsigned long long)(t)->serial, (void *)(t)->mem, (t)->d.format, (t)->d.levels, ##__VA_ARGS__); } while (0)
static void wb_ent_free(wb_ent *e) { if (!e) return; if (e->obj) { defer_obj_release((__bridge id)e->obj); CFRelease(e->obj); } free(e); }
static void wb_note(const tex_t *t) {
    TILELOG(t, "GPU render (owned %d)", gpu_owned(t->serial));
    if (!atomic_load(&g_wb_on) || !t->mem || !t->L.size) return;
    id o = serial_get(t->serial); if (!o) return;
    /* CPU writes after this rendering show up in nvn_dirty_since. TOTK (#90): the stamp comes first; a write that faults while
       the pages are being protected then counts as after it (taken after, it covered that page, writable from then on). */
    uint64_t stamp = nvn_dirty_now(), k = t->serial;
    nvn_dirty_protect(t->mem, t->L.size);
    pthread_mutex_lock(&g_smu);
    wb_ent *e = nvn_hm_get(&g_wb, &k);
    if (e) { e->stamp = stamp; e->t = *t; pthread_mutex_unlock(&g_smu); return; }
    e = calloc(1, sizeof *e); if (!e) MDIE("write-back record");
    e->t = *t; e->stamp = stamp; e->obj = (void *)CFBridgingRetain(o);
    nvn_hm_put(&g_wb, &k, e);
    pthread_mutex_unlock(&g_smu);
}
static int wb_level_back(const tex_t *t, id<MTLTexture> mt, unsigned level, unsigned layer) {
    int bw, bh, bpb = nvn_fmt_bpb(t->d.format, &bw, &bh);
    uint32_t lw = MAX(t->d.width >> level, 1u), lh = MAX(t->d.height >> level, 1u);
    size_t lp = (size_t)((lw + bw - 1) / bw) * bpb, lr = (lh + bh - 1) / bh;
    /* This runs on the game's thread (nvnMemoryPoolInvalidateMappedRange), which has no autorelease pool: without one the
       autoreleased command buffer kept its blit encoder and this read-back buffer for ever (one 16 KiB buffer and one
       blit context per written-back level: Breath of the Wild writes back about 130 a second, 3.7 GB of GPU memory in 30
       minutes; TOTK's AGXG16GFamilyBuffer / BlitContext pairs growing by the thousands per lap were the same). */
    @autoreleasepool {
    id<MTLBuffer> buf = [g_dev newBufferWithLength:lp * lr options:MTLResourceStorageModeShared];
    if (!buf) return 0;
    id<MTLCommandBuffer> cb = q_cb(); id<MTLBlitCommandEncoder> b = enc_b_begin(cb);
    [b copyFromTexture:mt sourceSlice:layer sourceLevel:level sourceOrigin:MTLOriginMake(0, 0, 0) sourceSize:MTLSizeMake(lw, lh, 1)
              toBuffer:buf destinationOffset:0 destinationBytesPerRow:lp destinationBytesPerImage:lp * lr];
    enc_b_end(b); cb_commit(cb); cb_wait(cb);
    if (nvn_swizzle(&t->d, level, layer, (const uint8_t *)buf.contents, lp, t->mem)) return 0;
    g_wb_bytes += lp * lr;
    }
    return 1;
}
static void wb_write_list(wb_ent **list, int nl, int force);
/* Diagnostic TOTK_WB_EAGER=<w>x<h>: at every present, renderings of mirrored textures of that size are written back to
   memory without waiting for the game's invalidate (to see whether the CPU reads them from an uncached pool). */
void mtl_wb_eager(void) {
    static int on = -1; static unsigned w, h; if (on < 0) { const char *e = getenv("TOTK_WB_EAGER"); on = e && sscanf(e, "%ux%u", &w, &h) == 2; if (on) MLOG("TOTK_WB_EAGER: %ux%u renderings written back every frame", w, h); }
    if (!on || !atomic_load(&g_wb_on)) return;
    pthread_mutex_lock(&g_smu);
    wb_ent *list[512]; int nl = 0;
    for (uint32_t i = 0; i < g_wb.cap && nl < 512 && g_wb.n; i++) {
        wb_ent *e = g_wb.vals ? g_wb.vals[i] : NULL;
        if (!e || e->t.d.width != w || e->t.d.height != h) continue;
        uint64_t k = e->t.serial; nvn_hm_del(&g_wb, &k); list[nl++] = e; i = (uint32_t)-1;
    }
    pthread_mutex_unlock(&g_smu);
    wb_write_list(list, nl, 1);
}
void mtl_pool_invalidate(const pool_t *p, uint64_t off, uint64_t n) {
    if (!p || !p->mem || !atomic_load(&g_wb_on)) return;
    pthread_mutex_lock(&g_smu);
    if (!g_wb.n) { pthread_mutex_unlock(&g_smu); return; }
    const uint8_t *a = p->mem + off, *z = a + n;
    wb_ent *list[512]; int nl = 0;
    for (uint32_t i = 0; i < g_wb.cap && nl < 512; i++) {
        wb_ent *e = g_wb.vals ? g_wb.vals[i] : NULL;
        if (!e || e->t.mem >= z || e->t.mem + e->t.L.size <= a) continue;
        uint64_t k = e->t.serial; nvn_hm_del(&g_wb, &k); list[nl++] = e; i = (uint32_t)-1;   // deletion shifts entries: rescan
    }
    pthread_mutex_unlock(&g_smu);
    wb_write_list(list, nl, 0);
}
/* Writes the listed renderings back to memory (the entries are freed); force: even over CPU writes since the render. */
static void wb_write_list(wb_ent **list, int nl, int force) {
    if (!nl) return;
    { extern void nvn_x_drain(void) __attribute__((weak)); if (nvn_x_drain) nvn_x_drain(); }   // translation thread: nothing queued overtakes this read-back (as for ReadTexels)
    mtl_finish_gpu();
    /* Freshness is decided for every entry before anything is written back (a write-back marks its pages written), and
       of several renderings of the same memory (texture objects over it) only the newest is written back. */
    int fresh[512];
    for (int i = 0; i < nl; i++) fresh[i] = force || !nvn_dirty_since(list[i]->t.mem, list[i]->t.L.size, list[i]->stamp);
    for (int i = 0; i < nl; i++) for (int j = 0; j < nl; j++)
        if (i != j && fresh[i] && fresh[j] && list[j]->t.mem == list[i]->t.mem && list[j]->stamp > list[i]->stamp) { fresh[i] = 2; break; }   // 2: superseded
    for (int i = 0; i < nl; i++) {
        wb_ent *e = list[i]; const tex_t *t = &e->t;
        id o = (__bridge id)e->obj; id<MTLTexture> mt = [o isKindOfClass:[NvPkg class]] ? ((NvPkg *)o)->tex : o;
        uint32_t upf; int ubpp;
        if (fresh[i] == 2 || !mt) { wb_ent_free(e); continue; }   // !mt: copy evicted (pkg_evict_sweep) before the GPU rendered into it
        TILELOG(t, "write-back request: %s", !fresh[i] ? "CPU wrote since the render, skip" : "write back");
        if (tilelog_match(t) && !fresh[i]) {   // who wrote it
            extern int runtime_module_offset(uint64_t pc, const char **name, uint64_t *off);
            nvn_dirty_rec rec[64]; int nr = nvn_dirty_recent((uintptr_t)t->mem & ~(uintptr_t)16383, (uintptr_t)t->mem + t->L.size, rec, 64);
            char line[900]; size_t o2 = 0; int shown = 0; uint64_t seen[8]; int ns = 0;
            for (int q = nr - 1; q >= 0 && shown < 6 && o2 < sizeof line - 120; q--) {
                uint64_t pc = rec[q].pc; int dup = 0; for (int w = 0; w < ns; w++) if (seen[w] == pc) dup = 1; if (dup) continue; if (ns < 8) seen[ns++] = pc;
                const char *mn = "?", *ln = "?"; uint64_t mo = 0, lo2 = 0; int okp = runtime_module_offset(pc, &mn, &mo), okl = rec[q].lr && runtime_module_offset(rec[q].lr, &ln, &lo2);
                Dl_info di; if (!okp && dladdr((void *)(uintptr_t)pc, &di) && di.dli_fbase) { mn = di.dli_sname ? di.dli_sname : "host"; mo = pc - (uint64_t)(uintptr_t)di.dli_fbase + 0x100000000ull; okp = 1; }
                o2 += snprintf(line + o2, sizeof line - o2, " [%s pc=%s+%#llx lr=%s+%#llx page+%#llx]", rec[q].src ? "host" : "guest", okp ? mn : "?", (unsigned long long)(okp ? mo : pc),
                               okl ? ln : "-", (unsigned long long)(okl ? lo2 : 0), (unsigned long long)(rec[q].page - (uintptr_t)t->mem)); shown++;
            }
            TILELOG(t, "writers since the render (%d records):%s", nr, line);
        }
        if (!fresh[i]) {   // the CPU wrote it since: its bytes are newer
            if (++g_wb_skip_cpu <= 24) MLOG("[writeback] skipped (CPU wrote since the render) ser=%llu %ux%u nvnfmt=%#x lv%u", (unsigned long long)t->serial, t->d.width, t->d.height, t->d.format, t->d.levels);
            wb_ent_free(e); continue;
        }
        if (!mt || bc_unpack(t->d.format, &upf, &ubpp) || t->d.target == 2 || t->d.samples > 1) { if (++g_wb_skip_fmt <= 8) MLOG("【红】GPU 写回内存：不支持的贴图 ser=%llu 格式 %#x 目标 %d", (unsigned long long)t->serial, t->d.format, t->d.target); wb_ent_free(e); continue; }
        /* the GPU's bytes landing in memory: not a CPU write (with dm_guest_write_prepare the page this texture shares
           with a neighbour counted as written, and the neighbour's own write-back was skipped as "CPU wrote since") */
        void *tok = nvn_dirty_tracked(t->mem, t->L.size) ? nvn_dirty_gpu_write_begin(t->mem, t->L.size) : NULL;
        if (!tok) dm_guest_write_prepare(t->mem, t->L.size);
        unsigned layers = t->L.layers ? t->L.layers : 1, ok = 1;
        for (unsigned l = 0; l < t->d.levels && ok; l++) for (unsigned y = 0; y < layers && ok; y++) ok = wb_level_back(t, mt, l, y);
        nvn_dirty_gpu_write_end(tok);
        if (ok) { uint64_t d = ++g_wb_done; if (d <= 8 || d % 500 == 0) MLOG("[writeback] ser=%llu %ux%u nvnfmt=%#x lv%u：GPU 渲染结果写回内存（累计 %llu 张 / %llu MB，CPU 已改写而跳过 %llu 张）", (unsigned long long)t->serial, t->d.width, t->d.height, t->d.format, t->d.levels, (unsigned long long)d, (unsigned long long)(g_wb_bytes >> 20), (unsigned long long)g_wb_skip_cpu); }
        else MLOG("【红】GPU 写回内存失败 ser=%llu 格式 %#x", (unsigned long long)t->serial, t->d.format);
        wb_ent_free(e);
    }
}
static uint64_t g_pkg_uploads, g_pkg_reuploads, g_pkg_miss, g_pkg_restored;
static uint64_t g_pfv_upgrades;
// DM_NVN_DIRTYCHECK=1（诊断，对照真值）：每次使用都全量哈希池内容，变了却没被脏页跟踪检出 = 漏检
// DM_NVN_DIRTYCHECK=1 (diagnostic, compared against ground truth): fully hash the pool content on every use; changed but not detected by dirty-page tracking = a missed detection
static int dirtycheck(void) { static int v = -1; if (v < 0) v = getenv("DM_NVN_DIRTYCHECK") != NULL; return v; }
static uint64_t full_hash(const uint8_t *m, uint64_t n) { uint64_t h = 1469598103934665603ull; for (uint64_t i = 0; i < n; i++) h = (h ^ m[i]) * 1099511628211ull; return h; }
// 显卡不支持 BC 压缩格式（A15 / A16 等）：BC 贴图建成解压后的格式，上传 / 缓冲→贴图拷贝时在 CPU 上解压（nvn_bcdec.c）。
// 游戏贴图里的 BC3 由老机型补充包离线换成了 ASTC（dm/tools/astc_pack.py），走到这里的是剩下的少量 BC。测试开关 DM_TEST_NO_BC=1 在任何机器上强制走这条路
// The GPU does not support BC compressed formats (A15 / A16 etc.): BC textures are created in the decompressed format and decompressed on the CPU at upload / buffer→texture copy time (nvn_bcdec.c).
// BC3 among the game textures was converted to ASTC offline by the Legacy Device Pack (dm/tools/astc_pack.py); what reaches here is the small remainder of BC. The test switch DM_TEST_NO_BC=1 forces this path on any machine
static int no_bc(void) {
    static int v = -1;
    if (v < 0) { const char *e = getenv("DM_TEST_NO_BC"); v = (e && *e && strcmp(e, "0")) || ![g_dev supportsBCTextureCompression];
        if (v) MLOG("显卡不支持 BC 压缩格式%s：BC 贴图建成解压格式（BC1–5 在 GPU 上解压，BC6H / BC7 / 3D 在 CPU 上）", e && *e && strcmp(e, "0") ? "（测试开关 DM_TEST_NO_BC）" : ""); }
    return v;
}
static int bc_unpack(uint32_t nvn_fmt, uint32_t *pf, int *bpp) { return no_bc() && nvn_bc_unpacked(nvn_fmt, pf, bpp); }
/* TOTK, no BC (A15/A16): BC1 textures (most of TOTK's colour textures) become ASTC 4x4 instead of RGBA8: a quarter of the
   memory. Uploads transcode on the GPU (bc1astc kernel, tex/nvn_bc1astc_msl.h) after the deswizzle; CPU paths use the C
   transcoder (tex/nvn_bc1astc.c). 3D, 1D and multisample BC1 textures keep the decompressed path. TOTK_BC1_ASTC=0 turns
   it off. probe-bc1astc checks the transcoding through Metal's ASTC decoder. */
static int bc1_fmt(uint32_t f) { return f == 0x41 || f == 0x42 || f == 0x45 || f == 0x46; }
static int bc1_rgba(uint32_t f) { return f == 0x42 || f == 0x46; }
static MTLPixelFormat bc1_astc_pf(uint32_t f) { return (f == 0x45 || f == 0x46) ? MTLPixelFormatASTC_4x4_sRGB : MTLPixelFormatASTC_4x4_LDR; }
static int pf_astc4(NSUInteger pf) { return pf == MTLPixelFormatASTC_4x4_LDR || pf == MTLPixelFormatASTC_4x4_sRGB; }
static int astc_on(void) {
    static int v = -1;
    if (v < 0) { const char *e = getenv("TOTK_BC1_ASTC"); v = no_bc() && (!e || atoi(e)); if (v) MLOG("无 BC：BC1 贴图转成 ASTC 4x4（TOTK_BC1_ASTC=0 改回解压成 RGBA8）"); }
    return v;
}
static int tex_astc(const tex_t *t) { uint32_t g = t->d.target; return astc_on() && bc1_fmt(t->d.format) && (g == 1 || g == 4 || g == 7 || g == 8 || g == 9); }
/* TOTK, no BC: CPU-pool (mirrored) BC2/BC3/BC7 textures become ASTC 4x4 and unsigned BC4/BC5 EAC R11/RG11 instead of
   RGBA8 / R8 / RG8 (a quarter / half of the memory), transcoded on the GPU after the deswizzle (tex/nvn_bctc.metal,
   probe-gpu-bctc). Only uploads that take the GPU deswizzle path (pool-backed block-linear storage); others, GPU-owned
   textures and a copy the GPU starts rendering into keep the decompressed format. TOTK_BC_TRANSCODE=0 turns it off. */
static MTLPixelFormat tc_pf(uint32_t f) {
    switch (f) {
    case 0x43: case 0x44: case 0x4d: return MTLPixelFormatASTC_4x4_LDR;
    case 0x47: case 0x48: case 0x4e: return MTLPixelFormatASTC_4x4_sRGB;
    case 0x49: return MTLPixelFormatEAC_R11Unorm;
    case 0x4b: return MTLPixelFormatEAC_RG11Unorm;
    default: return MTLPixelFormatInvalid;
    }
}
static int tex_mirrored(const tex_t *t);
static id<MTLComputePipelineState> bctc_pso(void);
int mtl_addr(uint64_t addr, uint64_t len, void **buf, uint64_t *off);
static int g_mip_nodrop;   // set while re-uploading a copy at full size and in the decompressed format (the GPU renders into it)
static int tex_tc(const tex_t *t) {
    static int on = -1; if (on < 0) { const char *e = getenv("TOTK_BC_TRANSCODE"); on = no_bc() && (!e || atoi(e)); if (on) MLOG("无 BC：素材里的 BC2/BC3/BC7 转成 ASTC 4x4、BC4/BC5 转成 EAC（TOTK_BC_TRANSCODE=0 改回解压）"); }
    uint32_t g = t->d.target; void *mb; uint64_t mo;
    return on && !g_mip_nodrop && tc_pf(t->d.format) != MTLPixelFormatInvalid && (g == 1 || g == 4 || g == 7 || g == 8 || g == 9) && tex_mirrored(t)
        && g_nvn_deswz_gpu && !nvn_tex_is_linear(&t->d) && mtl_addr((uint64_t)t->mem, t->L.size, &mb, &mo) && bctc_pso();
}
// TOTK: NVN texture swizzle selectors (0/1 = constants, 2..5 = R..A) composed with the format remap of nvn_fmt_to_mtl.
// Returns 1 when the result is not the identity.
// A view with its own swizzle (view selectors non-NULL) replaces the texture's selectors.
static int tex_swizzle_sel(const tex_t *t, const uint8_t *view_sel, int format, MTLTextureSwizzleChannels *out) {
    uint32_t pf = 0; uint8_t swz[4] = {MTLTextureSwizzleRed, MTLTextureSwizzleGreen, MTLTextureSwizzleBlue, MTLTextureSwizzleAlpha};
    if (!nvn_fmt_to_mtl(format, &pf, swz)) return 0;
    unsigned sel[4] = {t->d.swizzle_r, t->d.swizzle_g, t->d.swizzle_b, t->d.swizzle_a};
    if (view_sel) for (unsigned i = 0; i < 4; i++) sel[i] = view_sel[i];
    MTLTextureSwizzle c[4];
    for (unsigned i = 0; i < 4; i++) c[i] = (MTLTextureSwizzle)(sel[i] < 2 ? sel[i] : swz[sel[i] - 2]);
    *out = MTLTextureSwizzleChannelsMake(c[0], c[1], c[2], c[3]);
    return c[0] != MTLTextureSwizzleRed || c[1] != MTLTextureSwizzleGreen || c[2] != MTLTextureSwizzleBlue || c[3] != MTLTextureSwizzleAlpha;
}
static int tex_swizzle(const tex_t *t, int format, MTLTextureSwizzleChannels *out) { return tex_swizzle_sel(t, NULL, format, out); }
static int swizzle_eq(MTLTextureSwizzleChannels a, MTLTextureSwizzleChannels b) { return a.red == b.red && a.green == b.green && a.blue == b.blue && a.alpha == b.alpha; }
static MTLTextureDescriptor *tex_desc(const tex_t *t, int packaged) {
    uint32_t pf = 0; uint8_t swz[4];
    if (!nvn_fmt_to_mtl(t->d.format, &pf, swz) || !pf) { RED_ONCE(0, "贴图格式 %#x Metal 无对应（首例）", t->d.format); return nil; }
    int unp = 0; { uint32_t upf; int ubpp; if (tex_astc(t)) pf = (uint32_t)bc1_astc_pf(t->d.format); else if (tex_tc(t)) pf = (uint32_t)tc_pf(t->d.format); else if (bc_unpack(t->d.format, &upf, &ubpp)) { pf = upf; unp = 1; } }
    MTLTextureDescriptor *d = [MTLTextureDescriptor new];
    d.pixelFormat = (MTLPixelFormat)pf;
    d.width = t->d.width ? t->d.width : 1; d.height = t->d.height ? t->d.height : 1; d.depth = 1; d.arrayLength = 1;
    d.mipmapLevelCount = t->d.levels ? t->d.levels : 1;
    switch (t->d.target) {
        case 0: d.textureType = MTLTextureType1D; d.height = 1; break;
        case 2: d.textureType = MTLTextureType3D; d.depth = t->d.depth; break;
        case 3: d.textureType = MTLTextureType1DArray; d.arrayLength = t->d.height; d.height = 1; break;
        case 4: d.textureType = MTLTextureType2DArray; d.arrayLength = t->d.depth; break;
        case 5: d.textureType = MTLTextureType2DMultisample; d.sampleCount = t->d.samples; d.mipmapLevelCount = 1; break;
        case 6: d.textureType = MTLTextureType2DMultisampleArray; d.sampleCount = t->d.samples; d.arrayLength = t->d.depth; d.mipmapLevelCount = 1; break;
        case 8: d.textureType = MTLTextureTypeCube; break;
        case 9: d.textureType = MTLTextureTypeCubeArray; d.arrayLength = t->d.depth; break;
        case 10: RED_ONCE(1, "缓冲贴图（TARGET_BUFFER）未实现"); return nil;
        default: d.textureType = MTLTextureType2D; break;
    }
    d.storageMode = MTLStorageModePrivate;   // 渲染目标与素材都放 GPU 私有存储（可用无损压缩） | Render targets and assets both go in GPU private storage (lossless compression available)
    d.usage = MTLTextureUsageShaderRead | (fmt_compressed(t->d.format) || packaged ? 0 : MTLTextureUsageRenderTarget)
            | (t->d.flags & NVN_TEXTURE_FLAGS_IMAGE ? MTLTextureUsageShaderWrite : 0)   // 图像用途：着色器可写（计算核生成 3D 调色表等） | Image usage: shader-writable (compute kernels generating the 3D color lookup table, etc.)
            | (t->d.target == 8 && t->d.width <= 64 && !fmt_compressed(t->d.format) && !packaged ? MTLTextureUsageShaderWrite : 0)   // TOTK: small cube render targets: the cube-merge copy-out kernel writes them (nvn_cube_group.h)
            | (unp ? MTLTextureUsageShaderWrite | MTLTextureUsagePixelFormatView : 0);
    // TOTK: Metal rejects descriptor swizzle on render targets and on shader-writable textures (image use, and BC textures
    // decoded by the bcd kernel on GPUs without BC support); those get the swizzle on their sampling view (tex_by_id).
    MTLTextureSwizzleChannels sw;
    if (tex_swizzle(t, t->d.format, &sw) && !(d.usage & (MTLTextureUsageRenderTarget | MTLTextureUsageShaderWrite))) d.swizzle = sw;
    return d;
}
// 就地升级：原贴图没开 PixelFormatView（缺省不开，保住苹果显卡无损压缩）却要建换格式视图时，按原规格 + PixelFormatView 新建、逐 slice × level 拷过去并替换登记。
// 计数：选角 / 营地 / 野外 / 战斗 4 页 17473 张贴图换格式视图 0 次，所以这里是兜底，不靠预测哪些贴图需要
// In-place upgrade: when the original texture was not created with PixelFormatView (off by default, to keep Apple GPU lossless compression) but a different-format view is needed, create a new one with the original spec + PixelFormatView, copy over every slice × level, and replace the registration.
// Count: across the 4 screens character select / camp / wilderness / combat, 17473 textures needed a different-format view 0 times, so this is a fallback and does not rely on predicting which textures need it
static id<MTLTexture> tex_upgrade_pfv(const tex_t *t, id<MTLTexture> base, MTLPixelFormat view_pf) {
    if (g_tex_preparing && rp_active()) { g_tex_prepare_split = 1; return base; }
    { stor_key k;   // TOTK: a storage-shared base is recreated for every serial holding it, then this serial re-resolves
      if (stor_key_lookup(base, &k)) { if (!stor_recreate(&k, base.usage | MTLTextureUsagePixelFormatView)) return base; id<MTLTexture> nb = tex_mtl(t); return nb ? nb : base; } }
    MTLTextureDescriptor *d = [MTLTextureDescriptor new];
    d.textureType = base.textureType; d.pixelFormat = base.pixelFormat; d.width = base.width; d.height = base.height; d.depth = base.depth;   // 保留原格式，只加换格式视图用途 | Keep the original format, only add the format-view usage
    d.swizzle=base.swizzle;
    d.arrayLength = base.arrayLength; d.mipmapLevelCount = base.mipmapLevelCount; d.sampleCount = base.sampleCount;
    d.storageMode = base.storageMode; d.cpuCacheMode = base.cpuCacheMode; d.hazardTrackingMode = base.hazardTrackingMode;
    d.resourceOptions = base.resourceOptions; d.usage = base.usage | MTLTextureUsagePixelFormatView;
    id<MTLTexture> upgraded = [g_dev newTextureWithDescriptor:d];
    if (!upgraded) { RED_ONCE(45, "贴图升级失败 ser=%llu 格式 %lu → %lu", t->serial, (unsigned long)base.pixelFormat, (unsigned long)view_pf); return base; }
    res_add(upgraded);
    id<MTL4ComputeCommandEncoder> b = blit();
    NSUInteger slices = base.textureType == MTLTextureType3D ? 1 : base.arrayLength * (base.textureType == MTLTextureTypeCube || base.textureType == MTLTextureTypeCubeArray ? 6 : 1);
    for (NSUInteger l = 0; l < base.mipmapLevelCount; l++) {
        NSUInteger w = MAX(base.width >> l, 1u), h = MAX(base.height >> l, 1u), z = base.textureType == MTLTextureType3D ? MAX(base.depth >> l, 1u) : 1;
        if (base.textureType == MTLTextureType3D)
            enc_b_copy_texture(b, base, 0, l, MTLOriginMake(0, 0, 0), MTLSizeMake(w, h, z), upgraded, 0, l, MTLOriginMake(0, 0, 0));
        else for (NSUInteger s = 0; s < slices; s++)
            enc_b_copy_texture(b, base, s, l, MTLOriginMake(0, 0, 0), MTLSizeMake(w, h, 1), upgraded, s, l, MTLOriginMake(0, 0, 0));
    }
    id holder = serial_get(t->serial);
    if ([holder isKindOfClass:[NvPkg class]]) { id<MTLTexture> old = ((NvPkg *)holder)->tex; ((NvPkg *)holder)->tex = upgraded; memset(&((NvPkg *)holder)->key, 0, sizeof(reup_key)); defer_obj_release(old); ser_bump(t->serial); }   // key 0: the upgraded texture is not recycled
    else serial_put(t->serial, upgraded);
    MLOG("贴图升级为可换格式视图 ser=%llu 基格式 %lu → 视图格式 %lu（升级次数=%llu）", t->serial, (unsigned long)base.pixelFormat, (unsigned long)view_pf, ++g_pfv_upgrades);
    return upgraded;
}
static int stor_key_lookup(id o, stor_key *k) {
    if (!o) return 0; uint64_t ok = obj_key(o);
    pthread_mutex_lock(&g_smu); stor_ent *e = nvn_hm_get(&g_stor_of_obj, &ok); if (e) *k = e->k; pthread_mutex_unlock(&g_smu);
    return e != NULL;
}
/* g_smu held. Serials still holding the entry lose their table entries (they re-resolve on next use); the base is
   retired once the submissions using it complete. */
static void stor_release_holders_locked(stor_ent *e) {
    for (int i = 0; i < e->nser; i++) {
        uint64_t s = e->ser[i]; id o = hm_get_id(&g_by_serial, &s); if (!o) continue;
        uint64_t ok = obj_key(o); if (ok != (uint64_t)(uintptr_t)e->tex) nvn_hm_del(&g_stor_of_obj, &ok);
        defer_obj_unref(o); hm_del_id(&g_by_serial, &s); BOTW_SERIAL_NOTE(s, "storage entry dropped")
    }
    e->nser = 0; ser_bump_locked(0);
}
static void stor_drop_locked(stor_ent *e) {
    stor_release_holders_locked(e);
    uint64_t bk = (uint64_t)(uintptr_t)e->tex; nvn_hm_del(&g_stor_of_obj, &bk); nvn_hm_del(&g_by_storage, &e->k);
    defer_obj_release((__bridge id)e->tex); CFRelease(e->tex);
    free(e->ser); free(e);
}
/* Replaces the entry's base by one with the requested usage, content copied on the GPU timeline (submit thread only). */
static id<MTLTexture> stor_recreate(const stor_key *k, MTLTextureUsage usage) {
    if (g_tex_preparing && rp_active()) { g_tex_prepare_split = 1; return nil; }
    if (!on_sub_thread() || rp_active()) {   // the copy is a blit, which would end the open render pass under its draw; the serial then keeps a texture of its own
        static uint64_t n; if (++n <= 4) MLOG("storage-shared texture recreate refused (%s): the serial keeps a texture of its own", on_sub_thread() ? "inside a render pass" : "not on the submit thread");
        return nil; }
    pthread_mutex_lock(&g_smu); stor_ent *e = nvn_hm_get(&g_by_storage, k); id<MTLTexture> base = e ? (__bridge id<MTLTexture>)e->tex : nil; pthread_mutex_unlock(&g_smu);
    if (!base) return nil;
    MTLTextureDescriptor *d = [MTLTextureDescriptor new];
    d.textureType = base.textureType; d.pixelFormat = base.pixelFormat; d.width = base.width; d.height = base.height; d.depth = base.depth;
    d.swizzle = base.swizzle; d.arrayLength = base.arrayLength; d.mipmapLevelCount = base.mipmapLevelCount; d.sampleCount = base.sampleCount;
    d.storageMode = base.storageMode; d.cpuCacheMode = base.cpuCacheMode; d.hazardTrackingMode = base.hazardTrackingMode;
    d.resourceOptions = base.resourceOptions; d.usage = usage;
    id<MTLTexture> nt = [g_dev newTextureWithDescriptor:d];
    if (!nt) { RED_ONCE(120, "storage-shared texture recreate failed %lux%lu format %lu usage %#lx", (unsigned long)base.width, (unsigned long)base.height, (unsigned long)base.pixelFormat, (unsigned long)usage); return nil; }
    res_add(nt);
    if (base.sampleCount <= 1) {
        id<MTL4ComputeCommandEncoder> b = blit();
        NSUInteger slices = base.textureType == MTLTextureType3D ? 1 : base.arrayLength * (base.textureType == MTLTextureTypeCube || base.textureType == MTLTextureTypeCubeArray ? 6 : 1);
        for (NSUInteger l = 0; l < base.mipmapLevelCount; l++) {
            NSUInteger w = MAX(base.width >> l, 1u), h = MAX(base.height >> l, 1u), z = base.textureType == MTLTextureType3D ? MAX(base.depth >> l, 1u) : 1;
            if (base.textureType == MTLTextureType3D) enc_b_copy_texture(b, base, 0, l, MTLOriginMake(0, 0, 0), MTLSizeMake(w, h, z), nt, 0, l, MTLOriginMake(0, 0, 0));
            else for (NSUInteger s = 0; s < slices; s++) enc_b_copy_texture(b, base, s, l, MTLOriginMake(0, 0, 0), MTLSizeMake(w, h, 1), nt, s, l, MTLOriginMake(0, 0, 0));
        }
    }
    pthread_mutex_lock(&g_smu);
    e = nvn_hm_get(&g_by_storage, k);
    if (!e || (__bridge void *)base != e->tex) { pthread_mutex_unlock(&g_smu); defer_obj_release(nt); return nil; }   // the entry went away meanwhile (pool finalised)
    stor_release_holders_locked(e);
    uint64_t bk = (uint64_t)(uintptr_t)e->tex; nvn_hm_del(&g_stor_of_obj, &bk);
    defer_obj_release(base); CFRelease(e->tex);
    e->tex = (void *)CFBridgingRetain(nt); bk = (uint64_t)(uintptr_t)e->tex; nvn_hm_put(&g_stor_of_obj, &bk, e);
    uint64_t n = ++g_stor_recreated;
    pthread_mutex_unlock(&g_smu);
    if (n <= 8) MLOG("storage-shared texture recreated with usage %#lx (%lux%lu format %lu, %llu so far)", (unsigned long)usage, (unsigned long)base.width, (unsigned long)base.height, (unsigned long)base.pixelFormat, (unsigned long long)n);
    return nt;
}
/* NVN compression: a compressible texture in a compressible pool keeps its contents in compressed form, and a clear only
   sets the compression state - the bytes under it stay as they were. A descriptor that reads the same storage in another
   format therefore does not see such writes on hardware. 2026-10-15, the frame-wide flashes: when the game moved the
   linear depth to new memory, the deferred lighting kept reading the old depth descriptor for two frames, while the old
   memory already belonged to an RGBA8 target cleared to white; with one shared Metal texture every depth texel read
   0xFFFFFFFF = NaN, the lighting turned NaN and bloom / exposure spread it over the frame.
   So compressible textures share storage only with the same format or its sRGB / linear twin. When one of another format
   arrives, the storage changes hands: the current entry is detached (kept, with its content, for the serials and stale
   descriptors still holding it) and the newcomer's format owns the storage; a detached entry of the newcomer's format is
   taken back instead of creating a new texture, so a buffer re-initialised every frame keeps last frame's content.
   Detached entries go when nobody has held them for STOR_IDLE_SUBMITS submissions or their pool is finalised.
   TOTK_COMPRESSED_ALIAS=1 shares across formats as before (A/B). */
static uint64_t g_stor_handover, g_stor_taken_back;
static stor_ent **g_stor_det; static int g_stor_ndet, g_stor_cdet;   // detached entries (g_smu)
static int stor_compressed(const tex_t *t) { return (t->d.flags & NVN_TEXTURE_FLAGS_COMPRESSIBLE) && t->pool && (t->pool->flags & NVN_MEMORY_POOL_FLAGS_COMPRESSIBLE); }
static int compressed_alias_on(void) { static int on = -1; if (on < 0) { const char *e = getenv("TOTK_COMPRESSED_ALIAS"); on = e && atoi(e); } return on; }
static void stor_det_push_locked(stor_ent *e) {
    if (g_stor_ndet == g_stor_cdet) { g_stor_cdet = g_stor_cdet ? g_stor_cdet * 2 : 16; g_stor_det = realloc(g_stor_det, (size_t)g_stor_cdet * sizeof *g_stor_det); if (!g_stor_det) MDIE("detached storage list"); }
    g_stor_det[g_stor_ndet++] = e;
}
/* A detached entry for this storage whose base reads in pixel format pf (itself or its sRGB / linear twin), removed from the list. */
static stor_ent *stor_det_take_locked(const stor_key *k, MTLPixelFormat pf) {
    for (int i = 0; i < g_stor_ndet; i++) {
        stor_ent *d = g_stor_det[i]; MTLPixelFormat bf = ((__bridge id<MTLTexture>)d->tex).pixelFormat;
        if (!memcmp(&d->k, k, sizeof *k) && (bf == pf || !tex_need_pfv(bf, pf))) { g_stor_det[i] = g_stor_det[--g_stor_ndet]; return d; }
    }
    return NULL;
}
/* g_smu held: like stor_drop_locked, for an entry that is no longer in g_by_storage (its key may belong to another entry). */
static void stor_det_drop_locked(stor_ent *e) {
    stor_release_holders_locked(e);
    uint64_t bk = (uint64_t)(uintptr_t)e->tex; nvn_hm_del(&g_stor_of_obj, &bk);
    defer_obj_release((__bridge id)e->tex); CFRelease(e->tex);
    free(e->ser); free(e);
}
static void stor_det_sweep(int (^pick)(const stor_ent *), uint64_t *counter) {
    pthread_mutex_lock(&g_smu);
    for (int i = 0; i < g_stor_ndet; ) {
        stor_ent *d = g_stor_det[i];
        if (pick(d)) { g_stor_det[i] = g_stor_det[--g_stor_ndet]; stor_det_drop_locked(d); (*counter)++; } else i++;
    }
    pthread_mutex_unlock(&g_smu);
}
/* The object a serial should hold for texture t when another serial already has the same storage and layout:
   the shared base, or a format view on it. nil: the caller creates a texture of its own and publishes it. */
static id<MTLTexture> stor_acquire(const tex_t *t, MTLTextureDescriptor *d) {
    stor_key k; if (!stor_on() || !stor_key_of(t, &k)) return nil;
    MTLPixelFormat pf = d.pixelFormat;
    pthread_mutex_lock(&g_smu);
    stor_ent *e = nvn_hm_get(&g_by_storage, &k); id<MTLTexture> base = e ? (__bridge id<MTLTexture>)e->tex : nil;
    if (!base) { pthread_mutex_unlock(&g_smu); return nil; }
    int pfv = pf != base.pixelFormat && tex_need_pfv(base.pixelFormat, pf);
    if (pfv && stor_compressed(t) && !compressed_alias_on()) {   /* another format of compressed storage: it changes hands (see stor_compressed) */
        MTLPixelFormat bf = base.pixelFormat;
        stor_ent *back = stor_det_take_locked(&k, pf);
        nvn_hm_del(&g_by_storage, &e->k); stor_det_push_locked(e);
        uint64_t n = ++g_stor_handover;
        if (back) { nvn_hm_put(&g_by_storage, &back->k, back); e = back; base = (__bridge id<MTLTexture>)back->tex; pfv = pf != base.pixelFormat && tex_need_pfv(base.pixelFormat, pf); g_stor_taken_back++; }
        if (n <= 8) MLOG("compressible texture serial %llu (NVN format %#x, Metal %lu, %ux%u) takes over storage %p from Metal format %lu%s (%llu so far)",
                         (unsigned long long)t->serial, t->d.format, (unsigned long)pf, t->d.width, t->d.height, (void *)t->mem, (unsigned long)bf,
                         back ? ", back on its earlier texture" : ", with a new texture", (unsigned long long)n);
        if (!back) { pthread_mutex_unlock(&g_smu); return nil; }   /* the caller creates the texture and publishes it as the storage's owner */
    }
    MTLTextureUsage want = base.usage | d.usage | (pfv ? MTLTextureUsagePixelFormatView : 0);
    if (want == base.usage && pf == base.pixelFormat) { g_stor_shared++; pthread_mutex_unlock(&g_smu); goto logged; }
    pthread_mutex_unlock(&g_smu);
    if (want != base.usage) { base = stor_recreate(&k, want); if (!base) return nil; }
    if (pf != base.pixelFormat) {
        id<MTLTexture> v = [base newTextureViewWithPixelFormat:pf];
        if (!v) { RED_ONCE(121, "storage-shared format view %lu on %lu failed", (unsigned long)pf, (unsigned long)base.pixelFormat); return nil; }
        pthread_mutex_lock(&g_smu);
        e = nvn_hm_get(&g_by_storage, &k);
        if (!e || (__bridge void *)base != e->tex) { pthread_mutex_unlock(&g_smu); return nil; }
        uint64_t ok = obj_key(v); nvn_hm_put(&g_stor_of_obj, &ok, e); g_stor_viewed++;
        pthread_mutex_unlock(&g_smu);
