        [b setArgumentTable:g_up_ct]; [b setComputePipelineState:bc1astc_pso()];
        for (int i = 0; i < g_nup_tcas; i++) { up_tca *x = &g_up_tcas[i];
            [g_up_ct setAddress:x->src.gpuAddress atIndex:0]; [g_up_ct setAddress:x->params.gpuAddress + x->poff atIndex:1]; [g_up_ct setAddress:x->dst.gpuAddress atIndex:2];
            [b dispatchThreadgroups:MTLSizeMake((x->bw + 7) / 8, (x->bh + 7) / 8, 1) threadsPerThreadgroup:MTLSizeMake(8, 8, 1)]; }
        [b barrierAfterEncoderStages:MTLStageDispatch beforeEncoderStages:MTLStageBlit | MTLStageDispatch visibilityOptions:MTL4VisibilityOptionDevice];
    }
    if (b && g_nup_tcxs) {   // BC2/3/4/5/7 -> ASTC / EAC (tex_tc), like the BC1 jobs above
        [b setArgumentTable:g_up_ct]; [b setComputePipelineState:bctc_pso()];
        for (int i = 0; i < g_nup_tcxs; i++) { up_tca *x = &g_up_tcxs[i];
            [g_up_ct setAddress:x->src.gpuAddress atIndex:0]; [g_up_ct setAddress:x->params.gpuAddress + x->poff atIndex:1]; [g_up_ct setAddress:x->dst.gpuAddress atIndex:2];
            [b dispatchThreadgroups:MTLSizeMake((x->bw + 7) / 8, (x->bh + 7) / 8, 1) threadsPerThreadgroup:MTLSizeMake(8, 8, 1)]; }
        [b barrierAfterEncoderStages:MTLStageDispatch beforeEncoderStages:MTLStageBlit | MTLStageDispatch visibilityOptions:MTL4VisibilityOptionDevice];
    }
    for (int i = 0; b && i < g_nup_blits; i++) {
        up_blit *x = &g_up_blits[i];
        enc_b_copy_buffer_texture(b, x->src, x->off, x->row, x->image, x->size, x->dst, x->slice, x->level, MTLOriginMake(0, 0, 0));
    }
    if (b && g_nup_decs) {   // 无 BC 的 GPU 解压（见 up_dec）：参数块里的偏移相对暂存块起点 | GPU decompression without BC (see up_dec): offsets in the parameter block are relative to the start of the staging block
        [b setArgumentTable:g_up_ct]; [b setComputePipelineState:bcd_pso()];
        for (int i = 0; i < g_nup_decs; i++) { up_dec *x = &g_up_decs[i];
            [g_up_ct setAddress:x->src.gpuAddress atIndex:0]; [g_up_ct setAddress:x->params.gpuAddress + x->poff atIndex:1]; [g_up_ct setTexture:x->view.gpuResourceID atIndex:0];
            [b dispatchThreadgroups:MTLSizeMake((x->bw + 7) / 8, (x->bh + 7) / 8, 1) threadsPerThreadgroup:MTLSizeMake(8, 8, 1)]; }
    }
    if (b) { m4_end(b); g_up_ce = nil; }
    id<MTL4CommandBuffer> cb = g_up_cb;
    unsigned slot = (g_up_seq - 1) % 3;
    NSMutableArray *dsts = [NSMutableArray arrayWithCapacity:(NSUInteger)g_nup_blits]; for (int i = 0; i < g_nup_blits; i++) if (g_up_blits[i].dst) [dsts addObject:g_up_blits[i].dst];
    static int lost_at = -2; static uint64_t batch_n; if (lost_at == -2) { const char *e = getenv("DM_TEST_UP_LOST"); lost_at = e ? atoi(e) : -1; } int fake_lost = dsts.count && lost_at > 0 && (int)++batch_n == lost_at;
    TotkCommitOptions *o = [TotkCommitOptions new];
    NSMutableArray *staging = [g_up_keep mutableCopy];
    if (!staging) staging = [NSMutableArray array];
    if (g_up_block && !g_up_block_pooled) [staging addObject:g_up_block];
    if (g_up_sblock && !g_up_sblock_pooled) [staging addObject:g_up_sblock];
    uint32_t pool_mask = g_up_batch_pool, spool_mask = g_up_batch_spool;
    atomic_fetch_add(&g_up_pending, 1);
    [o addFeedbackHandler:^(id<MTL4CommitFeedback> f) {
        if (f.error) MLOG("【红】上传命令缓冲执行出错：%s", f.error.description.UTF8String);
        if (f.error || fake_lost) {
            os_unfair_lock_lock(&g_up_lost_lk); if (!g_up_lost) g_up_lost = [NSHashTable weakObjectsHashTable]; for (id d in dsts) [g_up_lost addObject:d]; int n = (int)g_up_lost.allObjects.count; atomic_store(&g_up_lost_n, n); os_unfair_lock_unlock(&g_up_lost_lk);
            ser_bump(0);   // 让各贴图号的视图缓存走一次慢路（缓存命中时不会经过 tex_mtl，看不到这份记录） | Make the view cache of every texture ID take the slow path once (on a cache hit tex_mtl is not passed through and this record is not seen)
            MLOG("%s上传命令缓冲被丢：这一批 %lu 张贴图记为内容未写，下次取用时重传（待重传共 %d 张）", fake_lost ? "DM_TEST_UP_LOST：" : "", (unsigned long)dsts.count, n);
        }
        double d = f.GPUEndTime - f.GPUStartTime;
        if (d > 0) atomic_fetch_add(&g_upload_gpu_ns, (uint64_t)(d * 1e9));
        for (id obj in staging) res_remove(obj);
        [staging removeAllObjects];
        for (int i = 0; i < UP_POOL; i++) if (pool_mask >> i & 1) atomic_store(&g_up_pool_busy[i], 0);
        for (int i = 0; i < UP_SPOOL; i++) if (spool_mask >> i & 1) atomic_store(&g_up_spool_busy[i], 0);
        pthread_mutex_lock(&g_up_slot_mu); atomic_store(&g_up_alloc_busy[slot], 0); pthread_cond_broadcast(&g_up_slot_cv); pthread_mutex_unlock(&g_up_slot_mu);
        atomic_fetch_sub(&g_up_pending, 1);
    }];
    res_commit();
    [cb endCommandBuffer];
    q4_commit(cb, o);
    g_up_cb = nil; g_up_block = nil; g_up_block_off = g_up_block_size = 0; g_up_batch_bytes = 0; g_up_block_pooled = 0; g_up_batch_pool = 0;
    g_up_sblock = nil; g_up_sblock_off = g_up_sblock_size = 0; g_up_sblock_pooled = 0; g_up_batch_spool = 0;
    [g_up_keep removeAllObjects];
    up_diag();
    g_nup_blits = 0; g_nup_decs = 0; g_nup_tcas = 0; g_nup_tcxs = 0;
    [g_up_texs removeAllObjects];
}

void mtl_upload_wait_stats(uint64_t *n, uint64_t *ns) { *n = atomic_load(&g_up_slot_waits); *ns = atomic_load(&g_up_slot_wait_ns); }
static void up_begin(void) {
    up_owner_check("up_begin");
    if (g_up_cb) return;
    unsigned slot = g_up_seq++ % 3;
    if (atomic_load(&g_up_alloc_busy[slot])) {
        uint64_t w0 = bp_now(); pthread_mutex_lock(&g_up_slot_mu);
        while (atomic_load(&g_up_alloc_busy[slot])) pthread_cond_wait(&g_up_slot_cv, &g_up_slot_mu);
        pthread_mutex_unlock(&g_up_slot_mu); atomic_fetch_add(&g_up_slot_waits, 1); atomic_fetch_add(&g_up_slot_wait_ns, bp_now() - w0);
    }
    atomic_store(&g_up_alloc_busy[slot], 1);
    [g_up_alloc4[slot] reset];
    g_up_cb = [g_dev newCommandBuffer];
    [g_up_cb beginCommandBufferWithAllocator:g_up_alloc4[slot]];
    g_up_ce = [g_up_cb computeCommandEncoder];
    [g_up_ce barrierAfterQueueStages:MTLStageAll beforeStages:MTLStageAll visibilityOptions:MTL4VisibilityOptionDevice];
    [g_up_ce setArgumentTable:g_up_ct];
    if (!g_up_texs) g_up_texs = [NSMutableArray array];
    if (!g_up_keep) g_up_keep = [NSMutableArray array];
}
static void up_reserve(size_t n) {
    if (g_up_batch_bytes && n > g_up_batch_limit - MIN(g_up_batch_bytes, g_up_batch_limit)) {
        up_flush(); up_begin();
    }
    g_up_batch_bytes += n;
}

// 诊断读数（低频，换块次数有变化且距上一行 ≥ 1 秒才打，一局最多 200 行）：一批上传里暂存块放不下、中途换了几次块；显卡已分配、驻留集对象数、延迟释放队列长度。
// 换块时旧块若没退役，它留在驻留集里永远放不掉，「显卡已分配」会随换块次数一块一块往上涨
// Diagnostic readout (low frequency; printed only when the block switch count changed and ≥ 1 second since the last line, at most 200 lines per game): how many times an upload batch ran out of staging block and switched blocks midway; GPU allocated, residency set object count, deferred-release queue length.
// If the old block is not retired on a switch it stays in the residency set and can never be freed, and "GPU allocated" climbs one block at a time with the switch count
static uint64_t g_up_blocks_new, g_up_swaps, g_up_swap_bytes; static NSHashTable *g_up_old;   // g_up_old：换下的旧块（弱引用），诊断行数它们还活着几块 | g_up_old: old blocks switched out (weak references); the diagnostic line counts how many are still alive
static void up_diag(void) {
    // 换块次数变了打一行；之后过 5 秒再补一行（那一批提交早已跑完、延迟退役也排空了，「显卡已分配」是落定后的数）
    // Print a line when the block switch count changes; then one more line 5 seconds later (that batch's commit is long done and deferred retirement drained, so "GPU allocated" is the settled number)
    static uint64_t said_swaps = ~0ull, last_ns; static int lines, follow; uint64_t now = clock_gettime_nsec_np(CLOCK_MONOTONIC);
    int chg = g_up_swaps != said_swaps, fol = follow && now - last_ns >= 5000000000ull; if ((!chg && !fol) || lines >= 200) return;
    if (chg && last_ns && now - last_ns < 1000000000ull) return; last_ns = now; said_swaps = g_up_swaps; lines++; follow = chg;
    unsigned long alive = 0, inres = 0; uint64_t abytes = 0; NSArray *olds = g_up_old.allObjects;
    pthread_mutex_lock(&g_res_mu); unsigned long nres = (unsigned long)g_res_objects.allObjects.count; for (id<MTLBuffer> o in olds) { alive++; abytes += o.length; inres += [g_res_objects containsObject:o]; } pthread_mutex_unlock(&g_res_mu);
    pthread_mutex_lock(&g_deferred_mu); unsigned long ndef = (unsigned long)g_deferred.count; pthread_mutex_unlock(&g_deferred_mu);
    MLOG("上传暂存块%s：累计新建 %llu 块、其中一批内换块 %llu 次（换下的旧块共 %llu MB）；换下的旧块此刻还活着 %lu 块 %llu MB、仍在驻留集 %lu 块；显卡已分配 %llu MB、驻留集 %lu 个对象、延迟释放队列 %lu", fol && !chg ? "（落定后）" : "",
         (unsigned long long)g_up_blocks_new, (unsigned long long)g_up_swaps, (unsigned long long)(g_up_swap_bytes >> 20), alive, (unsigned long long)(abytes >> 20), inres, (unsigned long long)(g_dev.currentAllocatedSize >> 20), nres, ndef);
}
static id<MTLBuffer> up_alloc(size_t n, size_t *off) {
    size_t need = (n + 255u) & ~((size_t)255u);
    if (!g_up_block || g_up_block_off + need > g_up_block_size) {
        up_reserve(n > UP_BLOCK_SIZE ? need : UP_BLOCK_SIZE);
        // 换块：旧块还被这一批已经登记的拷贝 / 解压命令引用着，不能当场放；交给 g_up_keep，在本批上传完成时撤出驻留集并释放。
        // 原先这里直接把 g_up_block 换成新块：旧块没人退役、却一直留在驻留集里，一批上传每多换一次块就漏掉一块（通常 32 MB）显卡内存。
        // 旧块与冲刷时退役的「当前块」是两个对象，不会重复退役
        // Block switch: the old block is still referenced by copy / decompress commands already recorded in this batch and cannot be freed on the spot; hand it to g_up_keep, then remove residency and release it when this upload batch completes.
        // Previously g_up_block was simply replaced with the new block here: nobody retired the old block, yet it stayed in the residency set, so each extra block switch in an upload batch leaked one block (usually 32 MB) of GPU memory.
        // The old block and the "current block" retired at flush are two objects, so nothing is retired twice
        g_up_blocks_new++; if (g_up_block && !g_up_block_pooled) { g_up_swaps++; g_up_swap_bytes += g_up_block_size; if (!g_up_old) g_up_old = [NSHashTable weakObjectsHashTable]; [g_up_old addObject:g_up_block]; static int leak = -1; if (leak < 0) leak = getenv("DM_TEST_UP_LEAK") != NULL;   // 测试开关 DM_TEST_UP_LEAK=1：照修前的做法不退役旧块（对照用，量漏多少） | test switch DM_TEST_UP_LEAK=1: do not retire the old block, as before the fix (for comparison, to measure the leak)
            if (!leak) { if (!g_up_keep) g_up_keep = [NSMutableArray array]; [g_up_keep addObject:g_up_block]; } }
        g_up_block_size = n > UP_BLOCK_SIZE ? need : UP_BLOCK_SIZE;
        int pi = n > UP_BLOCK_SIZE ? -1 : up_pool_take(g_up_pool, g_up_pool_busy, &g_up_pool_n, UP_POOL_USE, &g_up_batch_pool, UP_BLOCK_SIZE, MTLResourceStorageModePrivate);
        if (pi >= 0) { g_up_block = g_up_pool[pi]; g_up_block_pooled = 1; }
        else {
            g_up_block = [g_dev newBufferWithLength:g_up_block_size options:MTLResourceStorageModePrivate];
            if (!g_up_block) MDIE("建预排布上传暂存块失败 %#zx", g_up_block_size);
            res_add(g_up_block); g_up_block_pooled = 0;
        }
        g_up_block_off = 0;
    }
    *off = g_up_block_off;
    g_up_block_off += need;
    return g_up_block;
}

// 解排布参数块：64 字节一格，从 64 KB 共享存储块里顺序切；块满换新，旧块按栅栏延迟释放
// Deswizzle parameter blocks: 64 bytes per cell, cut sequentially from a 64 KB shared-storage block; a full block is replaced by a new one, and the old block is released lazily by fence
static id<MTLBuffer> g_up_pblock; static size_t g_up_pblock_off;
static id<MTLBuffer> up_param_alloc(size_t *off) {
    if (!g_up_pblock || g_up_pblock_off + 64 > g_up_pblock.length) {
        if (g_up_pblock) defer_obj_release(g_up_pblock);
        g_up_pblock = [g_dev newBufferWithLength:64 << 10 options:MTLResourceStorageModeShared];
        if (!g_up_pblock) MDIE("建解排布参数块失败");
        res_add(g_up_pblock); g_up_pblock_off = 0;
    }
    *off = g_up_pblock_off; g_up_pblock_off += 64;
    return g_up_pblock;
}
static void up_blit_add(id<MTLBuffer> src, size_t off, size_t row, size_t image, MTLSize size,
                        id<MTLTexture> dst, NSUInteger slice, NSUInteger level) {
    if (g_nup_blits == g_up_blitcap) {
        g_up_blitcap = g_up_blitcap ? g_up_blitcap * 2 : 256;
        g_up_blits = realloc(g_up_blits, g_up_blitcap * sizeof *g_up_blits);
    }
    g_up_blits[g_nup_blits++] = (up_blit){src, off, row, image, size, dst, slice, level};
}

/* TOTK: small mirrored textures (<= PKG_HASH_MAX bytes) are checked by a content hash once per submission instead of by
   write-protecting their pages. The game rewrites about 30 of them on the CPU every frame (4x4 RGBA8 and the like): each
   rewrite was a page fault on the game thread and a step of the global guest-write generation, after which every
   CPU-pool texture bound by a following draw looked its pages up again. TOTK_PKG_HASH=0 protects them like the others. */
#define PKG_HASH_MAX (4u << 10)
static int pkg_hashed(const tex_t *t) {
    static int on = -1; if (on < 0) { const char *e = getenv("TOTK_PKG_HASH"); on = !e || atoi(e); }
    return on && t->L.size && t->L.size <= PKG_HASH_MAX;
}
static uint64_t pkg_hash(const void *p, uint64_t n) {
    const uint8_t *b = p; uint64_t a[4] = {0x9E3779B97F4A7C15ull ^ n, 0xC2B2AE3D27D4EB4Full, 0x165667B19E3779F9ull, 0x27D4EB2F165667C5ull}, i = 0;
    for (; i + 32 <= n; i += 32) for (int k = 0; k < 4; k++) { uint64_t w; memcpy(&w, b + i + 8 * k, 8); a[k] = (a[k] ^ w) * 0xff51afd7ed558ccdull; a[k] ^= a[k] >> 29; }   // four independent lanes
    uint64_t h = a[0] ^ (a[1] * 3) ^ (a[2] * 5) ^ (a[3] * 7);
    for (; i < n; i++) h = (h ^ b[i]) * 0x100000001b3ull;
    h ^= h >> 33; h *= 0xc4ceb9fe1a85ec53ull; return h ^ (h >> 33);
}
/* TOTK (#90): a texture whose first or last host page (16 KB) also holds other data is marked written whenever that data
   is. The glyph cache's last page holds the glyph records the font code flags as used on every frame, so the whole 8 MB
   texture was uploaded again on every frame. When only those shared pages were written since the stamp, the texture's
   bytes in them are compared with the ones the upload started from: equal means clean, and the two pages are protected
   again under a new stamp. The bytes are kept only for a texture that showed this once (edge_want): no memory for others. */
static void pkg_edges(const tex_t *t, uintptr_t *h, uintptr_t *tl) {   // own pages [h, tl); the shared parts are [mem, h) and [tl, end)
    static uintptr_t pg; if (!pg) pg = (uintptr_t)getpagesize();
    uintptr_t a = (uintptr_t)t->mem, e = a + t->L.size; *h = (a + pg - 1) & ~(pg - 1); *tl = e & ~(pg - 1);
}
static void pkg_edge_snap(const tex_t *t, NvPkg *pk) {   // in pkg_upload_, after the stamp and before the pages are protected and copied
    uintptr_t h, tl, a = (uintptr_t)t->mem, e = a + t->L.size; pkg_edges(t, &h, &tl);
    free(pk->edge); pk->edge = NULL; pk->eh = pk->et = 0;
    if (tl <= h || (h == a && tl == e) || !(pk->edge = malloc((h - a) + (e - tl)))) return;
    pk->eh = (uint32_t)(h - a); pk->et = (uint32_t)(e - tl);
    memcpy(pk->edge, t->mem, pk->eh); memcpy(pk->edge + pk->eh, (const void *)tl, pk->et);
}
static uint64_t g_pkg_edge_same;
static int pkg_edge_clean(const tex_t *t, NvPkg *pk) {   // 1: only the shared pages were written, and the texture's bytes there are unchanged
    uintptr_t h, tl, a = (uintptr_t)t->mem, e = a + t->L.size; pkg_edges(t, &h, &tl);
    if (tl <= h || (h == a && tl == e) || nvn_dirty_since((const void *)h, tl - h, pk->stamp)) return 0;   // its own pages were written
    if (!pk->edge || pk->eh != h - a || pk->et != e - tl) { pk->edge_want = 1; return 0; }   // upload again, keeping the shared bytes this time
    uint64_t st = nvn_dirty_now();   // before protecting, as in pkg_upload_
    if (h > a) nvn_dirty_protect(t->mem, h - a);
    if (e > tl) nvn_dirty_protect((const void *)tl, e - tl);
    /* compared after protecting: a write before it is in the bytes compared, a write after it faults and is newer than st */
    if (memcmp(t->mem, pk->edge, pk->eh) || memcmp((const void *)tl, pk->edge + pk->eh, pk->et) ||
        nvn_dirty_since((const void *)h, tl - h, pk->stamp)) return 0;   // changed, or its own pages written meanwhile
    pk->stamp = st;
    if (!g_pkg_edge_same++ || g_pkg_edge_same % 5000 == 0)
        MLOG("贴图首尾共享页被写、贴图内容没变，不重传：累计 %llu 次（例 ser=%llu %ux%u）", (unsigned long long)g_pkg_edge_same, (unsigned long long)t->serial, t->d.width, t->d.height);
    return 1;
}
static id<MTLTexture> pkg_upload_(const tex_t *t, uint64_t *stamp, reup_key *key, NvPkg *pk);
static id<MTLTexture> pkg_upload(const tex_t *t, uint64_t *stamp, reup_key *key, NvPkg *pk) {
    struct timespec a, b; clock_gettime(CLOCK_MONOTONIC, &a);
    id<MTLTexture> r = pkg_upload_(t, stamp, key, pk);
    clock_gettime(CLOCK_MONOTONIC, &b); uint64_t d_ = (uint64_t)((b.tv_sec - a.tv_sec) * 1000000000ll + b.tv_nsec - a.tv_nsec);
    atomic_fetch_add(&g_upload_ns, d_); g_up_total_ns += d_;
    return r;
}
uint64_t mtl_upload_ns_take(void) { return atomic_exchange(&g_upload_ns, 0); }
uint64_t mtl_upload_gpu_ns_take(void) { return atomic_exchange(&g_upload_gpu_ns, 0); }
void mtl_create_stats(uint64_t *lib, uint64_t *pso) { *lib = g_bp_lib_n; *pso = g_bp_pso_n; }
void mtl_create_ns(uint64_t *lib_ns, uint64_t *pso_ns) { *lib_ns = g_bp_lib_ns; *pso_ns = g_bp_pso_ns; }   // 同步现建着色器库 / 管线的累计耗时（长帧日志按帧取差） | Cumulative time spent synchronously creating shader libraries / pipelines on the spot (the long-frame log takes the per-frame difference)
uint64_t mtl_upload_bytes(void) { return g_bp_up_bytes; }   // 贴图上传累计字节 | Cumulative texture upload bytes
/* TOTK: textures replaced by a re-upload are kept (still resident) once the submissions that read them completed, and the
   next upload with the same description writes into one instead of creating a texture: about 30 small textures the game
   rewrites on the CPU every frame (4x4 RGBA8, 3x3x8 R8 ...) were each a new MTLTexture plus residency-set churn per frame.
   An upload writes every level and layer, so nothing of the earlier content survives. Unused entries are retired after
   REUP_IDLE submissions; TOTK_REUP_RECYCLE=0 turns it off. */
#define REUP_MAX 256
#define REUP_MAX_BYTES (1u << 20)
#define REUP_IDLE 600
typedef struct { void *tex; uint64_t fence; reup_key k; } reup_ent;   // tex: CFBridgingRetain'd MTLTexture
static reup_ent g_reup[REUP_MAX]; static int g_nreup; static os_unfair_lock g_reup_lk = OS_UNFAIR_LOCK_INIT;
static uint64_t g_reup_reused, g_reup_kept;
static int reup_on(void) { static int on = -1; if (on < 0) { const char *e = getenv("TOTK_REUP_RECYCLE"); on = !e || atoi(e); } return on; }
static reup_key reup_key_of(MTLTextureDescriptor *d) {
    reup_key k; memset(&k, 0, sizeof k); MTLTextureSwizzleChannels z = d.swizzle;
    k.pf = d.pixelFormat; k.type = d.textureType; k.w = d.width; k.h = d.height; k.z = d.depth; k.levels = d.mipmapLevelCount; k.layers = d.arrayLength;
    k.samples = d.sampleCount; k.usage = d.usage; k.storage = d.storageMode; k.swz[0] = (uint8_t)z.red; k.swz[1] = (uint8_t)z.green; k.swz[2] = (uint8_t)z.blue; k.swz[3] = (uint8_t)z.alpha;
    return k;
}
/* The texture a re-upload replaced (k: the description it was created from): keep it for reuse, or retire it as before. */
