void mtl_prog_release(prog_t *p) { if (p->serial) serial_del(p->serial); }

// ---------- 描述符池：贴图号 / 采样器号 → 对象 ----------
// 登记时快照整个贴图对象（NVN 语义：描述符已写进池）；view：该号对应的 MTLTexture（视图或基贴图，CFBridgingRetain 持有）及取得时的序号表 / 客体写代号
// ---------- Descriptor pool: texture ID / sampler ID → object ----------
// At registration the whole texture object is snapshotted (NVN semantics: the descriptor has been written into the pool); view: the MTLTexture for that ID (a view or the base texture, held via CFBridgingRetain) and the serial-table / guest-write generations at the time it was obtained
// view_pkg: the texture mirrors CPU pool memory (only then do guest writes matter); dead_pending: the serial was finalised
// and no live texture was found at its storage yet, so every serial-table step re-checks it (see tex_by_id).
typedef struct { tex_t t; int ok; view_t v; int has_v; void *view; uint64_t view_id, view_rid, view_ser, view_dirty;
    uint64_t indexed_serial, used; int view_prev, view_next; uint8_t view_pkg, dead_pending; } treg_t;   // used (TOTK): last submission that resolved this id
static treg_t *g_treg; static int g_ntreg;
/* Only slots with a cached Metal view need work when an NVN texture is finalized. A linear
   scan of the entire descriptor pool on every finalize dominated the game's render thread. */
static nvn_hmap g_view_heads = {.klen = 8};   // serial -> slot id + 1; protected by g_rmu
static void treg_unlink_locked(int tid) {
    treg_t *r = &g_treg[tid]; uint64_t serial = r->indexed_serial;
    if (!serial) return;
    int next = r->view_next, prev = r->view_prev;
    if (prev) g_treg[prev - 1].view_next = next;
    else if (next) nvn_hm_put(&g_view_heads, &serial, (void *)(uintptr_t)next);
    else nvn_hm_del(&g_view_heads, &serial);
    if (next) g_treg[next - 1].view_prev = prev;
    r->indexed_serial = 0; r->view_prev = r->view_next = 0;
}
static void treg_link_locked(int tid) {
    treg_t *r = &g_treg[tid]; uint64_t serial = r->t.serial;
    if (!r->view || !serial) return;
    int head = (int)(uintptr_t)nvn_hm_get(&g_view_heads, &serial);
    r->indexed_serial = serial; r->view_prev = 0; r->view_next = head;
    if (head) g_treg[head - 1].view_prev = tid + 1;
    nvn_hm_put(&g_view_heads, &serial, (void *)(uintptr_t)(tid + 1));
}
static void treg_clear_view_locked(int tid) {
    treg_t *r = &g_treg[tid];
    treg_unlink_locked(tid);
    if (r->view) { defer_obj_unref((__bridge id)r->view); CFRelease(r->view); r->view = NULL; }
    r->view_id = r->view_rid = r->view_ser = r->view_dirty = 0; r->view_pkg = r->dead_pending = 0;
}
// 贴图号 → 序号的无锁副本（回放热路径只要序号：写回前瞻索引、纯清除前提的绑定集合）：贴图号 20 位，固定 1M 项（BSS，只占碰过的页），
// 登记时 release 写、读端 relaxed 原子读，不进 g_rmu（原 h_ser 每次查表加解锁，营地每帧数千次）
// Lock-free copy of texture ID → serial (the replay hot path only needs the serial: store lookahead index, binding set of the clear-only hoist): texture IDs are 20 bits, fixed 1M entries (BSS, only touched pages are used),
// release write at registration, relaxed atomic read on the reader side, without entering g_rmu (the former h_ser locked and unlocked on every lookup, thousands of times per frame in the camp)
static _Atomic uint64_t g_tser[1 << 20];
static samp_par *g_sreg; static uint8_t *g_sreg_ok; static void **g_sview; static uint64_t *g_srid; static int g_nsreg;   // g_sview：采样器号 → MTLSamplerState（持有） | g_sview: sampler ID → MTLSamplerState (retained)
void mtl_reg_tex(int tid, const tex_t *t, const view_t *v) {
    int id_ = tid; if (id_ < 0) return;
    registry_lock();
    if (id_ >= g_ntreg) { int n = id_ + 1024; g_treg = realloc(g_treg, n * sizeof *g_treg); memset(g_treg + g_ntreg, 0, (n - g_ntreg) * sizeof *g_treg); g_ntreg = n; }
    /* TOTK: the game writes the same descriptor into a slot again and again; an identical registration changes nothing, so
       the slot keeps its view and no argument buffer has to be encoded again (g_reg_gen). */
    { treg_t *r = &g_treg[id_];
      if (t && r->ok && r->has_v == (v != NULL) && !memcmp(&r->t, t, sizeof *t) && (!v || !memcmp(&r->v, v, sizeof *v))) { g_treg_same++; registry_unlock(); return; } }
    g_treg_changed++;
    g_reg_gen++;
    if (g_treg[id_].view) treg_clear_view_locked(id_);
    uint64_t was = g_treg[id_].ok ? g_treg[id_].t.serial : 0;   // the serial this slot named before: one reference less (serial_forget_locked_rmu)
    if (t && t->serial != was) treg_ref_locked(t->serial, 1);
    if (was && (!t || t->serial != was)) { treg_ref_locked(was, -1); serial_forget_locked_rmu(was); }
    g_treg[id_].ok = t != NULL; if (t) g_treg[id_].t = *t; g_treg[id_].has_v = v != NULL;
    if (v) g_treg[id_].v = *v; else memset(&g_treg[id_].v, 0, sizeof g_treg[id_].v);   // TOTK: a registration without a view must not keep the slot's previous view (depth texture once got a stale BC3 9-level view)
    if (id_ < (1 << 20)) atomic_store_explicit(&g_tser[id_], t ? t->serial : 0, memory_order_release);
    registry_unlock();
}
/* TOTK: Metal has three border colours (transparent black, opaque black, opaque white). A sampler that clamps to any
   other colour is emulated in the shader (fs_fn_border). The game's grass interaction map (two 256x256 targets updated
   from each other every frame, scrolled with the player) clamps to (0.5, 0.5, 0.5, 0.5), its "untouched" value: with
   transparent black every area entering the map read as grass bent all the way, so grass lay flat away from the player,
   stood up where Link walked and showed no cut (#49). */
static int samp_border_custom(const samp_par *p) {
    if (!(p->ws == 4 || p->ws == 5 || p->wt == 4 || p->wt == 5 || p->wr == 4 || p->wr == 5)) return 0;
    const float *b = p->border;
    int grey = b[0] == b[1] && b[1] == b[2];
    if (grey && b[0] == 0 && (b[3] == 0 || b[3] == 1)) return 0;   // transparent / opaque black
    if (grey && b[0] == 1 && b[3] == 1) return 0;                   // opaque white
    return 1;
}
static _Atomic int g_border_custom_any;   // set once such a sampler is registered: border_key runs only then
void mtl_reg_samp(int sid, const samp_par *sp) {
    int id_ = sid; if (id_ < 0) return;
    registry_lock();
    if (id_ >= g_nsreg) { int n = id_ + 256; g_sreg = realloc(g_sreg, n * sizeof *g_sreg); g_sreg_ok = realloc(g_sreg_ok, n); g_sview = realloc(g_sview, n * sizeof *g_sview); g_srid = realloc(g_srid, n * sizeof *g_srid);
        memset(g_sreg_ok + g_nsreg, 0, n - g_nsreg); memset(g_sview + g_nsreg, 0, (n - g_nsreg) * sizeof *g_sview); memset(g_srid + g_nsreg, 0, (n - g_nsreg) * sizeof *g_srid); g_nsreg = n; }
