/* Texture-pool slots whose cached view still holds a texture of a finalized serial (diagnostic for the readout line). */
static void treg_stale_report(void) {
    unsigned long stale = 0, views = 0; unsigned long long stale_mb = 0;
    registry_lock();
    for (int i = 0; i < g_ntreg; i++) if (g_treg[i].view) { views++; if (serial_is_dead(g_treg[i].t.serial)) { stale++; id<MTLTexture> v = (__bridge id<MTLTexture>)g_treg[i].view; id<MTLTexture> b = v.parentTexture ?: v; stale_mb += b.allocatedSize >> 20; } }
