/* TOTK (iPhone): Metal copies of CPU-pool textures are kept as long as the game keeps the NVNtexture, i.e. for every
   asset loaded around the player. Turning the camera resolves all of them once, and on a 4 GB iPhone the copies alone
   (530 -> 730 MB) pushed the app past its memory limit (killed with SIGKILL after a few camera turns). The pool bytes
   are still in guest memory, so a copy that no submission resolved for a while can be dropped and uploaded again when it
   is used next. Only mirrored copies the GPU never rendered into (pk->owned: the pool bytes are stale) and that are
   larger than the content-hashed small textures are dropped, least recently used first.
   When: iOS, the app's remaining allowance (os_proc_available_memory) below TOTK_TEX_EVICT_LOW_MB (600): drop until
   TOTK_TEX_EVICT_HIGH_MB (850) would be available; copies idle for EVICT_IDLE submissions, or EVICT_IDLE_CRIT below
   TOTK_TEX_EVICT_CRIT_MB (300). Any platform: TOTK_TEX_EVICT_MB=<n> keeps the copies under n MB (tests on the Mac).
   TOTK_TEX_EVICT=0 turns it off. Runs between submissions on the replay thread, every 4 submissions. */
#define EVICT_IDLE 90
#define EVICT_IDLE_CRIT 8
typedef struct { void *pk; uint64_t used, bytes, serial; } evict_cand;
static uint64_t g_pkg_evicted, g_pkg_evicted_mb_x, g_evict_sweeps;
static int evict_cmp(const void *a, const void *b) { uint64_t x = ((const evict_cand *)a)->used, y = ((const evict_cand *)b)->used; return x < y ? -1 : x > y; }
static uint64_t env_mb(const char *name, uint64_t dflt) { const char *e = getenv(name); return (e && *e ? strtoull(e, NULL, 10) : dflt) << 20; }
static uint64_t evict_available(void) {
#if TARGET_OS_IPHONE
    return os_proc_available_memory();
#else
    return 0;
#endif
}
/* TOTK (2026-10-17, long-session memory): how many copies of CPU-pool textures are alive, and how many of them belong to a
   memory pool that is already gone (the game deleted the pool but never finalized the texture object, so mtl_tex_release
   never ran for it). Every 6,000 submits on the replay thread; the ranges are copied under g_smu, the pools looked up
   under g_mu afterwards (the two locks are never held together here). */
static void pkg_orphan_report(void) {
    if (g_sub_serial % 6000) return;
    size_t n = 0, cap = 0; struct { uintptr_t lo, hi; uint64_t bytes; } *v = NULL;
    pthread_mutex_lock(&g_smu);
    for (uint32_t i = 0; i < g_by_serial.cap; i++) {
        __unsafe_unretained id o = (__bridge id)g_by_serial.vals[i];
        if (!o || ![o isKindOfClass:[NvPkg class]]) continue;
        NvPkg *pk = (NvPkg *)o; if (!pk->tex || pk->hi <= pk->lo) continue;
        if (n == cap) { cap = cap ? cap * 2 : 4096; v = realloc(v, cap * sizeof *v); if (!v) MDIE("orphan report"); }
        v[n].lo = pk->lo; v[n].hi = pk->hi; v[n].bytes = pk->tex.allocatedSize; n++;
    }
    pthread_mutex_unlock(&g_smu);
    uint64_t total = 0, orphan_n = 0, orphan_b = 0;
    pthread_mutex_lock(&g_mu);
    for (size_t i = 0; i < n; i++) { total += v[i].bytes; if (!pidx_find_mut(&g_pools, v[i].lo, v[i].hi - v[i].lo)) { orphan_n++; orphan_b += v[i].bytes; } }
    pthread_mutex_unlock(&g_mu);
    free(v);
