static void life_use(int tid, const tex_t *t, const char *how) {
    static uint64_t frame = ~0ull; static int seen[64]; static int nseen;
    uint64_t f = atomic_load(&g_cur_frame); if (f != frame) { frame = f; nseen = 0; }
    for (int i = 0; i < nseen; i++) if (seen[i] == tid) return;
    if (nseen < 64) seen[nseen++] = tid;
    totk_life_log("use fc=%llu id=%d ser=%llu mem=%p %s%s", (unsigned long long)f, tid, (unsigned long long)t->serial, (void *)t->mem, how, serial_is_dead(t->serial) ? " (dead)" : "");
