        if (!f) MDIE("vertex shader %s (variant %s): %s", vs->key, key.UTF8String, e.localizedDescription.UTF8String);
        if (!vs->vpatch) vs->vpatch = [NSMutableDictionary dictionary];
        vs->vpatch[key] = f;
        static int once, lonce;
        if (miss.count && once++ < 64) MLOG("[totk] fragment shader %s reads varyings the vertex shader %s leaves unwritten (locn %s): added as zero outputs", fs ? fs->key : "-", vs->key, [miss componentsJoinedByString:@","].UTF8String);
        if (layered && !lonce++) MLOG("[totk] layered pass: vertex shader %s writes the render target array index", vs->key);
    }
    os_unfair_lock_unlock(&lk);
    return f;
}
// MSL of a depth-exporting fragment function with the depth output kept as a local (see fs_fn_without_depth).
static NSString *fs_src_without_depth(NvShader *fs) {
    NSRegularExpression *decl = [NSRegularExpression regularExpressionWithPattern:@"float\\s+(\\w+)\\s*\\[\\[depth\\([^)]*\\)\\]\\]\\s*;" options:0 error:nil];
    NSTextCheckingResult *match = [decl firstMatchInString:sh_src(fs) options:0 range:NSMakeRange(0, sh_src(fs).length)];
    if (!match) MDIE("fragment shader %s: missing depth output declaration", fs->key);
    NSString *field = [sh_src(fs) substringWithRange:[match rangeAtIndex:1]];
    NSString *local = [@"totk_ignored_" stringByAppendingString:field];
    NSString *src = [sh_src(fs) stringByReplacingCharactersInRange:match.range withString:@""];
    src = [src stringByReplacingOccurrencesOfString:[@"out." stringByAppendingString:field] withString:local];
    NSString *init = @"main0_out out = {};";
    if ([src rangeOfString:init].location == NSNotFound) MDIE("fragment shader %s: missing output initialization", fs->key);
    return [src stringByReplacingOccurrencesOfString:init withString:[NSString stringWithFormat:@"%@ float %@ = 0.0;", init, local]];
}
/* A framebuffer without a depth attachment discards fragment depth on NVN. Metal instead rejects a pipeline whose
   fragment entry exports depth without a matching attachment. Keep its calculation local in that case; color
   outputs and side effects are unchanged. The pipeline key already includes the depth attachment format. */
static id<MTLFunction> fs_fn_without_depth(NvShader *fs) {
    if (!fs || !fs->writes_depth) return fs ? fs->fn : nil;
    static os_unfair_lock lock = OS_UNFAIR_LOCK_INIT; os_unfair_lock_lock(&lock);
    if (!fs->no_depth_fn) {
        NSString *src = fs_src_without_depth(fs);
        NSError *err = nil; id<MTLLibrary> lib = totk_msl_library(src, &err);
        fs->no_depth_fn = lib ? [lib newFunctionWithName:fs->fn.name] : nil;
        if (!fs->no_depth_fn) MDIE("fragment shader %s without depth export: %s", fs->key, err.localizedDescription.UTF8String);
        MLOG("[totk] fragment depth export omitted for a color-only pass: %s", fs->key);
    }
    id<MTLFunction> fn = fs->no_depth_fn; os_unfair_lock_unlock(&lock); return fn;
}
/* TOTK_MFX: the fragment function with its colour 0 output copied to attachment 7, the UI layer (role 3 makes the copy
   opaque). Returns nil when the source cannot take the copy (no float colour 0, attachment 7 already written); the
   caller then masks the attachment. */
static id<MTLFunction> fs_fn_mfx(NvShader *fs, int role, int nodepth) {
    if (!fs || !sh_has_src(fs) || role < MFX_ROLE_UI || role > MFX_ROLE_UI_OPAQUE) return nil;
    int idx = role * 2 + (nodepth && fs->writes_depth);
    static os_unfair_lock lock = OS_UNFAIR_LOCK_INIT; os_unfair_lock_lock(&lock);
    if (!fs->mfx_tried[idx]) {
        fs->mfx_tried[idx] = 1;
        NSString *src = nodepth && fs->writes_depth ? fs_src_without_depth(fs) : sh_src(fs);
        NSRegularExpression *c0 = [NSRegularExpression regularExpressionWithPattern:@"\\n\\s*(\\w+)\\s+(\\w+)\\s*\\[\\[color\\(0\\)\\]\\]\\s*;" options:0 error:nil];
        NSTextCheckingResult *m = [c0 firstMatchInString:src options:0 range:NSMakeRange(0, src.length)];
        NSString *head = @"struct main0_out\n{\n";
        NSString *type = m ? [src substringWithRange:[m rangeAtIndex:1]] : nil, *name = m ? [src substringWithRange:[m rangeAtIndex:2]] : nil, *e = nil;
        if ([type isEqualToString:@"float4"] || [type isEqualToString:@"half4"]) e = [NSString stringWithFormat:@"float4(out.%@)", name];
        else if ([type isEqualToString:@"float3"] || [type isEqualToString:@"half3"]) e = [NSString stringWithFormat:@"float4(float3(out.%@), 1.0)", name];
        else if ([type isEqualToString:@"float2"] || [type isEqualToString:@"half2"]) e = [NSString stringWithFormat:@"float4(float2(out.%@), 0.0, 1.0)", name];
        else if ([type isEqualToString:@"float"] || [type isEqualToString:@"half"]) e = [NSString stringWithFormat:@"float4(float(out.%@), 0.0, 0.0, 1.0)", name];
        if (e && role == MFX_ROLE_UI_OPAQUE) e = [NSString stringWithFormat:@"float4((%@).rgb, 1.0)", e];
        if (e && [src rangeOfString:head].location != NSNotFound && [src rangeOfString:@"[[color(7)]]"].location == NSNotFound) {
            src = [src stringByReplacingCharactersInRange:[src rangeOfString:head] withString:[head stringByAppendingString:@"    float4 totk_mfx_copy [[color(7)]];\n"]];
            src = [src stringByReplacingOccurrencesOfString:@"return out;" withString:[NSString stringWithFormat:@"{ out.totk_mfx_copy = %@; return out; }", e]];
            NSError *err = nil; id<MTLLibrary> lib = totk_msl_library(src, &err);
            fs->mfx_fn[idx] = lib ? [lib newFunctionWithName:fs->fn.name] : nil;
            if (!fs->mfx_fn[idx]) MDIE("fragment shader %s, MetalFX copy (role %d): %s", fs->key, role, err.localizedDescription.UTF8String);
        } else MLOG("【红】[mfx] fragment shader %s: colour 0 (%s) cannot be copied to the UI layer; this draw is left out of it", fs->key, type ? type.UTF8String : "none");
    }
    id<MTLFunction> fn = fs->mfx_fn[idx]; os_unfair_lock_unlock(&lock); return fn;
}
/* Diagnostic TOTK_NAN_TRACE=<fragment key prefix> (log TOTK_NAN_TRACE_LOG, default analysis/nan-trace.tsv): those fragment
   shaders are rebuilt so that every float temporary is checked right after it is computed, and the number of the first
   temporary that is Inf or NaN is remembered. When a colour output ends up non-finite, the pixel counts that number in a
   per-frame histogram (buffer 29, 64 frame slots), so one run names the operation where the bad values start. */
#define NT_SLOTS 64
#define NT_SLOT_WORDS 4096   /* [0] bad pixels, [1..3] first pixel x, y, temporary; [16..] histogram by temporary number */
static const char *nan_trace_prefix(void) { static const char *p; static int init; if (!init) { init = 1; p = getenv("TOTK_NAN_TRACE"); if (p && !*p) p = NULL; } return p; }
static int nan_trace_match(const NvShader *fs) { const char *p = nan_trace_prefix(); return p && fs && fs->stage == 1 && sh_has_src(fs) && !strncmp(fs->key, p, strlen(p)); }
static id<MTLFunction> nan_trace_fn(NvShader *fs) {
    static NSMutableDictionary<NSValue *, id<MTLFunction>> *done; static os_unfair_lock lock = OS_UNFAIR_LOCK_INIT;
    NSValue *k = [NSValue valueWithPointer:(__bridge const void *)fs];
    os_unfair_lock_lock(&lock); if (!done) done = [NSMutableDictionary dictionary]; id<MTLFunction> have = done[k]; os_unfair_lock_unlock(&lock);
    if (have) return have;
    NSMutableArray<NSString *> *outs = [NSMutableArray array];
    NSRegularExpression *colre = [NSRegularExpression regularExpressionWithPattern:@"\\b(float[234]?|half[234]?) (\\w+) \\[\\[color\\(\\d+\\)\\]\\]" options:0 error:nil];
    for (NSTextCheckingResult *m in [colre matchesInString:sh_src(fs) options:0 range:NSMakeRange(0, sh_src(fs).length)]) [outs addObject:[sh_src(fs) substringWithRange:[m rangeAtIndex:2]]];
    NSRegularExpression *decl = [NSRegularExpression regularExpressionWithPattern:@"^(\\s+)(float|float2|float3|float4) _(\\d+) = .*;\\s*$" options:0 error:nil];
    NSRegularExpression *asgn = [NSRegularExpression regularExpressionWithPattern:@"^(\\s+)_(\\d+) = .*;\\s*$" options:0 error:nil];
    NSMutableDictionary<NSString *, NSString *> *types = [NSMutableDictionary dictionary];
    NSMutableArray<NSString *> *lines = [[sh_src(fs) componentsSeparatedByString:@"\n"] mutableCopy];
    NSMutableString *o = [NSMutableString string]; int in_entry = 0, depth = 0, instrumented = 0;
    for (NSString *line in lines) {
        NSString *l = line;
        if (!in_entry && [l containsString:@"fragment main0_out main0("]) {
            l = [l stringByReplacingOccurrencesOfString:@"[[buffer(0)]])" withString:@"[[buffer(0)]], device atomic_uint *totk_nt [[buffer(29)]], float4 totk_pos [[position]])"];
            if ([l isEqualToString:line]) MDIE("TOTK_NAN_TRACE: entry signature of %s not recognised", fs->key);
            in_entry = 1; [o appendFormat:@"%@\n", l]; continue;
        }
        if (in_entry == 1 && [[l stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceCharacterSet] isEqualToString:@"{"]) {
            in_entry = 2; depth = 1; [o appendFormat:@"%@\n    uint totk_first = 0u;\n", l]; continue;
        }
        if (in_entry == 2) {
            NSString *t = [l stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceCharacterSet];
            if ([t isEqualToString:@"return out;"] && depth == 1) {
                NSMutableString *bad = [NSMutableString string];
                for (NSString *v in outs) [bad appendFormat:@"%@!all(isfinite(float4(out.%@)))", bad.length ? @" || " : @"", v];
                if (!bad.length) [bad appendString:@"false"];
                [o appendFormat:@"    if (%@) {\n        uint totk_n = atomic_fetch_add_explicit(&totk_nt[0], 1u, memory_order_relaxed);\n"
                                "        if (totk_n == 0u) { atomic_store_explicit(&totk_nt[1], uint(totk_pos.x), memory_order_relaxed); atomic_store_explicit(&totk_nt[2], uint(totk_pos.y), memory_order_relaxed); atomic_store_explicit(&totk_nt[3], totk_first, memory_order_relaxed); }\n"
                                "        atomic_fetch_add_explicit(&totk_nt[16u + min(totk_first, %du)], 1u, memory_order_relaxed);\n    }\n", bad, NT_SLOT_WORDS - 17];
                [o appendFormat:@"%@\n", l]; in_entry = 3; continue;
            }
            for (NSUInteger c = 0; c < t.length; c++) { unichar ch = [t characterAtIndex:c]; if (ch == '{') depth++; else if (ch == '}') depth--; }
            NSTextCheckingResult *m = [decl firstMatchInString:l options:0 range:NSMakeRange(0, l.length)];
            NSString *var = nil, *type = nil, *ind = nil;
            if (m) { ind = [l substringWithRange:[m rangeAtIndex:1]]; type = [l substringWithRange:[m rangeAtIndex:2]]; var = [l substringWithRange:[m rangeAtIndex:3]]; types[var] = type; }
            else if ((m = [asgn firstMatchInString:l options:0 range:NSMakeRange(0, l.length)])) { ind = [l substringWithRange:[m rangeAtIndex:1]]; var = [l substringWithRange:[m rangeAtIndex:2]]; type = types[var]; }
            [o appendFormat:@"%@\n", l];
            if (var && type) {
                NSString *test = [type isEqualToString:@"float"] ? [NSString stringWithFormat:@"!isfinite(_%@)", var] : [NSString stringWithFormat:@"!all(isfinite(_%@))", var];
                [o appendFormat:@"%@if (totk_first == 0u && %@) totk_first = %@u;\n", ind, test, var]; instrumented++;
            }
            continue;
        }
        [o appendFormat:@"%@\n", l];
    }
    if (in_entry != 3) MDIE("TOTK_NAN_TRACE: could not instrument %s (state %d)", fs->key, in_entry);
    NSError *err = nil; id<MTLLibrary> lib = totk_msl_library(o, &err);
    id<MTLFunction> fn = lib ? [lib newFunctionWithName:fs->fn.name] : nil;
    if (!fn) MDIE("TOTK_NAN_TRACE: %s does not compile: %s", fs->key, err.localizedDescription.UTF8String);
    MLOG("TOTK_NAN_TRACE: %s rebuilt with %d checked temporaries, outputs %s", fs->key, instrumented, [outs componentsJoinedByString:@","].UTF8String);
    os_unfair_lock_lock(&lock); done[k] = fn; os_unfair_lock_unlock(&lock);
    return fn;
}
/* Per draw of a traced shader: the frame's slot in buffer 29. The histogram of frame f is read when frame f + 1 first
   uses the trace (its command buffer completes after f's), and is logged when the frame had bad pixels. */
static void nan_trace_bind(id<MTL4RenderCommandEncoder> en) {
    static id<MTLBuffer> buf; static long cur = -1; static FILE *f;
    long fr = (long)atomic_load(&g_cur_frame);
    if (!buf) {
        buf = [g_dev newBufferWithLength:NT_SLOTS * NT_SLOT_WORDS * 4 options:MTLResourceStorageModeShared]; res_add(buf); memset(buf.contents, 0, buf.length);
        const char *path = getenv("TOTK_NAN_TRACE_LOG"); if (!(f = fopen(path ? path : "analysis/nan-trace.tsv", "w"))) MDIE("TOTK_NAN_TRACE_LOG: cannot open");
        fprintf(f, "frame\tbad_pixels\tx\ty\tfirst_temp\thistogram (temporary:pixels, most first)\n"); fflush(f);
    }
    if (fr != cur) {
        long prev = cur; cur = fr;
        uint32_t *slot = (uint32_t *)buf.contents + (size_t)(fr % NT_SLOTS) * NT_SLOT_WORDS;
        memset(slot, 0, NT_SLOT_WORDS * 4);   /* last used NT_SLOTS frames ago, long finished */
        if (prev >= 0) {
            const uint32_t *ps = (const uint32_t *)buf.contents + (size_t)(prev % NT_SLOTS) * NT_SLOT_WORDS; FILE *lf = f;
            [g_commit_blocks addObject:^{
                if (!ps[0]) return;
                uint32_t idx[NT_SLOT_WORDS - 16]; int n = 0;
                for (int i = 0; i < NT_SLOT_WORDS - 16; i++) if (ps[16 + i]) idx[n++] = (uint32_t)i;
                for (int a = 0; a < n; a++) for (int b = a + 1; b < n; b++) if (ps[16 + idx[b]] > ps[16 + idx[a]]) { uint32_t t = idx[a]; idx[a] = idx[b]; idx[b] = t; }
                char h[512]; size_t o = 0; h[0] = 0;
                for (int a = 0; a < n && a < 12 && o < sizeof h - 32; a++) o += (size_t)snprintf(h + o, sizeof h - o, "%s_%u:%u", a ? " " : "", idx[a], ps[16 + idx[a]]);
                fprintf(lf, "%ld\t%u\t%u\t%u\t_%u\t%s\n", prev, ps[0], ps[1], ps[2], ps[3], h); fflush(lf); }];
        }
    }
    enc_r_args(en, MTLRenderStageFragment, buf.gpuAddress + (uint64_t)(fr % NT_SLOTS) * NT_SLOT_WORDS * 4, 29);
}
static MTLRenderPipelineDescriptor *pso_desc(const pso_key *k, NvShader *vs, NvShader *fs, id<MTLFunction> fsfn, int merged) {
    MTLRenderPipelineDescriptor *d = [MTLRenderPipelineDescriptor new];
    d.vertexFunction = vs_fn_for(vs, fs, (k->a2c & PSO_LAYERED) != 0, (k->a2c & PSO_VBORDER) != 0); d.fragmentFunction = fsfn ? fsfn : fs ? (k->dfmt ? fs->fn : fs_fn_without_depth(fs)) : nil;
    if (!fsfn && nan_trace_match(fs) && !fs->writes_depth) d.fragmentFunction = nan_trace_fn(fs);   // diagnostic TOTK_NAN_TRACE
    // 诊断 DM_NVN_HILITE=片元着色器键,…：这些绘制改用纯色片元（第 1–6 个键依次 品红 / 绿 / 青 / 黄 / 蓝 / 白），看几何落在哪里
    // Diagnostic DM_NVN_HILITE=fragment shader key,...: these draws use a solid-color fragment instead (keys 1–6 in order magenta / green / cyan / yellow / blue / white), to see where the geometry lands
    if (fs) { static char keys[6][24]; static int nk = -1; static id<MTLLibrary> hl;
        if (nk < 0) { nk = 0; const char *e = getenv("DM_NVN_HILITE");
            for (const char *q = e; q && *q && nk < 6; q = strchr(q, ',') ? strchr(q, ',') + 1 : q + strlen(q)) { size_t n = strcspn(q, ","); if (n > 23) n = 23; memcpy(keys[nk], q, n); keys[nk++][n] = 0; } }
        for (int i = 0; i < nk; i++) if (!strncmp(fs->key, keys[i], strlen(keys[i]))) {
            if (!hl) { NSError *e = nil; hl = [g_dev newLibraryWithSource:@"#include <metal_stdlib>\nusing namespace metal;\nstruct O { float4 c0 [[color(0)]]; float4 c1 [[color(1)]]; float4 c2 [[color(2)]]; };\n"
                "fragment O hl0() { return {float4(1,0,1,1),float4(1,0,1,1),float4(1,0,1,1)}; } fragment O hl1() { return {float4(0,1,0,1),float4(0,1,0,1),float4(0,1,0,1)}; }\n"
                "fragment O hl2() { return {float4(0,1,1,1),float4(0,1,1,1),float4(0,1,1,1)}; } fragment O hl3() { return {float4(1,1,0,1),float4(1,1,0,1),float4(1,1,0,1)}; }\n"
                "fragment O hl4() { return {float4(0,0,1,1),float4(0,0,1,1),float4(0,0,1,1)}; } fragment O hl5() { return {float4(1,1,1,1),float4(1,1,1,1),float4(1,1,1,1)}; }\n" options:nil error:&e];
                if (!hl) MLOG("【红】HILITE 着色器编译失败 %s", e.localizedDescription.UTF8String); }
            if (hl) d.fragmentFunction = [hl newFunctionWithName:[NSString stringWithFormat:@"hl%d", i]];
            break; } }
    /* TOTK diagnostic TOTK_GPU_HILITE1=<fragment shader key prefix>,...: draws of these fragment shaders write a solid
       colour to colour attachment 0 only (green / cyan / yellow / blue), to tell whether their geometry rasterises at all. */
    int hilited = 0;
    if (fs) { static char keys[4][24]; static int nk = -1; static id<MTLLibrary> hl;
        if (nk < 0) { nk = 0; const char *e = getenv("TOTK_GPU_HILITE1");
            for (const char *q = e; q && *q && nk < 4; q = strchr(q, ',') ? strchr(q, ',') + 1 : q + strlen(q)) { size_t n = strcspn(q, ","); if (n > 23) n = 23; memcpy(keys[nk], q, n); keys[nk++][n] = 0; } }
        for (int i = 0; i < nk; i++) if (keys[i][0] && !strncmp(fs->key, keys[i], strlen(keys[i]))) {
            if (!hl) { NSError *e = nil; hl = [g_dev newLibraryWithSource:@"#include <metal_stdlib>\nusing namespace metal;\n"
                "fragment float4 h0() { return float4(0,1,0,1); } fragment float4 h1() { return float4(0,1,1,1); }\n"
                "fragment float4 h2() { return float4(1,1,0,1); } fragment float4 h3() { return float4(0,0,1,1); }\n" options:nil error:&e];
                if (!hl) MDIE("TOTK_GPU_HILITE1 shader library failed: %s", e.localizedDescription.UTF8String); }
            d.fragmentFunction = [hl newFunctionWithName:[NSString stringWithFormat:@"h%d", i]]; hilited = 1;
            /* TOTK_GPU_HILITE_VS=1: also replace the vertex shader with a 25x15 screen-tile grid driven only by vertex_id / instance_id
               (same quad order 0,2,1,1,2,3 as the game's tile-light draw), to tell draw-path problems from shader-input problems */
            if (getenv("TOTK_GPU_HILITE_VS")) { static id<MTLLibrary> vl; if (!vl) { NSError *e2 = nil; vl = [g_dev newLibraryWithSource:@"#include <metal_stdlib>\nusing namespace metal;\n"
                "struct V { float4 p [[position]]; };\nvertex V vtile(uint vid [[vertex_id]], uint iid [[instance_id]]) { float2 c = float2(vid & 1, vid >> 1); uint tx = iid % 25, ty = iid / 25;"
                " float2 q = (float2(tx, ty) + c) * float2(2.0 / 25.0, 2.0 / 15.0); V o; o.p = float4(q.x - 1.0, 1.0 - q.y, 0.5, 1.0); return o; }\n" options:nil error:&e2]; if (!vl) MDIE("HILITE_VS library: %s", e2.localizedDescription.UTF8String); }
                d.vertexFunction = [vl newFunctionWithName:@"vtile"]; d.vertexDescriptor = nil; static int said2; if (!said2++) MLOG("TOTK_GPU_HILITE_VS: vertex shader of %s replaced by the grid VS", keys[i]); }
            static int said[4]; if (!said[i]++) MLOG("TOTK_GPU_HILITE1: fragment shader %s drawn as solid colour %d", keys[i], i);
            break; } }
    d.rasterSampleCount = k->samples ? k->samples : 1;
    d.alphaToCoverageEnabled = (k->a2c & 1) != 0;
    if (k->a2c & PSO_LAYERED) d.inputPrimitiveTopology = MTLPrimitiveTopologyClassTriangle;   // TOTK: required with a layer output; layered passes take triangle draws only (lay_draw_ok)
    for (int i = 0; i < 8; i++) {
        if (!k->cfmt[i]) continue;
        MTLRenderPipelineColorAttachmentDescriptor *c = d.colorAttachments[i];
        c.pixelFormat = (MTLPixelFormat)k->cfmt[i];
        int l = merged ? k->lmap[i] : i;
        uint32_t m = l == 0xff ? 0 : (k->chmask >> (4 * l)) & 0xf;
        c.writeMask = (m & 1 ? MTLColorWriteMaskRed : 0) | (m & 2 ? MTLColorWriteMaskGreen : 0) | (m & 4 ? MTLColorWriteMaskBlue : 0) | (m & 8 ? MTLColorWriteMaskAlpha : 0);
        if (l != 0xff && k->blend_en >> l & 1 && !(hilited && getenv("TOTK_GPU_HILITE_NOBLEND"))) {   /* TOTK diagnostic: highlighted draws can be drawn without blending */
            c.blendingEnabled = YES;
            c.sourceRGBBlendFactor = bfac(k->blend[l].src_rgb); c.destinationRGBBlendFactor = bfac(k->blend[l].dst_rgb);
            c.sourceAlphaBlendFactor = bfac(k->blend[l].src_a); c.destinationAlphaBlendFactor = bfac(k->blend[l].dst_a);
            c.rgbBlendOperation = bop(k->blend[l].eq_rgb); c.alphaBlendOperation = bop(k->blend[l].eq_a);
        }
    }
    int mr = (int)(k->a2c >> 2) & 3;   // TOTK_MFX role (see g_mfx): attachment 7 takes the UI layer
    if (mr) {
        id<MTLFunction> mf = fs_fn_mfx(fs, mr, k->dfmt == 0);
        d.colorAttachments[7].blendingEnabled = NO; d.colorAttachments[7].writeMask = MTLColorWriteMaskNone;
        if (mf) {
            d.fragmentFunction = mf;
            {   // premultiplied UI layer: the game's colour blend; alpha accumulates coverage of "over" draws, additive ones leave it
                MTLRenderPipelineColorAttachmentDescriptor *c = d.colorAttachments[7]; uint32_t m0 = k->chmask & 0xf;
                c.writeMask = (m0 & 1 ? MTLColorWriteMaskRed : 0) | (m0 & 2 ? MTLColorWriteMaskGreen : 0) | (m0 & 4 ? MTLColorWriteMaskBlue : 0) | MTLColorWriteMaskAlpha;
                if (mr == MFX_ROLE_UI && (k->blend_en & 1)) {
                    const blend_st *b = &k->blend[0]; int over = b->dst_rgb == NVN_BLEND_FUNC_ONE_MINUS_SRC_ALPHA;
                    c.blendingEnabled = YES;
                    c.sourceRGBBlendFactor = bfac(b->src_rgb); c.destinationRGBBlendFactor = bfac(b->dst_rgb); c.rgbBlendOperation = bop(b->eq_rgb);
                    c.sourceAlphaBlendFactor = over ? MTLBlendFactorOne : MTLBlendFactorZero; c.destinationAlphaBlendFactor = over ? MTLBlendFactorOneMinusSourceAlpha : MTLBlendFactorOne;
                    c.alphaBlendOperation = MTLBlendOperationAdd;
                }
            }
        }
    }
    d.depthAttachmentPixelFormat = (MTLPixelFormat)k->dfmt; d.stencilAttachmentPixelFormat = (MTLPixelFormat)k->sfmt;
    MTLVertexDescriptor *vd = [MTLVertexDescriptor vertexDescriptor];
    const nvn_refl *rf = &vs->rf;
    for (int v = 0; v < rf->nv; v++) {
        int loc = rf->v[v].loc, a = rf->v[v].nvn;   // Metal 槽 loc ← NVN 属性 a | Metal slot loc ← NVN attribute a
        MTLVertexFormat vf = a < 16 ? vfmt(k->attr[a].fmt) : MTLVertexFormatInvalid;
        // a >= S.nattr 时 k.attr[a] 保持 memset 的 0，vfmt(0) 为 Invalid，走同一回退分支且 fmt 非 0 的 RED_ONCE 条件不成立。
        // When a >= S.nattr, k.attr[a] keeps the 0 from memset, vfmt(0) is Invalid, the same fallback branch is taken and the RED_ONCE condition of fmt being non-0 does not hold.
        if (a < 16 && k->attr[a].fmt && vf == MTLVertexFormatInvalid) RED_ONCE(15, "顶点属性格式 %#x 未映射", k->attr[a].fmt);
        if (vf == MTLVertexFormatInvalid) {
            int ct = rf->v[v].ct;
            vd.attributes[loc].format = ct == NVN_CT_UINT ? MTLVertexFormatUInt4 : ct == NVN_CT_INT ? MTLVertexFormatInt4 : MTLVertexFormatFloat4;
            vd.attributes[loc].offset = 0; vd.attributes[loc].bufferIndex = 30;
            vd.layouts[30].stride = 16; vd.layouts[30].stepFunction = MTLVertexStepFunctionConstant; vd.layouts[30].stepRate = 0;
            continue;
        }
        int st = k->attr[a].stream;
        vd.attributes[loc].format = vf; vd.attributes[loc].offset = k->attr[a].offset; vd.attributes[loc].bufferIndex = 16 + st;
        vd.layouts[16 + st].stride = k->stream[st].stride ? k->stream[st].stride : 4;
        vd.layouts[16 + st].stepFunction = k->stream[st].stride == 0 ? MTLVertexStepFunctionConstant : k->stream[st].divisor ? MTLVertexStepFunctionPerInstance : MTLVertexStepFunctionPerVertex;
        vd.layouts[16 + st].stepRate = k->stream[st].stride == 0 ? 0 : k->stream[st].divisor ? k->stream[st].divisor : 1;
    }
    d.vertexDescriptor = vd;
    return d;
}
// 管线键：当前状态 S + 通道格式（普通通道；合并通道另带 lmap / 特化函数，由 pso_get 填）
// Pipeline key: current state S + pass formats (normal pass; a merged pass additionally carries lmap / specialized function, filled in by pso_get)
static void pso_key_fill(pso_key *k, NvShader *vs, NvShader *fs, const uint32_t cfmt[8], uint32_t dfmt, uint32_t sfmt, uint32_t samples, int lmap) {
    memset(k, 0, sizeof *k);
    k->vs = (__bridge void *)vs; k->fs = (__bridge void *)fs;
    memcpy(k->cfmt, cfmt, sizeof k->cfmt); k->dfmt = dfmt; k->sfmt = sfmt; k->samples = samples;
    k->blend_en = S.color.blend_en; k->chmask = S.chmask.mask; k->a2c = S.ms.a2c;
    for (int i = 0; i < 8; i++) if (k->cfmt[i] || lmap) k->blend[i] = S.blend[i];
    const nvn_refl *rf = &vs->rf;
    for (int v = 0; v < rf->nv; v++) { int a = rf->v[v].nvn; if (a < 16 && a < S.nattr) { k->attr[a] = S.attr[a]; int st = S.attr[a].stream; if (st < 16) k->stream[st] = S.stream[st]; } }
}
// ---- 并行预编：首次遇到的管线原先在提交线程一条条同步编，一帧里连着缺 9 条 = 284 ms（真机重场面）。
// 现在：一次提交里第一次缺管线时，顺着余下的命令往前扫一遍（只重放状态，不画），把后面还会缺的普通通道管线一并丢给后台并行编；
// 提交线程走到那次绘制时只等「还没编完的剩余时间」。编出来的管线与同步编的完全相同（同一份描述符）。合并通道 / 特化片元的管线键依赖回放时的规划结果，不预测，照旧同步编。
// ---- Parallel precompile: pipelines met for the first time used to be compiled synchronously one by one on the submit thread; 9 misses in a row in one frame = 284 ms (heavy scene on a real device).
// Now: on the first pipeline miss in a submission, scan ahead once along the remaining commands (replaying state only, no drawing) and kick all the normal-pass pipelines that will also miss later to the background to compile in parallel;
// when the submit thread reaches that draw it only waits for 'the remaining time not yet compiled'. The compiled pipelines are identical to synchronously compiled ones (same descriptor). Pipeline keys of merged passes / specialized fragments depend on the planning result at replay time, are not predicted, and are compiled synchronously as before.
#define PSO_PEND_MAX 384
static struct { pso_key k; id<MTLRenderPipelineState> ps; uint64_t submit; int used, done; } g_pp[PSO_PEND_MAX];
static pthread_mutex_t g_pp_mu = PTHREAD_MUTEX_INITIALIZER; static pthread_cond_t g_pp_cv = PTHREAD_COND_INITIALIZER;
static uint64_t g_pp_submit_mark, g_pp_kicked, g_pp_taken;   // 本次提交是否已预测过（按提交序号）；累计丢出 / 领用条数 | Whether this submission has already been predicted (by submission serial); cumulative kicked / taken counts
// Statistics line (pso_predict_rest, every 100 scans): guesses refused because the table was full, stale guesses freed,
// time draws waited for a background compile, scans and which budget ended them.
static uint64_t g_pp_full, g_pp_reclaimed, g_pp_waits, g_pp_wait_ns, g_pp_scans, g_pp_scan_ns, g_pp_stop[3];
static void pso_predict_rest(void);
static int pso_pend_find(const pso_key *k) { for (int i = 0; i < PSO_PEND_MAX; i++) if (g_pp[i].used && !memcmp(&g_pp[i].k, k, sizeof *k)) return i; return -1; }
// Called only with g_pp_mu held. An in-flight worker still owns its slot:
// completion must be published before that slot can ever be reused. Negative 25 frees every slot.
static void pso_pend_reclaim(uint64_t submit) {
    for (int i = 0; i < PSO_PEND_MAX; i++) if (g_pp[i].used && ((g_pp[i].done && submit - g_pp[i].submit > 2) || pred_negative() == 25)) {
        g_pp[i].ps = nil; g_pp[i].used = 0; g_pp_reclaimed++;
    }
}
static void pso_pend_kick(const pso_key *k, NvShader *vs, NvShader *fs) {   // 提交线程调：没在缓存、没在表里才丢 | Called by the submit thread: kick only if it is neither in the cache nor in the table
    if (hm_get_id(&g_pso, k)) return;
    pthread_mutex_lock(&g_pp_mu);
    pso_pend_reclaim(g_sub_serial);
    int at = pso_pend_find(k), slot = -1;
    if (at < 0) for (int i = 0; i < PSO_PEND_MAX; i++) if (!g_pp[i].used) { slot = i; break; }
    if (at < 0 && slot >= 0) { g_pp[slot].k = *k; g_pp[slot].ps = nil; g_pp[slot].done = 0; g_pp[slot].used = 1; g_pp[slot].submit = g_sub_serial; }
    if (at < 0 && slot < 0) g_pp_full++;
    pthread_mutex_unlock(&g_pp_mu);
    if (at >= 0 || slot < 0) return;
    MTLRenderPipelineDescriptor *d = pso_desc(k, vs, fs, nil, 0); g_pp_kicked++;
    dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
        NSError *e = nil; id<MTLRenderPipelineState> ps = [g_dev newRenderPipelineStateWithDescriptor:d error:&e];
        pthread_mutex_lock(&g_pp_mu); g_pp[slot].ps = ps; g_pp[slot].done = 1; pthread_cond_broadcast(&g_pp_cv); pthread_mutex_unlock(&g_pp_mu);
    });
}
static id<MTLRenderPipelineState> pso_pend_take(const pso_key *k) {   // 提交线程调：表里有就等它编完并取走；没有返回 nil | Called by the submit thread: if it is in the table, wait for it to finish compiling and take it; otherwise return nil
    pthread_mutex_lock(&g_pp_mu);
    int at = pso_pend_find(k); id<MTLRenderPipelineState> ps = nil;
    if (at >= 0) { uint64_t t0 = bp_now(); int waited = !g_pp[at].done;
        while (!g_pp[at].done) pthread_cond_wait(&g_pp_cv, &g_pp_mu);
        if (waited) { g_pp_waits++; g_pp_wait_ns += bp_now() - t0; }
        ps = g_pp[at].ps; g_pp[at].ps = nil; g_pp[at].used = 0; }
    pthread_mutex_unlock(&g_pp_mu);
    return ps;
}
static __unsafe_unretained id<MTLRenderPipelineState> pso_get(NvProg *pr, MTLRenderPassDescriptor *unused) {
    (void)unused;
    __unsafe_unretained NvShader *vs = pr->sh[0], *fs = pr->sh[1];
    if (!vs) { RED_ONCE(13, "程序没有顶点着色器（或未映射）"); return nil; }
    pso_key k; pso_key_fill(&k, vs, fs, g_pass.cfmt, g_pass.dfmt, g_pass.sfmt, g_pass.samples, g_pso_lmap != NULL);
    if (g_pass.layered) k.a2c |= PSO_LAYERED;   // TOTK: layered pass (see g_lay)
    if (g_mfx.role) k.a2c |= (uint32_t)g_mfx.role << 2;   // TOTK_MFX: scene / UI copy variant (see pso_desc)
    if (g_pso_lmap) { memcpy(k.lmap, g_pso_lmap, 8); k.fsfn = (__bridge void *)g_pso_fsfn; }
    __unsafe_unretained id<MTLFunction> bfn = !g_pso_lmap && !g_mfx.role ? fs_fn_border(fs, k.dfmt == 0) : nil;   // TOTK: sampler border colour emulation
    if (bfn) k.fsfn = (__bridge void *)bfn;
    { float bc[8][4]; int ba[8], bn; if (border_key(vs, 0, bc, ba, &bn)) k.a2c |= PSO_VBORDER; }
    __unsafe_unretained id<MTLRenderPipelineState> cached = (__bridge id<MTLRenderPipelineState>)hm_get_ptr(&g_pso, &k);
    if (cached) return cached;
    id<MTLRenderPipelineState> ps;
    NSError *e = nil; uint64_t bt = bp_now();
    ps = g_pso_lmap ? nil : pso_pend_take(&k);
    if (ps) g_pp_taken++;
    else {
        if (g_pp_submit_mark != g_sub_serial) { g_pp_submit_mark = g_sub_serial; pso_predict_rest(); }   // 本次提交第一次缺：先把后面的丢出去并行编，再同步编眼前这条 | First miss in this submission: first kick the later ones out to compile in parallel, then synchronously compile the one at hand
        MTLRenderPipelineDescriptor *d = pso_desc(&k, vs, fs, bfn ? bfn : g_pso_fsfn, g_pso_lmap != NULL);
        ps = [g_dev newRenderPipelineStateWithDescriptor:d error:&e];
    }
    g_bp_pso_n++; g_bp_pso_ns += bp_now() - bt;
    if (!ps) { static int said; if (said++ < 12) MLOG("【红】建渲染管线失败：%s（vs %s ps %s dfmt %d sfmt %d cfmt0 %d samples %d）", e.localizedDescription.UTF8String, vs->key, fs ? fs->key : "-", (int)k.dfmt, (int)k.sfmt, (int)k.cfmt[0], (int)k.samples); else if (said == 12) MLOG("【红】建渲染管线失败：后续不再逐条打印"); return nil; }
    pso_key rk = k; rk.a2c &= ~PSO_VBORDER; if (bfn) rk.fsfn = NULL;   // the warm-up list records the plain pipeline: a border variant is built from the draw's samplers
    pso_skey sk; char shex[sizeof sk * 2 + 1]; pso_skey_from(&rk, vs, fs, g_pso_lmap != NULL, g_pso_lmap ? &g_pso_fz : NULL, &sk); pso_skey_hex(&sk, shex);
    if (survey_shader_log()) MLOG("[survey-shader] frame %llu render pipeline %s in %.2f ms", (unsigned long long)atomic_load(&g_cur_frame), shex, (bp_now() - bt) / 1e6);
    pso_record("R\t%s\n", shex);
    pso_user_record("R\t%s\n", shex);
    hm_put_id(&g_pso, &k, ps);
    return ps;
}
static NSString *warm_key(const char *s, size_t n) {
    size_t z = strnlen(s, n);
    return [[NSString alloc] initWithBytes:s length:z encoding:NSUTF8StringEncoding];
}
static _Atomic uint64_t g_warm_missing;   // shaders named in the warm lists that are not in the translation cache (yet)
static int warm_available(NSString *key) {
    if (!key.length) return 1;
    NSFileManager *fm = NSFileManager.defaultManager;
    NSString *rt = totk_rt_dir();
    int have = [fm fileExistsAtPath:[rt stringByAppendingFormat:@"/%@.metal", key]] ||
               [fm fileExistsAtPath:[rt stringByAppendingFormat:@"/%@.metallib", key]] ||
               [fm fileExistsAtPath:[g_msl_dir stringByAppendingFormat:@"/%@.metallib", key]];
    if (!have) {
        static NSMutableSet *missing; static dispatch_once_t once;
        dispatch_once(&once, ^{ missing = [NSMutableSet set]; });
        @synchronized (missing) { if (![missing containsObject:key]) { [missing addObject:key]; g_warm_missing++; } }
    }
    return have;
}
/* One shader of the warm-up, without the per-run dictionary (safe on several threads at once). */
static NvShader *warm_shader_load(NSString *key, int stage) {
    /* A warm list may name a variant this cache does not hold (collected by another session, the cache trimmed): it is
       translated on first use like any new shader, so the warm-up skips it quietly and counts it (one line at the end)
       instead of a red "cannot open" per pipeline that names it (2026-10-16 night: 42 such lines in one session). */
    static NSMutableSet<NSString *> *missing; static dispatch_once_t once; dispatch_once(&once, ^{ missing = [NSMutableSet set]; });
    @synchronized (missing) { if ([missing containsObject:key]) return nil; }
    NSString *msl = [NSString stringWithContentsOfFile:[totk_rt_dir() stringByAppendingFormat:@"/%@.metal", key]
                                                encoding:NSUTF8StringEncoding error:nil];
    if (!msl && ![NSFileManager.defaultManager fileExistsAtPath:[totk_rt_dir() stringByAppendingFormat:@"/%@.metallib", key]] &&
        ![NSFileManager.defaultManager fileExistsAtPath:[NSString stringWithFormat:@"%@/%@.metallib", g_msl_dir, key]]) {
        @synchronized (missing) { if (![missing containsObject:key]) { [missing addObject:key]; g_warm_missing++; } }
        return nil;
    }
    if (msl && ([msl containsString:@"double "] || [msl containsString:@"unsupported_GLSLstd450"])) return nil;
    uint64_t started = bp_now();
    NvShader *sh = shader_load(key, stage);
    atomic_fetch_add(&g_warm_library_ns, bp_now() - started);
    atomic_fetch_add(&g_warm_library_count, 1);
    return sh;
}
/* Shaders whose warm-up load failed: tried once, not again for every row that names them. */
static NSMutableSet<NSString *> *g_warm_failed;
static os_unfair_lock g_warm_failed_lock = OS_UNFAIR_LOCK_INIT;
static int warm_failed(NSString *key) {
    os_unfair_lock_lock(&g_warm_failed_lock); int f = [g_warm_failed containsObject:key]; os_unfair_lock_unlock(&g_warm_failed_lock);
    return f;
}
static void warm_fail(NSString *key) {
    os_unfair_lock_lock(&g_warm_failed_lock);
    if (!g_warm_failed) g_warm_failed = [NSMutableSet set];
    [g_warm_failed addObject:key];
    os_unfair_lock_unlock(&g_warm_failed_lock);
}
static NvShader *warm_shader(NSMutableDictionary<NSString *, NvShader *> *dict, NSString *key, int stage) {
    NvShader *sh = dict[key];
    if (sh || warm_failed(key)) return sh;
    sh = warm_shader_load(key, stage);
    if (sh) dict[key] = sh; else warm_fail(key);
    return sh;
}
/* TOTK (2026-10-18): the warm-up compiles the shader libraries of each block of rows on several threads, then builds the
   pipelines of those rows one after another in list order, as before. A cold library takes about 48-92 ms, almost all of it
   in the system Metal compiler (one thread: 9,268 libraries 856 s, 3,459 pipelines under 1 s), and the compiler service runs
   requests side by side (8 threads: 188 s). That matters on a Mac whose Metal cache has never seen the prepared shaders: a
   new Mac, after the system purged the cache, or after the app moved. (Programs without an app bundle -- the game binary is
   one -- share one store, keyed by the source, the options and the length of the path of the folder the program runs
   from: rebuilding the app in the same place keeps it, moving it does not. The store evicts heavily when any such program
   compiles many new libraries, and what one compiles while another that opened it first is running is lost when that
   one quits. build_app.py compiles the seed once at packaging time from the game binary's folder, with no other program
   using the store: tools/warm_metal_cache.m.) Once the player is in the world (mtl_warm_wait returned) at most 2 threads go on, so the
   rest of the warm-up does not take the game's cores. TOTK_WARM_THREADS=<n> (1 = one thread as before); default 8 on the
   Mac (at most the core count minus 2), 1 on iOS (prebuilt libraries, nothing to compile). */
enum { WARM_BLOCK = 512 };   // rows per block: the shaders of a block load in parallel, then its rows run in order
static _Atomic int g_warm_in_play;
static int warm_threads(void) {
    static int n; static dispatch_once_t once;
    dispatch_once(&once, ^{
        const char *e = getenv("TOTK_WARM_THREADS");
#if TARGET_OS_IPHONE
        int d = 1;
#else
        int d = (int)NSProcessInfo.processInfo.activeProcessorCount - 2; if (d > 8) d = 8; if (d < 1) d = 1;
#endif
        n = e && *e ? atoi(e) : d; if (n < 1) n = 1; if (n > 32) n = 32;
    });
    return n;
}
static int warm_threads_now(void) { int n = warm_threads(); return n > 2 && atomic_load(&g_warm_in_play) ? 2 : n; }
typedef struct { _Atomic size_t next; os_unfair_lock lock; } warm_par;
/* Load the shaders named by keys / stages into dict, each once, on warm_threads_now() threads. */
static void warm_load_keys(NSArray<NSString *> *keys, NSArray<NSNumber *> *stages, NSMutableDictionary<NSString *, NvShader *> *dict) {
    NSMutableArray<NSString *> *todo = [NSMutableArray array]; NSMutableArray<NSNumber *> *st = [NSMutableArray array];
    NSMutableSet<NSString *> *want = [NSMutableSet set];
    for (NSUInteger i = 0; i < keys.count; i++) {
        NSString *k = keys[i];
        if (!k.length || dict[k] || [want containsObject:k] || warm_failed(k)) continue;
        [want addObject:k]; [todo addObject:k]; [st addObject:stages[i]];
    }
    size_t n = todo.count, workers = (size_t)warm_threads_now();
    if (!n) return;
    if (workers <= 1 || n == 1) { for (size_t i = 0; i < n; i++) @autoreleasepool { warm_shader(dict, todo[i], st[i].intValue); } return; }
    if (workers > n) workers = n;
    warm_par *wp = calloc(1, sizeof *wp); if (!wp) MDIE("预热：内存不足");
    wp->lock = OS_UNFAIR_LOCK_INIT;
    dispatch_apply(workers, dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^(size_t w) {
        for (;;) @autoreleasepool {
            if (w && w >= (size_t)warm_threads_now()) break;   // fewer threads once playing; thread 0 always goes on
            size_t i = atomic_fetch_add(&wp->next, 1);
            if (i >= n) break;
            NSString *key = todo[i];
            NvShader *sh = warm_shader_load(key, st[i].intValue);
            if (!sh) { warm_fail(key); continue; }
            os_unfair_lock_lock(&wp->lock); dict[key] = sh; os_unfair_lock_unlock(&wp->lock);
        }
    });
    free(wp);
}
/* The shaders a block of warm-list rows names (S: the shader, R: its vertex and fragment shaders, C: the compute shader). */
static void warm_load_rows(NSArray<NSString *> *rows, NSMutableDictionary<NSString *, NvShader *> *dict) {
    NSMutableArray<NSString *> *keys = [NSMutableArray array]; NSMutableArray<NSNumber *> *stages = [NSMutableArray array];
    for (NSString *line in rows) {
        NSArray<NSString *> *c = [line componentsSeparatedByString:@"\t"];
        if ([c[0] isEqualToString:@"S"] && c.count >= 3) { [keys addObject:c[1]]; [stages addObject:@(c[2].intValue)]; }
        else if ([c[0] isEqualToString:@"R"] && c.count >= 2) {
            pso_skey sk; if (pso_skey_parse(c[1].UTF8String, &sk)) continue;
            NSString *vkey = warm_key(sk.vs, sizeof sk.vs), *fkey = warm_key(sk.fs, sizeof sk.fs);
            if (vkey.length) { [keys addObject:vkey]; [stages addObject:@(sk.vs_stage)]; }
            if (fkey.length) { [keys addObject:fkey]; [stages addObject:@(sk.fs_stage)]; }
        } else if ([c[0] isEqualToString:@"C"] && c.count >= 2 && c[1].length) { [keys addObject:c[1]]; [stages addObject:@5]; }
    }
    warm_load_keys(keys, stages, dict);
}
static void warm_enqueue(WarmItem *item) {
    os_unfair_lock_lock(&g_warm_lock);
    [g_warm_items addObject:item];
    atomic_store_explicit(&g_warm_ready, 1, memory_order_release);
    os_unfair_lock_unlock(&g_warm_lock);
}
/* Count the exact manifest rows and cached variants this run will visit before
   displaying a determinate bar. Shader/PSO counts are separate: one pipeline
   row may load two shaders, and a failed row still advances the task bar. */
static void warm_plan(NSArray<NSString *> *paths, NSArray<NSString *> *files, NSMutableSet<NSString *> *keys,
                      NSMutableSet<NSString *> *eligible,
                      uint64_t *tasks, uint64_t *shaders, uint64_t *pipelines) {
    NSMutableSet<NSString *> *rows = [NSMutableSet set];
    *tasks = *shaders = *pipelines = 0;
    for (NSString *path in paths) {
        NSString *txt = [NSString stringWithContentsOfFile:path encoding:NSUTF8StringEncoding error:nil];
        for (NSString *line in [txt componentsSeparatedByString:@"\n"]) {
            if (!line.length || [line hasPrefix:@"#"] || [rows containsObject:line]) continue;
            [rows addObject:line];
            NSArray<NSString *> *c = [line componentsSeparatedByString:@"\t"];
            if ([c[0] isEqualToString:@"S"] && c.count >= 3 && [c[1] length]) {
                if (!warm_available(c[1])) continue;
                [keys addObject:c[1]];
            }
            else if ([c[0] isEqualToString:@"R"] && c.count >= 2) {
                pso_skey sk; if (pso_skey_parse(c[1].UTF8String, &sk)) continue;
                NSString *vs = warm_key(sk.vs, sizeof sk.vs), *fs = warm_key(sk.fs, sizeof sk.fs);
                // Evaluate both so the missing-shader count remains deduplicated.
                int av = warm_available(vs), af = warm_available(fs);
                if (!av || !af) continue;
                if (vs.length) [keys addObject:vs]; if (fs.length) [keys addObject:fs]; ++*pipelines;
            } else if ([c[0] isEqualToString:@"C"] && c.count >= 2 && [c[1] length]) {
                if (!warm_available(c[1])) continue;
                [keys addObject:c[1]]; ++*pipelines;
            } else continue;
            [eligible addObject:line]; ++*tasks;
        }
    }
    for (NSString *file in files) if ([file hasSuffix:@"_b.metal"]) {
        ++*tasks; [keys addObject:[file stringByDeletingPathExtension]];
    }
    *shaders = keys.count;
}
static void warm_task_done(uint64_t *done,uint64_t total,uint64_t shader_total,uint64_t pipeline_total,
                           NSDictionary<NSString *,NvShader *> *dict) {
    ++*done;
    if (!(*done % 1024) || *done == total)
        MLOG("预热进度：已处理 %llu / %llu 项，着色器 %lu / %llu，管线 %llu / %llu",
             (unsigned long long)*done,(unsigned long long)total,(unsigned long)dict.count,(unsigned long long)shader_total,
             (unsigned long long)(g_warm_rps+g_warm_cps),(unsigned long long)pipeline_total);
    if (runtime_warm_progress && (!(*done % 64) || *done == total))
        runtime_warm_progress(*done,total,dict.count,shader_total,g_warm_rps+g_warm_cps,pipeline_total);
}
static void warm_worker(NSArray<NSString *> *paths, NSArray<NSString *> *files,
                        NSSet<NSString *> *eligible,
                        NSMutableSet<NSString *> *planned_keys,uint64_t total,uint64_t shader_total,uint64_t pipeline_total) {
    @autoreleasepool {
        NSMutableDictionary<NSString *, NvShader *> *dict = [NSMutableDictionary dictionary];
        NSMutableSet<NSString *> *seen = [NSMutableSet set];
        NSUInteger path_index = 0;
        MLOG("后台预热：着色器库用 %d 个线程编（TOTK_WARM_THREADS），进世界后最多 2 个", warm_threads());
        uint64_t done = 0;
        for (NSString *path in paths) {
            NSString *txt = [NSString stringWithContentsOfFile:path encoding:NSUTF8StringEncoding error:nil];
            if (!txt) { MLOG("【红】预热清单读取失败：%s", path.UTF8String);
                if (path_index++ == 0) atomic_store(&g_warm_priority_done, 1); continue; }
            NSMutableArray<NSString *> *todo = [NSMutableArray array];
            for (NSString *line in [txt componentsSeparatedByString:@"\n"]) {
                if (![eligible containsObject:line] || [seen containsObject:line]) continue;
                [seen addObject:line]; [todo addObject:line];
            }
            for (NSUInteger at = 0; at < todo.count; at += WARM_BLOCK) @autoreleasepool {
                NSArray<NSString *> *block = [todo subarrayWithRange:NSMakeRange(at, MIN((NSUInteger)WARM_BLOCK, todo.count - at))];
                warm_load_rows(block, dict);   // the block's shaders on several threads; its pipelines below, in list order
                for (NSString *line in block) {
                    NSArray<NSString *> *c = [line componentsSeparatedByString:@"\t"];
                    if (!c.count) { warm_task_done(&done,total,shader_total,pipeline_total,dict); continue; }
                    if ([c[0] isEqualToString:@"S"] && c.count >= 3) {
                        NSString *key = c[1]; NvShader *sh = warm_shader(dict, key, c[2].intValue);
                        if (!sh) { warm_task_done(&done,total,shader_total,pipeline_total,dict); continue; }
                        WarmItem *item = [WarmItem new]; item->kind = 0; item->key = key; item->shader = sh;
                        warm_enqueue(item);
                    } else if ([c[0] isEqualToString:@"R"] && c.count >= 2) {
                        pso_skey sk; if (pso_skey_parse(c[1].UTF8String, &sk)) { warm_task_done(&done,total,shader_total,pipeline_total,dict); continue; }
                        NSString *vkey = warm_key(sk.vs, sizeof sk.vs), *fkey = warm_key(sk.fs, sizeof sk.fs);
                        NvShader *vs = vkey.length ? warm_shader(dict, vkey, sk.vs_stage) : nil;
                        NvShader *fs = fkey.length ? warm_shader(dict, fkey, sk.fs_stage) : nil;
                        if (!vs || (fkey.length && !fs)) { warm_task_done(&done,total,shader_total,pipeline_total,dict); continue; }
                        id<MTLFunction> fsfn = nil;
                        if (sk.fz) {
                            if (sk.fz_desc.kind == 1 && fs) { int fx[32]; for (int i = 0; i < 32; i++) fx[i] = sk.fz_desc.fx[i]; fsfn = bf_fn(fs, fx, sk.fz_desc.fbmask, sk.k.lmap); }
                                                    if (!fsfn) { g_warm_skip_fz++; warm_task_done(&done,total,shader_total,pipeline_total,dict); continue; }
                        }
                        pso_key k = sk.k; k.vs = (__bridge void *)vs; k.fs = (__bridge void *)fs; k.fsfn = (__bridge void *)fsfn;
                        NSError *e = nil; uint64_t ps_started = bp_now();
                        id ps = [g_dev newRenderPipelineStateWithDescriptor:pso_desc(&k, vs, fs, fsfn, sk.merged) error:&e];
                        atomic_fetch_add(&g_warm_pipeline_ns, bp_now() - ps_started); atomic_fetch_add(&g_warm_pipeline_count, 1);
                        if (!ps) { MLOG("【红】后台建渲染管线失败：%s", e.localizedDescription.UTF8String); warm_task_done(&done,total,shader_total,pipeline_total,dict); continue; }
                        WarmItem *item = [WarmItem new]; item->kind = 1; item->vs_key = vkey; item->fs_key = fkey; item->vs = vs; item->fs = fs; item->fsfn = fsfn; item->pso = k; item->object = ps;
                        warm_enqueue(item); g_warm_rps++;
                    } else if ([c[0] isEqualToString:@"C"] && c.count >= 2) {
                        NSString *key = c[1]; if (!key.length) { warm_task_done(&done,total,shader_total,pipeline_total,dict); continue; }
                        NvShader *cs = warm_shader(dict, key, 5);
                        if (!cs) { warm_task_done(&done,total,shader_total,pipeline_total,dict); continue; }
                        NSError *e = nil; uint64_t ps_started = bp_now(); id ps = [g_dev newComputePipelineStateWithFunction:cs->fn error:&e];
                        atomic_fetch_add(&g_warm_pipeline_ns, bp_now() - ps_started); atomic_fetch_add(&g_warm_pipeline_count, 1);
                        if (!ps) { MLOG("【红】后台建计算管线失败：%s", e.localizedDescription.UTF8String); warm_task_done(&done,total,shader_total,pipeline_total,dict); continue; }
                        WarmItem *item = [WarmItem new]; item->kind = 2; item->key = key; item->shader = cs; item->object = ps;
                        warm_enqueue(item); g_warm_cps++;
                    }
                    warm_task_done(&done,total,shader_total,pipeline_total,dict);
                }
            }
            if (path_index++ == 0) atomic_store(&g_warm_priority_done, 1);
        }
        atomic_store(&g_warm_priority_done, 1);
        // The native port translates variants as they are discovered. Warm every variant already
        // present in this translation-chain cache before the first playable scene is released.
        NSString *rt = totk_rt_dir();
        // Preserve variants translated while the manifest was warming. They
        // extend the measured total rather than being silently omitted.
        NSMutableArray<NSString *> *cache_files = [files mutableCopy];
        NSMutableSet<NSString *> *known_files = [NSMutableSet setWithArray:files];
        NSArray<NSString *> *latest = [[NSFileManager.defaultManager contentsOfDirectoryAtPath:rt error:nil] sortedArrayUsingSelector:@selector(compare:)];
        for (NSString *file in latest) if ([file hasSuffix:@"_b.metal"] && ![known_files containsObject:file]) {
            // The native service publishes reflection last. A newly written
            // MSL with no reflection yet is still in flight, not a failed shader.
            NSString *json = [[file stringByDeletingPathExtension] stringByAppendingPathExtension:@"json"];
            if (![NSFileManager.defaultManager fileExistsAtPath:[rt stringByAppendingPathComponent:json]]) continue;
            [known_files addObject:file]; [cache_files addObject:file]; ++total;
            NSString *key = [file stringByDeletingPathExtension];
            if (![planned_keys containsObject:key]) { [planned_keys addObject:key]; ++shader_total; }
        }
        if (runtime_warm_progress) runtime_warm_progress(done,total,dict.count,shader_total,g_warm_rps+g_warm_cps,pipeline_total);
        uint64_t cached = 0, failed = 0;
        NSMutableArray<NSString *> *lkeys = [NSMutableArray array]; NSMutableArray<NSNumber *> *lstages = [NSMutableArray array];
        for (NSString *file in cache_files) @autoreleasepool {
            if (![file hasSuffix:@"_b.metal"]) continue;
            NSString *key = [file stringByDeletingPathExtension];
            if (dict[key]) { warm_task_done(&done,total,shader_total,pipeline_total,dict); continue; }
            NSString *jp = [rt stringByAppendingPathComponent:[key stringByAppendingPathExtension:@"json"]];
            NSData *jd = [NSData dataWithContentsOfFile:jp];
            NSDictionary *j = jd ? [NSJSONSerialization JSONObjectWithData:jd options:0 error:nil] : nil;
            NSString *stage = j[@"stage"];
            int st = [stage isEqual:@"vs"] ? 0 : [stage isEqual:@"ps"] ? 1 : [stage isEqual:@"cs"] ? 5 : -1;
            if (st < 0 || ![j[@"chain"] isEqual:@DMSH_CHAIN]) { failed++; warm_task_done(&done,total,shader_total,pipeline_total,dict); continue; }
            [lkeys addObject:key]; [lstages addObject:@(st)];
        }
        for (NSUInteger at = 0; at < lkeys.count; at += WARM_BLOCK) @autoreleasepool {   // on several threads, a block at a time
            NSRange r = NSMakeRange(at, MIN((NSUInteger)WARM_BLOCK, lkeys.count - at));
            NSArray<NSString *> *block = [lkeys subarrayWithRange:r];
            warm_load_keys(block, [lstages subarrayWithRange:r], dict);
            for (NSString *key in block) {
                NvShader *sh = dict[key];
                if (!sh) { failed++; warm_task_done(&done,total,shader_total,pipeline_total,dict); continue; }
                WarmItem *item = [WarmItem new]; item->kind = 0; item->key = key; item->shader = sh;
                warm_enqueue(item); cached++;
                warm_task_done(&done,total,shader_total,pipeline_total,dict);
            }
        }
        if (runtime_warm_progress) runtime_warm_progress(done,total,dict.count,shader_total,g_warm_rps+g_warm_cps,pipeline_total);
        MLOG("缓存补充预热：新增 %llu 个着色器，%llu 个失败；清单里还不在翻译缓存的着色器 %llu 个（第一次用到时现翻，自动收集）", cached, failed, (unsigned long long)g_warm_missing);
        MLOG("管线预热完成：着色器 %llu 个 / 渲染管线 %llu 个（跳过特化片元 %llu）/ 计算管线 %llu 个，后台用时 %.1f ms（着色器库 %d 个线程%s）",
             (unsigned long long)dict.count, g_warm_rps, g_warm_skip_fz, g_warm_cps, (bp_now() - g_warm_t0) / 1e6, warm_threads(),
             atomic_load(&g_warm_in_play) && warm_threads() > 2 ? "，进世界后 2 个" : "");
        MLOG("预热分段：着色器库 %llu 次 / %.1f ms（各线程用时相加），Metal 管线 %llu 次 / %.1f ms",
             (unsigned long long)atomic_load(&g_warm_library_count),atomic_load(&g_warm_library_ns)/1e6,
             (unsigned long long)atomic_load(&g_warm_pipeline_count),atomic_load(&g_warm_pipeline_ns)/1e6);
    }
    atomic_store(&g_warm_running, 0);
    if (runtime_warm_done) runtime_warm_done();
}
// 等后台预热跑完（最多 timeout_ms；负数表示一直等）：返回实际等了多少毫秒，没在跑返回 0。首装时系统着色器缓存全冷，预热慢于玩家进局的话，
// 没预热到的管线会在提交线程现编 = 局内卡顿；进局读取画面本来就挡着玩家，让它多读一会儿（hle_nvn.c 出图处调）。
// Wait for the background warm-up to finish (at most timeout_ms): returns how many milliseconds were actually waited, 0 if it is not running. On first install the system shader cache is fully cold; if warm-up is slower than the player entering a run,
// pipelines not yet warmed are compiled on the spot on the submit thread = in-run stutter; the loading screen on entering a run blocks the player anyway, so let it load a little longer (called where hle_nvn.c presents).
int mtl_warm_wait(int timeout_ms) {
    if (!atomic_load(&g_warm_running)) return 0;
    uint64_t t0 = bp_now();
    while (atomic_load(&g_warm_running) && (timeout_ms < 0 || (bp_now() - t0) / 1000000ull < (uint64_t)timeout_ms)) usleep(2000);
    atomic_store(&g_warm_in_play, 1);   // the player goes into the world: the rest of the warm-up uses at most 2 threads
    return (int)((bp_now() - t0) / 1000000ull) + 1;
}
/* TOTK (iOS): variants the phone was missing (shader-requests/, written by totk_rt_variant) that fill_shaders.py has since
   translated and pushed are compiled once in the background at start, so their first use in play hits the system Metal
   shader cache instead of compiling on the submit thread. The results are not kept (no resident memory; the full warm-up
   stays off on the phone, about 600 MB); the request moves to shader-requests/done/. Requests still untranslated stay. */
static void warm_filled(void) {
#if TARGET_OS_IPHONE
    NSFileManager *fm = NSFileManager.defaultManager;
    NSMutableArray<NSString *> *names = [NSMutableArray array];
    for (NSString *n in [fm contentsOfDirectoryAtPath:@"shader-requests" error:nil] ?: @[]) if ([n hasSuffix:@".json"]) [names addObject:n];
    if (!names.count) return;
    dispatch_async(dispatch_get_global_queue(QOS_CLASS_UTILITY, 0), ^{
        int ok = 0, pending = 0, failed = 0; uint64_t t0 = bp_now();
        [fm createDirectoryAtPath:@"shader-requests/done" withIntermediateDirectories:YES attributes:nil error:nil];
        for (NSString *n in names) @autoreleasepool {
            NSString *variant = [n stringByDeletingPathExtension];
            if (![fm fileExistsAtPath:[totk_rt_dir() stringByAppendingFormat:@"/%@_b.metal", variant]]) { pending++; continue; }
            NSData *jd = [NSData dataWithContentsOfFile:[@"shader-requests" stringByAppendingPathComponent:n]];
            NSDictionary *rq = jd ? [NSJSONSerialization JSONObjectWithData:jd options:0 error:nil] : nil;
            NSString *sn = [rq isKindOfClass:[NSDictionary class]] ? rq[@"stage"] : nil;
            int st = [sn isEqual:@"vs"] ? 0 : [sn isEqual:@"ps"] ? 1 : [sn isEqual:@"cs"] ? 5 : -1;
            if (st < 0 || !shader_load([variant stringByAppendingString:@"_b"], st)) { failed++; continue; }
            NSString *done = [@"shader-requests/done" stringByAppendingPathComponent:n];
            [fm removeItemAtPath:done error:nil];
            [fm moveItemAtPath:[@"shader-requests" stringByAppendingPathComponent:n] toPath:done error:nil];
            ok++;
        }
        MLOG("[shader-miss] 启动预热以前缺的着色器：编好 %d 个（%.0f ms），还没在 Mac 上补的 %d 个，失败 %d 个", ok, (bp_now() - t0) / 1e6, pending, failed);
    });
#endif
}
/* TOTK (iOS): the full warm-up keeps every built pipeline (about 600 MB on the phone) and is off there, so a pipeline met
   for the first time in play is compiled on the submit thread (50-700 ms hitches while turning the camera). This light
   warm-up builds the pipelines recorded in this profile's pso_user.tsv in the background, newest first, and drops each
   one at once: the point is the system Metal shader cache (on disk, per app), so that the in-game creation becomes a
   cache hit. Libraries are kept only for a batch of rows. It runs at background priority on the title and loading
   screens only and stops at the first world frame: on the A15 (two performance cores) it doubled the replay time
   while playing (14 -> 28 ms per frame, 30 -> 20 fps). The next start goes over the list again; rows already in the
   cache take a few ms each. TOTK_WARM_LIGHT=0 turns it off. */
static _Atomic int g_world_on;   // set at the first world frame (hle_nvn.c, nvnQueuePresentTexture)
void mtl_note_world(void) { atomic_store(&g_world_on, 1); }
static void warm_light(void) {
#if TARGET_OS_IPHONE
    const char *e = getenv("TOTK_WARM_LIGHT"); if (e && !atoi(e)) return;
    NSString *path = pso_user_path();
    NSString *txt = path ? [NSString stringWithContentsOfFile:path encoding:NSUTF8StringEncoding error:nil] : nil;
    if (!txt) return;
    NSArray<NSString *> *lines = [txt componentsSeparatedByString:@"\n"];
    dispatch_async(dispatch_get_global_queue(QOS_CLASS_BACKGROUND, 0), ^{
        uint64_t t0 = bp_now(), nr = 0, nc = 0, nfail = 0, slow = 0; NSMutableSet<NSString *> *seen = [NSMutableSet set];
        NSMutableDictionary<NSString *, NvShader *> *dict = [NSMutableDictionary dictionary];
        MLOG("轻量管线预热：开始（%lu 行，最近的先编，编完即丢，只热系统缓存；TOTK_WARM_LIGHT=0 关）", (unsigned long)lines.count);
        for (NSInteger i = (NSInteger)lines.count - 1; i >= 0; i--) @autoreleasepool {
            if (atomic_load(&g_world_on)) { MLOG("轻量管线预热：进世界了，停在第 %llu 条（用时 %.1f s，现编 %llu 条；下次启动接着热）", nr + nc, (bp_now() - t0) / 1e9, slow); return; }
            NSString *line = lines[(NSUInteger)i];
            if (!line.length || [line hasPrefix:@"#"] || [seen containsObject:line]) continue;
            [seen addObject:line];
            NSArray<NSString *> *c = [line componentsSeparatedByString:@"\t"];
            uint64_t t1 = bp_now(); id ps = nil; int tried = 0;
            if ([c[0] isEqualToString:@"R"] && c.count >= 2) {
                pso_skey sk; if (pso_skey_parse(c[1].UTF8String, &sk) || sk.fz) continue;
                NSString *vkey = warm_key(sk.vs, sizeof sk.vs), *fkey = warm_key(sk.fs, sizeof sk.fs);
                NvShader *vs = vkey.length ? warm_shader(dict, vkey, sk.vs_stage) : nil, *fs = fkey.length ? warm_shader(dict, fkey, sk.fs_stage) : nil;
                if (!vs || (fkey.length && !fs)) { nfail++; continue; }
                pso_key k = sk.k; k.vs = (__bridge void *)vs; k.fs = (__bridge void *)fs; k.fsfn = NULL;
                NSError *er = nil; ps = [g_dev newRenderPipelineStateWithDescriptor:pso_desc(&k, vs, fs, nil, sk.merged) error:&er]; tried = 1; nr += ps != nil;
            } else if ([c[0] isEqualToString:@"C"] && c.count >= 2 && [c[1] length]) {
                NvShader *cs = warm_shader(dict, c[1], 5); if (!cs) { nfail++; continue; }
                NSError *er = nil; ps = [g_dev newComputePipelineStateWithFunction:cs->fn error:&er]; tried = 1; nc += ps != nil;
            }
            if (tried && !ps) nfail++;
            if (tried && bp_now() - t1 > 20000000ull) slow++;   // > 20 ms: compiled, not a cache hit
            if (dict.count > 256) [dict removeAllObjects];
            if (tried && (nr + nc) % 500 == 0 && nr + nc) MLOG("轻量管线预热：%llu 条，用时 %.1f s，其中超过 20 ms（现编）%llu 条", nr + nc, (bp_now() - t0) / 1e9, slow);
        }
        MLOG("轻量管线预热完成：渲染管线 %llu 条、计算管线 %llu 条，失败 / 缺着色器 %llu，超过 20 ms（现编）%llu 条，用时 %.1f s", nr, nc, nfail, slow, (bp_now() - t0) / 1e9);
    });
#endif
}
static void warm_start(void) {
    if (g_warm_started++) return;
    warm_filled();
    const char *e = getenv("DM_PSO_MANIFEST");
    if (e && !strcmp(e, "off")) { warm_light(); return; }
    NSArray<NSString *> *paths;
    if (e && *e) {
        paths = @[@(e)];
    } else {
        NSFileManager *fm = NSFileManager.defaultManager;
        NSString *dir = g_shmap_path.stringByDeletingLastPathComponent;
        NSString *title = [dir stringByAppendingPathComponent:@"pso_title.tsv"];
        NSString *seed = [dir stringByAppendingPathComponent:@"pso_manifest.tsv"];
        NSMutableArray<NSString *> *all = [NSMutableArray array];
        // The first list is the one the first frame waits for (g_warm_priority_done below): only what the title screen,
        // its menu and the save list use (pso_title.tsv, recorded 2026-10-18 on 1.4.3, 1.1.2 and 1.0.0; rows of another
        // version are not in this cache and are skipped like any missing row). With the
        // 8,290 prepared shaders first the title came after 7-8 s even with warm caches and after about 10 minutes on a
        // Mac whose Metal cache has never seen them. Without the title list the game's manifest goes first, as before.
        if ([fm fileExistsAtPath:title]) [all addObject:title];
        if ([fm fileExistsAtPath:seed]) [all addObject:seed];
        NSString *user = pso_user_path();
        if (user && [fm fileExistsAtPath:user]) [all addObject:user];
        NSString *shared = pso_shared_path();   // what every session collected (pso_user_record)
        if ([fm fileExistsAtPath:shared]) [all addObject:shared];
        // The selected version's prepared shaders (real MSL, also on a fresh install) come last: they are shader libraries
        // only, while the lists above also build the pipelines the first scenes need.
        const char *seedMode = getenv("TOTK_SHADER_SEED");
        NSString *prepared = [dir stringByAppendingPathComponent:@"shader-seed/pso_manifest.tsv"];
        if (!(seedMode && !strcmp(seedMode, "off")) && [fm fileExistsAtPath:prepared]) [all addObject:prepared];
        paths = all;
        NSMutableString *desc = [NSMutableString string];
        for (NSString *p in paths) { NSString *t = [NSString stringWithContentsOfFile:p encoding:NSUTF8StringEncoding error:nil];
            [desc appendFormat:@"%@%@ %lu 行", desc.length ? @"，" : @"", p.lastPathComponent, (unsigned long)[t componentsSeparatedByString:@"\n"].count - 1]; }
        MLOG("预热清单（自动着色器收集）：%s；另加翻译缓存里的全部着色器", desc.UTF8String);
    }
    if (!g_warm_items) g_warm_items = [NSMutableArray array];
    NSArray<NSString *> *files = [[NSFileManager.defaultManager contentsOfDirectoryAtPath:totk_rt_dir() error:nil] sortedArrayUsingSelector:@selector(compare:)] ?: @[];
    uint64_t total = 0, shader_total = 0, pipeline_total = 0;
    NSMutableSet<NSString *> *planned_keys = [NSMutableSet set];
    NSMutableSet<NSString *> *eligible = [NSMutableSet set];
    warm_plan(paths,files,planned_keys,eligible,&total,&shader_total,&pipeline_total);
    if (runtime_warm_progress) runtime_warm_progress(0,total,0,shader_total,0,pipeline_total);
    g_warm_t0 = bp_now();
    dispatch_queue_attr_t attr = dispatch_queue_attr_make_with_qos_class(DISPATCH_QUEUE_SERIAL, QOS_CLASS_USER_INITIATED, 0);   // 不是可有可无的后台活：它决定玩家进局前管线是否就绪 | Not optional background work: it decides whether the pipelines are ready before the player enters a run
    dispatch_queue_t q = dispatch_queue_create("dm.nvn.pso-warm", attr);
    atomic_store(&g_warm_running, 1);
    dispatch_async(q, ^{ warm_worker(paths,files,eligible,planned_keys,total,shader_total,pipeline_total); });
    // The title's list must be ready before its first frame. The other lists,
    // the prepared shaders and the remaining translated variants finish behind
    // the menu, then mtl_warm_wait at save-load waits before entering play.
    uint64_t wait_start = bp_now();
    while (!atomic_load(&g_warm_priority_done)) usleep(2000);
    int ms = (int)((bp_now() - wait_start) / 1000000ull) + 1;
    warm_claim();
    MLOG("启动关键管线已就绪：等待 %d ms，可用着色器 %lu / 渲染管线 %llu / 计算管线 %llu；其余后台继续预热",
         ms, (unsigned long)g_shcache.count, g_warm_claim_rps, g_warm_claim_cps);
}
static int g_rt_ovr;   // 运行时外推的模板覆盖：0 不覆盖；1 只在单位 / 特效 / 外推洞位（0xD0）上通过、不写模板；3 照常深度测试，通过处写特效位 0x40 | Stencil override for runtime extrapolation: 0 no override; 1 pass only on the unit / effect / extrapolation-hole bits (0xD0), no stencil write; 3 depth test as usual, write the effect bit 0x40 where it passes
static id<MTLDepthStencilState> dss_get(int has_depth, int has_stencil) {
    struct { ds_st ds; uint32_t vm[2], wm[2]; int hd, hs, ovr; } k;
    memset(&k, 0, sizeof k); k.ds = S.ds; memcpy(k.vm, S.st_vmask, 8); memcpy(k.wm, S.st_wmask, 8); k.hd = has_depth; k.hs = has_stencil; k.ovr = has_stencil ? g_rt_ovr : 0;
    if (!g_dss.klen) g_dss.klen = sizeof k;
    id<MTLDepthStencilState> s = hm_get_id(&g_dss, &k);
    if (s) return s;
    MTLDepthStencilDescriptor *d = [MTLDepthStencilDescriptor new];
    if (has_depth && S.ds.dt) { d.depthCompareFunction = (MTLCompareFunction)(S.ds.df - 1); d.depthWriteEnabled = S.ds.dw; }
    if (has_stencil && S.ds.st) {
        MTLStencilDescriptor *f = [MTLStencilDescriptor new], *b = [MTLStencilDescriptor new];
        f.stencilCompareFunction = (MTLCompareFunction)(S.ds.sf_f - 1); f.stencilFailureOperation = (MTLStencilOperation)(S.ds.fail_f - 1);
        f.depthFailureOperation = (MTLStencilOperation)(S.ds.zfail_f - 1); f.depthStencilPassOperation = (MTLStencilOperation)(S.ds.zpass_f - 1);
        f.readMask = S.st_vmask[0]; f.writeMask = S.st_wmask[0];
        b.stencilCompareFunction = (MTLCompareFunction)(S.ds.sf_b - 1); b.stencilFailureOperation = (MTLStencilOperation)(S.ds.fail_b - 1);
        b.depthFailureOperation = (MTLStencilOperation)(S.ds.zfail_b - 1); b.depthStencilPassOperation = (MTLStencilOperation)(S.ds.zpass_b - 1);
        b.readMask = S.st_vmask[1]; b.writeMask = S.st_wmask[1];
        d.frontFaceStencil = f; d.backFaceStencil = b;
    }
    if (has_stencil && k.ovr) {
        MTLStencilDescriptor *f = [MTLStencilDescriptor new];
