        MTLFunctionConstantValues *cv = [MTLFunctionConstantValues new]; float v[4] = {rgba[0], rgba[1], rgba[2], rgba[3]};
        [cv setConstantValue:v type:MTLDataTypeFloat4 atIndex:0];
