    for(int i=0;i<vs->rf.nv;i++) {
        unsigned a=vs->rf.v[i].nvn;
        if(a<16 && a<(unsigned)S.nattr && vfmt(S.attr[a].fmt)!=MTLVertexFormatInvalid && S.attr[a].stream<16)
            mask|=(uint16_t)(1u<<S.attr[a].stream);
