}
/* TOTK: back-to-back dispatches share one compute encoder. Each dispatch used to open and end a compute encoder of its own
   (about 24 per world frame, 13 of them right after another dispatch). On Metal 4 the copy encoder (g_blit) is a compute
   encoder already kept open across copies, closed wherever another encoder starts or the command buffer is committed; a
   dispatch now uses it too. Ordering stays as before: between two commands of the encoder a barrier orders blit and dispatch
   stages with device visibility (blit()), as the end / start barriers of two encoders did. The argument table is set again
   for every dispatch (copies use none, other code may set its own). Off with DM_NVN_PASSGPU (one timing slot per encoder)
   and with TOTK_DISPATCH_REUSE=0. */
static int disp_reuse_on(void) { static int v = -1; if (v < 0) { const char *e = getenv("TOTK_DISPATCH_REUSE"); v = !(e && !strcmp(e, "0")); if (!v) MLOG("TOTK_DISPATCH_REUSE=0：每次派发单开计算编码器（旧行为）"); } return v; }
static uint64_t g_disp_n, g_disp_shared;
static int g_disp_probe_nobar;   // probe-gpu-dispatch-chain negative control: no barrier between the commands of the shared encoder
static id<MTL4ComputeCommandEncoder> disp_enc(void) {
    int open = g_blit != nil;
    g_disp_n++; g_disp_shared += open;
    if (!open) { rs_sync(); ser_gate(); pt_mark(g_cb, 'C', nil); g_blit = enc_b_begin(g_cb); [g_blit barrierAfterQueueStages:MTLStageAll beforeStages:MTLStageAll visibilityOptions:bar_vis()]; }
    else if (!g_disp_probe_nobar) [g_blit barrierAfterEncoderStages:MTLStageBlit | MTLStageDispatch beforeEncoderStages:MTLStageBlit | MTLStageDispatch visibilityOptions:bar_vis()];
    [g_blit setArgumentTable:g_ct]; args_dirty_all();
    if (g_disp_n % 20000 == 0) MLOG("[nvn] 计算派发 至 %llu 次：其中 %llu 次（%.0f%%）接在已开的计算编码器里，没有另开编码器", (unsigned long long)g_disp_n, (unsigned long long)g_disp_shared, 100.0 * (double)g_disp_shared / (double)g_disp_n);
    return g_blit;
}
/* Indirect draw records (p_draw_indirect tail, Bayonetta 3): read {count, instances, first, base vertex, base instance}
   (elements) or {count, instances, first, base instance} (arrays) from memory now and write them into the record.
   A record the GPU path takes (ind_resolve) is always drawn, from the arguments resolved on the GPU timeline (g_ind_gpu);
   its record keeps the CPU view for the replay's own checks. Otherwise (TOTK_GPU_INDIRECT=0, quads, 8-bit indices)
   arguments a GPU pass of this same submission writes are seen as they are in memory at replay, usually the previous
   frame's. 0 = nothing to draw. */
static int draw_resolve(const op_hdr *h, void *rec, int indexed) {
    size_t at = indexed ? DRAW_TAIL_AT(p_draw_idx) : DRAW_TAIL_AT(p_draw);
    g_ind_gpu = 0; g_ind_cur = NULL;
    if (h->size < 8 + at + sizeof(p_draw_indirect)) return 1;
    p_draw_indirect t; memcpy(&t, (uint8_t *)rec + at, sizeof t);
    if (t.magic != DRAW_INDIRECT_MAGIC) return 1;
    uint64_t gpu = 0;
    if (ind_gpu_on() && ind_tail(indexed ? OP_DRAW_IDX : OP_DRAW, rec, h->size)) {
        uint64_t *s = ind_slot(rec, 0);
        if (!s || !*s) { ind_resolve((const uint8_t *)rec - 8); s = ind_slot(rec, 0); }
        if (s && *s) gpu = *s; else RED_ONCE(60, "BY3: an indirect draw could not be resolved on the GPU (arguments read on the CPU)");
    }
    if (!gpu && t.count_addr) { uint32_t cnt; if (g_nupd) upd_guard(t.count_addr, t.count_addr + 4); memcpy(&cnt, (const void *)(uintptr_t)t.count_addr, 4); if (t.index >= cnt) return 0; }
    if (g_nupd) upd_guard(t.args, t.args + 20);
    uint32_t v[5]; memcpy(v, (const void *)(uintptr_t)t.args, indexed ? 20 : 16);
    if (gpu) { if (!v[0]) v[0] = 3; if (!v[1]) v[1] = 1; g_ind_gpu = gpu; g_ind_cur = rec; g_ind_ibuf = t.ibuf; }   // drawn as the GPU reads it; the CPU view only feeds the replay's checks
    else if (!v[0] || !v[1]) return 0;
    if (indexed) {
        p_draw_idx *d = rec; unsigned isz = d->itype == NVN_INDEX_TYPE_UNSIGNED_BYTE ? 1 : d->itype == NVN_INDEX_TYPE_UNSIGNED_SHORT ? 2 : 4;
        d->count = (int32_t)v[0]; d->instances = (int32_t)v[1]; d->ibuf = t.ibuf + (uint64_t)v[2] * isz; d->base_vertex = (int32_t)v[3]; d->base_instance = (int32_t)v[4];
    } else {
        p_draw *d = rec; d->count = (int32_t)v[0]; d->instances = (int32_t)v[1]; d->first = (int32_t)v[2]; d->base_instance = (int32_t)v[3];
